//! The numbers this agent decides with.
//!
//! They are constants in the code rather than settings anywhere else, so the
//! reviewer reads them with the rest of the source, and the claims in
//! `shonin.toml` say the same thing in words.

/// The companies it reads: the stock token's symbol and the company's SEC
/// Central Index Key.
pub const NAMES: &[(&str, u64)] = &[("NVDA", 1_045_810), ("TSLA", 1_318_605), ("AAPL", 320_193)];

/// The SEC asks every automated reader to say who it is.
pub const USER_AGENT: &str = "Shonin catalyst agent (contact: agents@shonin.fi)";
/// How often each company's filings are read, in seconds: well inside the
/// SEC's fair-access limit of ten requests a second.
pub const READ_EVERY: u64 = 300;

/// The model's name in the bundle, and the score at which it buys.
pub const MODEL: &str = "scorer";
pub const BUY_SCORE: &str = "0.60";

/// Each position at most this much of the vault, and all of them together
/// at most `MAX_EXPOSURE`.
pub const MAX_ORDER_FRACTION: &str = "0.05";
pub const MAX_EXPOSURE: &str = "0.30";
/// Held at most this long, in seconds, and closed sooner after this fall
/// from its entry price.
pub const HOLD_FOR: u64 = 86_400;
pub const STOP_LOSS: &str = "0.03";
/// How far from the price seen a swap may fill.
pub const SLIPPAGE: &str = "0.01";
/// Below this, an order is not worth what it costs.
pub const MINIMUM_NOTIONAL: &str = "25";
/// 6% of the vault kept liquid.
pub const IDLE_BUFFER: &str = "0.06";

//! The SEC's EDGAR filings: free, public, and published as they are
//! accepted. Each company's recent filings are one JSON document at
//! `data.sec.gov/submissions/CIK##########.json`.

use serde_json::Value;

/// One current report (Form 8-K) as the SEC lists it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Report {
    pub accession: String,
    /// When EDGAR accepted it, as the SEC writes it (ISO 8601, US Eastern).
    pub accepted: String,
    /// The report's item numbers, such as `2.02` (results of operations).
    pub items: Vec<String>,
}

/// The path of a company's submissions document.
pub fn path(cik: u64) -> String {
    format!("/submissions/CIK{cik:010}.json")
}

/// The 8-Ks among a company's recent filings, newest first.
pub fn current_reports(document: &Value) -> Vec<Report> {
    let recent = &document["filings"]["recent"];
    let column = |name: &str| recent[name].as_array().cloned().unwrap_or_default();
    let (forms, accessions, accepted, items) = (
        column("form"),
        column("accessionNumber"),
        column("acceptanceDateTime"),
        column("items"),
    );
    forms
        .iter()
        .enumerate()
        .filter(|(_, form)| form.as_str() == Some("8-K"))
        .filter_map(|(i, _)| {
            Some(Report {
                accession: accessions.get(i)?.as_str()?.to_string(),
                accepted: accepted.get(i)?.as_str().unwrap_or_default().to_string(),
                items: items
                    .get(i)
                    .and_then(|v| v.as_str())
                    .unwrap_or_default()
                    .split(',')
                    .map(|item| item.trim().to_string())
                    .filter(|item| !item.is_empty())
                    .collect(),
            })
        })
        .collect()
}

/// GET `https://data.sec.gov{path}` through the host's `wasi:http`, with
/// the User-Agent the SEC asks for.
#[cfg(target_arch = "wasm32")]
pub fn get(path: &str, user_agent: &str) -> Result<Value, String> {
    use strategy_sdk::http::outgoing_handler;
    use strategy_sdk::http::types::{Fields, Method, OutgoingRequest, Scheme};

    let headers = Fields::new();
    headers
        .append("user-agent", user_agent.as_bytes())
        .map_err(|e| format!("{e:?}"))?;
    headers
        .append("accept", b"application/json")
        .map_err(|e| format!("{e:?}"))?;
    let request = OutgoingRequest::new(headers);
    request.set_method(&Method::Get).map_err(|_| "method")?;
    request
        .set_scheme(Some(&Scheme::Https))
        .map_err(|_| "scheme")?;
    request
        .set_authority(Some("data.sec.gov"))
        .map_err(|_| "authority")?;
    request
        .set_path_with_query(Some(path))
        .map_err(|_| "path")?;
    let pending = outgoing_handler::handle(request, None).map_err(|e| format!("{e:?}"))?;
    pending.subscribe().block();
    let response = pending
        .get()
        .ok_or("no response")?
        .map_err(|_| "response taken twice")?
        .map_err(|e| format!("{e:?}"))?;
    if response.status() != 200 {
        return Err(format!("the SEC answered {}", response.status()));
    }
    let body = response.consume().map_err(|_| "no body")?;
    let stream = body.stream().map_err(|_| "no body stream")?;
    let mut bytes = Vec::new();
    loop {
        match stream.blocking_read(64 * 1024) {
            Ok(chunk) => bytes.extend_from_slice(&chunk),
            Err(strategy_sdk::bindings::wasi::io::streams::StreamError::Closed) => break,
            Err(e) => return Err(format!("{e:?}")),
        }
        if bytes.len() > 8 * 1024 * 1024 {
            return Err("the document is too large".into());
        }
    }
    serde_json::from_slice(&bytes).map_err(|e| e.to_string())
}

/// Off WebAssembly (the agent's tests), there is no host to ask.
#[cfg(not(target_arch = "wasm32"))]
pub fn get(_path: &str, _user_agent: &str) -> Result<Value, String> {
    Err("no host".into())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_current_reports_are_read_with_their_items() {
        let document = serde_json::json!({"filings": {"recent": {
            "form": ["10-Q", "8-K", "4", "8-K"],
            "accessionNumber": ["a", "b", "c", "d"],
            "acceptanceDateTime": ["t1", "t2", "t3", "t4"],
            "items": ["", "2.02,9.01", "", "5.02"]
        }}});
        let reports = current_reports(&document);
        assert_eq!(reports.len(), 2);
        assert_eq!(reports[0].accession, "b");
        assert_eq!(reports[0].items, vec!["2.02", "9.01"]);
        assert_eq!(reports[1].items, vec!["5.02"]);
    }

    #[test]
    fn a_companys_document_is_named_by_its_ten_digit_key() {
        assert_eq!(path(1_045_810), "/submissions/CIK0001045810.json");
    }
}

//! Reads company filings as they are published, scores them, and trades the
//! stock token on the news.
//!
//! Every few minutes it reads the SEC's list of each company's recent
//! filings. A current report (Form 8-K) it hasn't seen is turned into eight
//! numbers (`score.rs`) and scored by the bundle's model through the host's
//! inference service; if the model can't be run, the same placeholder score
//! is computed here instead. A strong score buys a bounded amount of the
//! company's stock token through the `robinhood` driver; every position is
//! sold after a day, or sooner after a fall from its entry.
//!
//! The model is a placeholder, and the manifest says so. Its limits are in
//! `config.rs`, and the manifest claims them in the same words.

mod config;
mod edgar;
mod score;
mod venues;

use std::collections::{BTreeMap, BTreeSet};

use futures::StreamExt;
use sdk::inference::{self, NamedTensor, Tensor, TensorData};
use sdk::streams::{self, CHAINLINK, ChainlinkFeed, ChainlinkValue};
use sdk::transfers::{self, Account, Moved, VenueAccount};
use sdk::{Decimal, Verdict, decimal, drivers, from_payload, millionths, to_payload, vault};
use strategy_sdk as sdk;
use venues::robinhood as rh;

struct Catalyst;

/// A position the agent opened: when, and at what price.
struct Entry {
    at: u64,
    price: Decimal,
}

struct Mind {
    /// Every report already read, so each is acted on once.
    seen: BTreeSet<String>,
    entries: BTreeMap<String, Entry>,
    last_read: u64,
    /// The first read only learns what is already out: old news is not
    /// traded.
    primed: bool,
}

fn now() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|since| since.as_secs())
        .unwrap_or(0)
}

fn zero() -> Decimal {
    Decimal::from(0)
}

impl sdk::Agent for Catalyst {
    async fn run() -> Result<(), String> {
        let mut mind = Mind {
            seen: BTreeSet::new(),
            entries: BTreeMap::new(),
            last_read: 0,
            primed: false,
        };
        // The feeds' rounds are the agent's clock: each wakes it to look at
        // its filings and its positions.
        let mut ticks = Vec::new();
        for (token, _) in config::NAMES {
            ticks.push(streams::subscribe::<_, ChainlinkValue>(
                CHAINLINK,
                &ChainlinkFeed::Price {
                    token: token.to_string(),
                },
            )?);
        }
        let ticks = futures::stream::select_all(ticks).map(|_| None);
        let vault_events = vault::events().into_stream().map(Some);
        let mut waking = futures::stream::select(ticks, vault_events);
        step(&mut mind).await?;
        while let Some(woke) = waking.next().await {
            match woke {
                Some(vault::VaultEvent::Halting(_)) => {
                    for (token, _) in config::NAMES {
                        sell_all(token).await?;
                    }
                    return Ok(());
                }
                Some(vault::VaultEvent::BufferLow(short)) => {
                    let _ = transfers::move_(venue(), Account::Vault, short).await;
                }
                _ => step(&mut mind).await?,
            }
        }
        Ok(())
    }
}

fn venue() -> Account {
    Account::Venue(VenueAccount {
        chain: transfers::home_chain(),
        driver: rh::DRIVER.to_string(),
    })
}

async fn state<Q: serde::Serialize, A: serde::de::DeserializeOwned>(
    query: &Q,
) -> Result<A, String> {
    from_payload(&drivers::account_state(rh::DRIVER.to_string(), to_payload(query)).await?)
}

async fn submit(action: &rh::Action) -> bool {
    let verdicts = drivers::submit(rh::DRIVER.to_string(), vec![to_payload(action)]).await;
    matches!(verdicts.first(), Some(Verdict::Accepted(_)))
}

async fn vault_value() -> (Decimal, Decimal) {
    let balances = transfers::balances().await;
    let dollars = |amount: u64| Decimal::from(amount) / Decimal::from(1_000_000u32);
    let total = balances.iter().map(|b| b.amount).sum::<u64>();
    let cash = balances
        .iter()
        .find(|b| matches!(b.account, Account::Vault))
        .map(|b| b.amount)
        .unwrap_or(0);
    (dollars(total), dollars(cash))
}

/// Read new filings, act on any strong one, and close what is due.
async fn step(mind: &mut Mind) -> Result<(), String> {
    let prices: Vec<rh::TokenPrice> = state(&rh::Query::Prices).await?;
    let holdings: rh::AccountState = state(&rh::Query::Holdings).await?;
    let price_of = |token: &str| prices.iter().find(|p| p.token == token);
    let held_of = |token: &str| {
        holdings
            .holdings
            .iter()
            .find(|h| h.token == token)
            .map(|h| h.tokens)
            .unwrap_or_else(zero)
    };

    // Close what is due: a day old, or past the stop.
    for (token, _) in config::NAMES {
        let held = held_of(token);
        let Some(price) = price_of(token) else {
            continue;
        };
        if held <= zero() {
            mind.entries.remove(*token);
            continue;
        }
        // A position this instance didn't open (a restart) is timed from now.
        let entry = mind.entries.entry(token.to_string()).or_insert(Entry {
            at: now(),
            price: price.market_price,
        });
        let stopped =
            price.market_price <= entry.price * (Decimal::from(1u8) - decimal(config::STOP_LOSS));
        if now() >= entry.at + config::HOLD_FOR || stopped {
            sell_all(token).await?;
        }
    }

    if now() < mind.last_read + config::READ_EVERY {
        return Ok(());
    }
    mind.last_read = now();
    for (token, cik) in config::NAMES {
        let document = match edgar::get(&edgar::path(*cik), config::USER_AGENT) {
            Ok(document) => document,
            // The SEC not answering is a quiet minute, not a fault.
            Err(_) => continue,
        };
        for report in edgar::current_reports(&document).into_iter().take(10) {
            if !mind.seen.insert(report.accession.clone()) || !mind.primed {
                continue;
            }
            let score = score_of(&report).await;
            let strong = score >= decimal(config::BUY_SCORE) && held_of(token) <= zero();
            if let (true, Some(price)) = (strong, price_of(token)) {
                buy(token, price).await?;
                mind.entries.insert(
                    token.to_string(),
                    Entry {
                        at: now(),
                        price: price.market_price,
                    },
                );
            }
        }
    }
    mind.primed = true;
    Ok(())
}

/// The model's score for a report, or the same placeholder computed here
/// if the model can't be run (not in the bundle, over its budget).
async fn score_of(report: &edgar::Report) -> Decimal {
    let features = score::features(report);
    let input = NamedTensor {
        name: "features".to_string(),
        tensor: Tensor {
            shape: vec![1, 8],
            data: TensorData::Float32(features.to_vec()),
        },
    };
    let scored = match inference::infer(config::MODEL.to_string(), vec![input]).await {
        Ok(outputs) => outputs
            .into_iter()
            .find_map(|named| match named.tensor.data {
                TensorData::Float32(values) => values.first().copied(),
                _ => None,
            }),
        Err(_) => None,
    };
    let score = scored.unwrap_or_else(|| score::written_down(&features));
    // Two decimal places are all a score is read to.
    Decimal::from((score.clamp(0.0, 1.0) * 100.0).round() as u32) / Decimal::from(100u32)
}

/// Buy one order's worth of `token`, within every limit.
async fn buy(token: &str, price: &rh::TokenPrice) -> Result<(), String> {
    if price.paused || price.market_price <= zero() {
        return Ok(());
    }
    let (value, cash) = vault_value().await;
    let holdings: rh::AccountState = state(&rh::Query::Holdings).await?;
    let exposure = holdings
        .holdings
        .iter()
        .map(|h| h.tokens * h.feed_price)
        .fold(zero(), |a, b| a + b);
    let room = value * decimal(config::MAX_EXPOSURE) - exposure;
    let dollars = (value * decimal(config::MAX_ORDER_FRACTION)).min(room);
    if dollars < decimal(config::MINIMUM_NOTIONAL) {
        return Ok(());
    }
    // The dollars go to the Safe first, the buffer staying home.
    if holdings.dollars < dollars {
        let keep = value * decimal(config::IDLE_BUFFER);
        let short = dollars - holdings.dollars;
        if cash - keep < short {
            return Ok(());
        }
        if !matches!(
            transfers::move_(Account::Vault, venue(), millionths(short)).await,
            Moved::Done
        ) {
            return Ok(());
        }
    }
    let one = Decimal::from(1u8);
    submit(&rh::Action::Buy {
        token: token.to_string(),
        amount: dollars,
        min_tokens: dollars / price.market_price * (one - decimal(config::SLIPPAGE)),
    })
    .await;
    Ok(())
}

/// Sell every token of `token` the Safe holds.
async fn sell_all(token: &str) -> Result<(), String> {
    let prices: Vec<rh::TokenPrice> = state(&rh::Query::Prices).await?;
    let holdings: rh::AccountState = state(&rh::Query::Holdings).await?;
    let (Some(price), Some(held)) = (
        prices.iter().find(|p| p.token == token),
        holdings.holdings.iter().find(|h| h.token == token),
    ) else {
        return Ok(());
    };
    let one = Decimal::from(1u8);
    submit(&rh::Action::Sell {
        token: token.to_string(),
        tokens: held.tokens,
        min_amount: held.tokens * price.market_price * (one - decimal(config::SLIPPAGE)),
    })
    .await;
    Ok(())
}

sdk::export_agent!(Catalyst);

//! What a report's items say, as the model's eight inputs, and the same
//! placeholder score written down, for when the model can't be run.
//!
//! The model is a placeholder: a fixed linear score of which items a report
//! carries (`sigmoid(features · WEIGHTS + BIAS)`), not trained on anything.
//! The weights are here so a reviewer can read exactly what it does.

use crate::edgar::Report;

/// Results of operations, a material agreement, a departure or appointment
/// of officers, other events, Regulation FD, non-reliance on earlier
/// statements, an impairment, and whether the report came outside the
/// market's hours.
pub const ITEMS: [&str; 7] = ["2.02", "1.01", "5.02", "8.01", "7.01", "4.02", "2.06"];
pub const WEIGHTS: [f32; 8] = [0.8, 0.5, -0.6, 0.3, 0.2, -0.4, 0.1, 0.05];
pub const BIAS: f32 = -0.1;

/// The model's input: one for each item the report carries, then whether it
/// was accepted outside the market's hours (Eastern, 9:30 to 16:00).
pub fn features(report: &Report) -> [f32; 8] {
    let mut features = [0f32; 8];
    for (i, item) in ITEMS.iter().enumerate() {
        if report.items.iter().any(|carried| carried == item) {
            features[i] = 1.0;
        }
    }
    features[7] = if after_hours(&report.accepted) {
        1.0
    } else {
        0.0
    };
    features
}

/// `2026-10-05T16:05:12.000Z`-style times as EDGAR writes them (Eastern).
fn after_hours(accepted: &str) -> bool {
    let Some(time) = accepted.split('T').nth(1) else {
        return false;
    };
    let mut parts = time.split(':');
    let (Some(hour), Some(minute)) = (parts.next(), parts.next()) else {
        return false;
    };
    let (Ok(hour), Ok(minute)) = (hour.parse::<u32>(), minute.parse::<u32>()) else {
        return false;
    };
    let minutes = hour * 60 + minute;
    !(570..960).contains(&minutes)
}

/// The placeholder's score, computed here.
pub fn written_down(features: &[f32; 8]) -> f32 {
    let z: f32 = features
        .iter()
        .zip(WEIGHTS)
        .map(|(x, w)| x * w)
        .sum::<f32>()
        + BIAS;
    1.0 / (1.0 + (-z).exp())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn report(items: &[&str], accepted: &str) -> Report {
        Report {
            accession: "x".into(),
            accepted: accepted.into(),
            items: items.iter().map(|s| s.to_string()).collect(),
        }
    }

    #[test]
    fn results_after_the_close_score_high_and_a_restatement_low() {
        let results = written_down(&features(&report(
            &["2.02", "9.01"],
            "2026-10-05T16:30:00.000Z",
        )));
        assert!(results > 0.6, "{results}");
        let restated = written_down(&features(&report(
            &["4.02", "5.02"],
            "2026-10-05T10:00:00.000Z",
        )));
        assert!(restated < 0.35, "{restated}");
    }

    #[test]
    fn an_unknown_item_scores_nothing_and_the_hours_are_read_as_eastern() {
        let f = features(&report(&["9.01"], "2026-10-05T12:00:00.000Z"));
        assert_eq!(f, [0.0; 8]);
        assert_eq!(features(&report(&[], "2026-10-05T09:29:00.000Z"))[7], 1.0);
        assert_eq!(features(&report(&[], "2026-10-05T09:30:00.000Z"))[7], 0.0);
    }
}

//! What this agent says to its two drivers, and hears back: the
//! `robinhood` driver's payloads (stock tokens in the station's Safe) and
//! the `lighter` driver's (the station's Lighter account).
//!
//! These are the drivers' own published payload types, copied verbatim (the
//! same names, fields and serde attributes, so they encode to the same
//! canonical CBOR). They move to the SDK beside Hyperliquid's; this file then
//! becomes two `use` lines.

#![allow(dead_code)]

pub mod robinhood {
    use serde::{Deserialize, Serialize};
    pub use strategy_sdk::Decimal;

    /// The driver's name, as `shonin.toml` writes it.
    pub const DRIVER: &str = "robinhood";

    /// The dollar's symbol: USDG, the chain's native dollar.
    pub const DOLLAR: &str = "USDG";

    /// What a strategy submits.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Action {
        /// Spend `amount` of the dollar on stock token `token`, receiving at
        /// least `min_tokens`.
        Buy {
            token: String,
            amount: Decimal,
            min_tokens: Decimal,
        },
        /// Sell `tokens` of stock token `token` for at least `min_amount`
        /// dollars.
        Sell {
            token: String,
            tokens: Decimal,
            min_amount: Decimal,
        },
    }

    /// What came back inside an accepted verdict.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Receipt {
        /// The swap landed: what was spent and what came back.
        Swapped {
            token: String,
            spent: Decimal,
            received: Decimal,
            transaction: String,
        },
    }

    /// What `account-state` is asked.
    #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Query {
        /// The Safe's holdings, priced.
        Holdings,
        /// Every listed token's prices: its feed's and its pool's.
        Prices,
    }

    /// One listed token's prices, as `Query::Prices` answers.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct TokenPrice {
        pub token: String,
        /// Chainlink's price for the token (the multiplier already applied).
        pub feed_price: Decimal,
        /// When the feed last moved, in seconds since the Unix epoch.
        pub feed_updated_at: u64,
        /// What the token's pool says, averaged over the driver's window.
        pub market_price: Decimal,
        /// Shares of the underlying per token.
        pub multiplier: Decimal,
        /// The issuer has paused the token's oracle.
        pub paused: bool,
    }

    /// One stock token the Safe holds.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct Holding {
        pub token: String,
        /// In shares of the token (its own units, not multiplied: the
        /// multiplier only matters for what a share is a claim on).
        pub tokens: Decimal,
        /// The token's Chainlink price, which already applies the multiplier.
        pub feed_price: Decimal,
        /// When the feed last moved, in seconds since the Unix epoch.
        pub feed_updated_at: u64,
        /// Shares of the underlying per token, from the token's multiplier:
        /// for display, never for valuing.
        pub multiplier: Decimal,
    }

    /// What `account-state` answers.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct AccountState {
        /// The Safe's address.
        pub safe: String,
        /// Idle dollars in the Safe.
        pub dollars: Decimal,
        pub holdings: Vec<Holding>,
    }

    /// Something that happened to the Safe, read from the chain.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum AccountEvent {
        /// Tokens moved into or out of the Safe: a swap, a deposit, a close.
        Moved {
            token: String,
            /// Positive when the Safe received.
            amount: Decimal,
            transaction: String,
            block: u64,
        },
    }
}

pub mod lighter {
    use serde::{Deserialize, Serialize};
    pub use strategy_sdk::Decimal;

    /// The driver's name, as `shonin.toml` writes it.
    pub const DRIVER: &str = "lighter";

    #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Side {
        Buy,
        Sell,
    }

    /// How long an order stands.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Tif {
        /// Added to the book only, never taking.
        PostOnly,
        /// Stands until `expiry_ms` (Lighter allows up to 28 days) or a cancel.
        GoodTill { expiry_ms: u64 },
        /// Immediate or cancel, at the limit price or better.
        Ioc,
    }

    /// An order on one perp market, by its symbol (`SPY`, `NVDA`).
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct Order {
        pub market: String,
        pub side: Side,
        /// In units of the underlying (shares, coins).
        pub size: Decimal,
        pub limit_price: Decimal,
        pub tif: Tif,
        /// Only ever shrinks a position, never past flat.
        pub reduce_only: bool,
        /// The agent's own id for the order (1 to 2^48 - 1), so it can cancel it
        /// before it knows the venue's.
        pub client_id: Option<u64>,
    }

    /// Which order: the venue's index, or the agent's own id.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum OrderRef {
        Venue(u64),
        Client(u64),
    }

    /// What a strategy submits.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Action {
        Place(Order),
        Cancel {
            market: String,
            order: OrderRef,
        },
        /// Change a resting order's size and price.
        Modify {
            market: String,
            order: OrderRef,
            size: Decimal,
            limit_price: Decimal,
        },
        /// Cancel every resting order on the account.
        CancelAll,
    }

    /// What came back inside an accepted verdict.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Receipt {
        /// The exchange took the transaction; what it did with it arrives as
        /// account events.
        Sent { tx_hash: String },
    }

    /// What `account-state` is asked.
    #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Query {
        Account,
    }

    /// One perp position.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct Position {
        pub market: String,
        /// Positive is long.
        pub size: Decimal,
        pub entry_price: Decimal,
        pub unrealized_pnl: Decimal,
    }

    /// What `account-state` answers: the station's master account.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct AccountState {
        pub account_index: u64,
        /// The account's worth at the mark.
        pub equity: Decimal,
        /// What it could withdraw or put up as margin now.
        pub available: Decimal,
        pub positions: Vec<Position>,
    }

    /// Something that happened to the account, as the venue reported it.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum AccountEvent {
        Filled {
            market: String,
            side: Side,
            size: Decimal,
            price: Decimal,
            time_ms: u64,
        },
        Order {
            market: String,
            order_index: u64,
            client_id: Option<u64>,
            status: String,
            time_ms: u64,
        },
        Funding {
            market: String,
            /// Positive when the account was paid.
            amount: Decimal,
            time_ms: u64,
        },
    }
}

//! The numbers this agent decides with.
//!
//! They are constants in the code rather than settings anywhere else, so the
//! reviewer reads them with the rest of the source, and the claims in
//! `shonin.toml` say the same thing in words.

/// The spot pair held long, as the driver names it, and the venue's own
/// name for its book.
pub const SPOT: &str = "HYPE/USDC";
pub const SPOT_BOOK: &str = "@107";
/// The token the spot leg is held in.
pub const SPOT_TOKEN: &str = "HYPE";
/// Size decimals the venue allows on the spot pair.
pub const SPOT_SIZE_DECIMALS: u32 = 2;
/// The perpetual shorted against it, and its size decimals.
pub const PERP: &str = "HYPE";
pub const PERP_SIZE_DECIMALS: u32 = 2;
/// The HYPE the account keeps for its sends home, which the strategy never
/// sells. Every send of dollars from HyperCore back to the vault costs the
/// account a little HYPE, and the executor buys it from the account's own
/// dollars, never past one HYPE in all. The strategy can't tell that HYPE
/// from its own spot leg, so it leaves the most the executor may hold.
pub const HYPE_KEPT_FOR_SENDS_HOME: &str = "1";
/// The leverage the perp leg is held at: cross margin, and low, since the
/// spot leg is the hedge and the perp only needs to survive the basis.
pub const PERP_LEVERAGE: u32 = 2;

/// Funding, as a fraction of notional per day, at which carrying is worth it.
pub const ENTRY_FUNDING: &str = "0.0002";
/// And at which an open carry is unwound.
pub const EXIT_FUNDING: &str = "0.00005";
/// How much of the vault to aim to have working.
pub const TARGET_DEPLOYMENT: &str = "0.80";
/// Below this, an order is not worth the spread it would pay (and the venue
/// refuses anything under ten dollars).
pub const MINIMUM_NOTIONAL: &str = "100";
/// How far past the best price an immediate order may reach, as a fraction.
pub const SLIPPAGE: &str = "0.002";
/// How far short of its target the carry, or the money behind it at the
/// venue, may fall before anything is done about it, as a fraction of the
/// target. Drift inside it is not worth the transactions it would take.
pub const REBALANCE_BAND: &str = "0.10";

/// Gross exposure at most twice the vault's value.
pub const MAX_GROSS_LEVERAGE: &str = "2";
/// No single order above 5% of the vault.
pub const MAX_ORDER_FRACTION: &str = "0.05";
/// 6% of the vault kept liquid, so an ordinary withdrawal closes nothing:
/// a little above the vault's own 5% idle floor, which it never moves past.
pub const IDLE_BUFFER: &str = "0.06";
/// Only reduces after a 10% fall from the vault's peak.
pub const DRAWDOWN_STOP: &str = "0.10";

//! What the strategy wants to do, worked out from what it can see.
//!
//! Everything here is arithmetic on the account and the latest quotes: no
//! host call, nothing sent. The program around it reads the account, asks
//! what to do, and does it, which is what lets the tests below pin down when
//! the strategy spends gas and when it doesn't.
//!
//! Orders and moves between the account's own perp and spot balances are
//! signed actions on HyperCore and cost no gas. Bringing money from the
//! vault does: a pull and a deposit on HyperEVM, paid from the vault's tank.
//! So the account is funded for the whole carry in one move, counting what
//! is already outside the vault's cash, and only when an order can follow;
//! dollars already waiting in the station go in first.

use hl::{AccountEvent, AccountState, Order, Side, Tif};
use strategy_sdk::hyperliquid as hl;
use strategy_sdk::{Decimal, Limits, decimal, from_payload, size_for};

use crate::config;

/// The limits in `config.rs`, as numbers.
pub fn limits() -> Limits {
    Limits {
        max_gross_leverage: decimal(config::MAX_GROSS_LEVERAGE),
        max_order_fraction: decimal(config::MAX_ORDER_FRACTION),
        idle_buffer: decimal(config::IDLE_BUFFER),
        drawdown_stop: decimal(config::DRAWDOWN_STOP),
    }
}

pub fn zero() -> Decimal {
    Decimal::from(0)
}

fn positive(value: Decimal) -> Decimal {
    if value > zero() { value } else { zero() }
}

fn cap(size: Decimal, most: Decimal) -> Decimal {
    if size > most { most } else { size }
}

/// The first of the fewest equal orders, none above `most`, that add up to
/// `size`.
fn in_equal_orders(size: Decimal, most: Decimal) -> Decimal {
    if size <= most || most <= zero() {
        return cap(size, most);
    }
    size / (size / most).ceil()
}

/// The most of `price` an order may be for: its share of the vault, priced at
/// the furthest the order may fill, so even a fill at the slippage limit stays
/// inside the cap.
pub fn order_size_cap(limits: &Limits, state: &AccountState, price: Decimal) -> Decimal {
    state.vault_value * limits.max_order_fraction
        / (price * (Decimal::from(1) + decimal(config::SLIPPAGE)))
}

/// The best bid and ask of one leg, as last heard.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Top {
    pub bid: Option<Decimal>,
    pub ask: Option<Decimal>,
}

/// What the strategy knows of the market: both legs' books and the funding.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Quotes {
    pub spot: Top,
    pub perp: Top,
    /// Funding, as a fraction of notional per day.
    pub funding: Option<Decimal>,
}

/// The legs as the account holds them: spot tokens, and the perp position
/// (negative when short).
pub fn held(state: &AccountState) -> (Decimal, Decimal) {
    let spot = state
        .spot
        .iter()
        .find(|balance| balance.token == config::SPOT_TOKEN)
        .map_or_else(zero, |balance| balance.total);
    let perp = state
        .positions
        .iter()
        .find(|position| position.market == config::PERP)
        .map_or_else(zero, |position| position.size);
    (spot, perp)
}

/// The dollars on the account's spot side that no order holds.
pub fn spot_dollars(state: &AccountState) -> Decimal {
    state
        .spot
        .iter()
        .find(|balance| balance.token == "USDC")
        .map_or_else(zero, |balance| balance.total - balance.hold)
}

/// `size` rounded down to `decimals` places.
pub fn round_down(size: Decimal, decimals: u32) -> Decimal {
    let scale = Decimal::from(10u64.pow(decimals));
    (size * scale).floor() / scale
}

/// `amount` rounded up to whole cents.
pub fn round_up_cents(amount: Decimal) -> Decimal {
    let scale = Decimal::from(100);
    (amount * scale).ceil() / scale
}

/// An immediate-or-cancel order, its limit written as the venue takes it.
pub fn order(market: &str, side: Side, size: Decimal, limit: Decimal, reduce_only: bool) -> Order {
    Order {
        market: market.to_string(),
        side,
        size,
        limit_price: five_figures(limit, side),
        tif: Tif::Ioc,
        reduce_only,
        client_id: None,
    }
}

/// A price at five significant figures, the most the venue takes, rounded
/// away from the market (down for a buy, up for a sell) so it never reaches
/// further than meant.
pub fn five_figures(price: Decimal, side: Side) -> Decimal {
    if price <= zero() {
        return price;
    }
    let mut scale = Decimal::from(1);
    let ten = Decimal::from(10);
    while price * scale < Decimal::from(10_000) {
        scale *= ten;
    }
    while price * scale >= Decimal::from(100_000) {
        scale /= ten;
    }
    let scaled = price * scale;
    let rounded = match side {
        Side::Buy => scaled.floor(),
        Side::Sell => scaled.ceil(),
    };
    rounded / scale
}

/// Dollars to bring to the account before trading. Each part is one move:
/// the station's idle dollars in one deposit, the vault's cash in a pull and
/// a deposit.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Funding {
    pub from_station: Decimal,
    pub from_vault: Decimal,
}

/// What to do now.
#[derive(Clone, Debug, PartialEq)]
pub enum Plan {
    /// Nothing would move the carry far enough to be worth doing.
    Nothing,
    /// Fund the account as `fund` says, buy `spot` if there is one, then
    /// short the perpetual to match what the spot holds (see [`hedge`]).
    Build { fund: Funding, spot: Option<Order> },
    /// Buy back `perp` if there is one, then sell the spot down to what is
    /// still short (see [`trim`]).
    Reduce { perp: Option<Order> },
}

/// Which side of the funding thresholds the market is on.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Regime {
    /// Worth opening.
    Open,
    /// Worth holding, not adding to.
    Hold,
    /// Worth unwinding.
    Exit,
}

pub fn regime(funding: Decimal) -> Regime {
    if funding >= decimal(config::ENTRY_FUNDING) {
        Regime::Open
    } else if funding < decimal(config::EXIT_FUNDING) {
        Regime::Exit
    } else {
        Regime::Hold
    }
}

/// Whether a funding update is worth looking at the account for.
///
/// The venue sends one every few seconds. When the last look found nothing
/// to do and the funding is on the same side of its thresholds, nothing it
/// says can change the answer; the account's own events (fills, the hourly
/// funding payment) still wake the strategy whatever the funding does.
pub fn steps_on_funding(before: Option<Decimal>, now: Decimal, busy: bool) -> bool {
    busy || before.map(regime) != Some(regime(now))
}

/// Whether an event on the account is worth looking at it for. An order's
/// change of state says nothing a fill doesn't: an order that filled sends
/// its fill too, and one cancelled unfilled changed nothing.
pub fn wakes_for(event: &[u8]) -> bool {
    !matches!(
        from_payload::<AccountEvent>(event),
        Ok(AccountEvent::Order { .. })
    )
}

/// Whether the vault has fallen far enough from its peak that this strategy
/// should stop opening anything and only get smaller.
pub fn only_reducing(peak: Decimal, value: Decimal, limits: &Limits) -> bool {
    peak > zero() && (peak - value) / peak >= limits.drawdown_stop
}

/// What both legs are worth at the prices they would close at.
pub fn gross(state: &AccountState, quotes: &Quotes) -> Decimal {
    let (spot, perp) = held(state);
    legs_gross(quotes, spot, perp)
}

/// What the legs would be worth at those prices, held as `spot` and `perp`.
fn legs_gross(quotes: &Quotes, spot: Decimal, perp: Decimal) -> Decimal {
    let spot_price = quotes.spot.ask.unwrap_or_else(zero);
    let perp_price = quotes.perp.bid.unwrap_or_else(zero);
    positive(spot) * spot_price + positive(-perp) * perp_price
}

/// Work out what to do, given the account, the market, the most the vault
/// has been worth, and the vault's cash that leavers are waiting on (see
/// [`Leavers`]).
pub fn decide(
    limits: &Limits,
    peak: Decimal,
    for_leavers: Decimal,
    state: &AccountState,
    quotes: &Quotes,
) -> Plan {
    let Some(funding) = quotes.funding else {
        return Plan::Nothing;
    };
    let (spot, perp) = held(state);
    let holding = spot > zero() || perp < zero();
    let reducing = only_reducing(peak, state.vault_value, limits);

    if holding && (reducing || regime(funding) == Regime::Exit) {
        let perp_order = unwind(limits, state, quotes);
        if perp_order.is_none() && trim(limits, state, quotes, spot, perp).is_none() {
            return Plan::Nothing;
        }
        return Plan::Reduce { perp: perp_order };
    }
    if reducing {
        return Plan::Nothing;
    }
    // A leg that didn't fill last time may have left the two sides apart.
    // They are levelled before anything is added: buying more spot while
    // some is still unhedged would only grow a position with a view on the
    // price.
    if hedge(limits, state, quotes, spot, perp).is_some() {
        return Plan::Build {
            fund: Funding::default(),
            spot: None,
        };
    }
    if regime(funding) == Regime::Open
        && let Some((fund, spot_order)) = build_step(limits, for_leavers, state, quotes)
    {
        return Plan::Build {
            fund,
            spot: Some(spot_order),
        };
    }
    Plan::Nothing
}

/// The notional of each leg of the next pair: half what is still wanted,
/// since a pair adds both legs to the gross, inside the order cap and the
/// leverage ceiling.
pub fn pair_notional(
    wanted: Decimal,
    vault_value: Decimal,
    gross: Decimal,
    limits: &Limits,
    minimum: Decimal,
) -> Decimal {
    let two = Decimal::from(2);
    let per_leg = size_for(wanted / two, vault_value, gross, limits, minimum);
    let headroom = positive(vault_value * limits.max_gross_leverage - gross) / two;
    let per_leg = cap(per_leg, headroom);
    if per_leg < minimum { zero() } else { per_leg }
}

/// The dollars one dollar of pair takes from the account: the spot paid in
/// full at its limit, and the short's margin at its leverage.
fn dollars_per_dollar() -> Decimal {
    Decimal::from(1)
        + decimal(config::SLIPPAGE)
        + Decimal::from(1) / Decimal::from(config::PERP_LEVERAGE)
}

/// The next pair's spot leg, and what has to reach the account first to pay
/// for it; nothing if the carry is close enough to its target, or if the
/// order couldn't be paid for even after moving what may be moved.
fn build_step(
    limits: &Limits,
    for_leavers: Decimal,
    state: &AccountState,
    quotes: &Quotes,
) -> Option<(Funding, Order)> {
    let (Some(spot_ask), Some(perp_bid)) = (quotes.spot.ask, quotes.perp.bid) else {
        return None;
    };
    if spot_ask <= zero() || perp_bid <= zero() || state.vault_value <= zero() {
        return None;
    }
    let minimum = decimal(config::MINIMUM_NOTIONAL);
    let band = decimal(config::REBALANCE_BAND);
    let working = state.vault_value * decimal(config::TARGET_DEPLOYMENT);
    let gross = gross(state, quotes);
    let wanted = positive(working - gross);
    if wanted < working * band {
        return None;
    }
    let per_leg = pair_notional(wanted, state.vault_value, gross, limits, minimum);
    if per_leg <= zero() {
        return None;
    }

    let fund = funding_for(limits, for_leavers, state, per_leg);
    let available = positive(spot_dollars(state))
        + positive(state.withdrawable)
        + fund.from_station
        + fund.from_vault;
    let notional = cap(per_leg, available / dollars_per_dollar());
    let size = round_down(
        cap(notional / spot_ask, order_size_cap(limits, state, spot_ask)),
        config::SPOT_SIZE_DECIMALS,
    );
    if size * spot_ask < minimum {
        // No order can follow, so nothing is moved either.
        return None;
    }
    let reach = Decimal::from(1) + decimal(config::SLIPPAGE);
    Some((
        fund,
        order(config::SPOT, Side::Buy, size, spot_ask * reach, false),
    ))
}

/// What to bring to the account before buying `per_leg` of spot.
///
/// The account is meant to hold the whole carry at target: the spot leg paid
/// in full and the short's notional again as its margin, which is the
/// deployment target of the vault. Every dollar outside the vault's cash
/// counts towards it, including any waiting in the station. Money is moved
/// only when the next pair couldn't be paid without it, or when the account
/// is short of that by more than the band, and then the whole shortfall goes
/// in one move rather than an order's worth at a time: the station's idle
/// dollars first, then the vault's cash. The vault's cash that leavers are
/// waiting on, `for_leavers`, is never part of it.
pub fn funding_for(
    limits: &Limits,
    for_leavers: Decimal,
    state: &AccountState,
    per_leg: Decimal,
) -> Funding {
    let goal = state.vault_value * decimal(config::TARGET_DEPLOYMENT);
    let outside = positive(state.vault_value - state.idle);
    let short_of_goal = positive(goal - outside);
    let available = positive(spot_dollars(state)) + positive(state.withdrawable);
    let needed_now = positive(per_leg * dollars_per_dollar() - available);
    if needed_now <= zero() && short_of_goal < goal * decimal(config::REBALANCE_BAND) {
        return Funding::default();
    }
    // A move too small to place an order with is not worth its gas.
    let worth = |amount: Decimal| {
        if amount < decimal(config::MINIMUM_NOTIONAL) {
            zero()
        } else {
            amount
        }
    };
    // What waits in the station earns nothing there, and it takes one
    // deposit however much of it goes, so all of it goes.
    let from_station = worth(positive(state.station_idle));
    // The buffer stays in the vault, where a withdrawal reaches it without
    // closing anything, and so does what leavers are waiting on.
    let spare =
        positive(state.idle - state.vault_value * limits.idle_buffer - positive(for_leavers));
    // The shortfall from the goal already counts the station's dollars; the
    // next pair's needs don't.
    let still = if short_of_goal > needed_now - from_station {
        short_of_goal
    } else {
        positive(needed_now - from_station)
    };
    let from_vault = worth(cap(still, spare));
    Funding {
        from_station,
        from_vault,
    }
}

/// The perpetual order that brings the short level with `spot_held`, as long
/// as the gap is worth an order: a sale when the spot is ahead, a reduce-only
/// purchase when the short is. A gap wider than one order is closed in equal
/// orders, so the last of it is never a sliver too small to send.
pub fn hedge(
    limits: &Limits,
    state: &AccountState,
    quotes: &Quotes,
    spot_held: Decimal,
    perp_held: Decimal,
) -> Option<Order> {
    let minimum = decimal(config::MINIMUM_NOTIONAL);
    let slip = decimal(config::SLIPPAGE);
    let one = Decimal::from(1);
    let gap = round_down(spot_held, config::PERP_SIZE_DECIMALS) + perp_held;
    if gap > zero() {
        let bid = quotes.perp.bid.filter(|bid| *bid > zero())?;
        let gross = legs_gross(quotes, spot_held, perp_held);
        let headroom = positive(state.vault_value * limits.max_gross_leverage - gross);
        let size = round_down(
            cap(
                in_equal_orders(gap, order_size_cap(limits, state, bid)),
                headroom / bid,
            ),
            config::PERP_SIZE_DECIMALS,
        );
        (size * bid >= minimum)
            .then(|| order(config::PERP, Side::Sell, size, bid * (one - slip), false))
    } else if gap < zero() && perp_held < zero() {
        let ask = quotes.perp.ask.filter(|ask| *ask > zero())?;
        let size = round_down(
            in_equal_orders(cap(-gap, -perp_held), order_size_cap(limits, state, ask)),
            config::PERP_SIZE_DECIMALS,
        );
        (size * ask >= minimum)
            .then(|| order(config::PERP, Side::Buy, size, ask * (one + slip), true))
    } else {
        None
    }
}

/// One order's worth of the short bought back, if there is a short.
pub fn unwind(limits: &Limits, state: &AccountState, quotes: &Quotes) -> Option<Order> {
    let (_, perp) = held(state);
    let ask = quotes.perp.ask.filter(|ask| *ask > zero())?;
    if perp >= zero() {
        return None;
    }
    let size = round_down(
        cap(-perp, order_size_cap(limits, state, ask)),
        config::PERP_SIZE_DECIMALS,
    );
    let slip = decimal(config::SLIPPAGE);
    (size > zero()).then(|| {
        order(
            config::PERP,
            Side::Buy,
            size,
            ask * (Decimal::from(1) + slip),
            true,
        )
    })
}

/// The spot sale that brings the spot down to what is still short. Closing
/// the spot ahead of the short would leave a naked short. The account keeps
/// some of the same token to pay for its sends home, and that is not the
/// strategy's to sell: [`config::HYPE_KEPT_FOR_SENDS_HOME`] always stays,
/// however much is sold around it. A remainder too small to be worth an
/// order stays too.
pub fn trim(
    limits: &Limits,
    state: &AccountState,
    quotes: &Quotes,
    spot_held: Decimal,
    perp_held: Decimal,
) -> Option<Order> {
    let bid = quotes.spot.bid.filter(|bid| *bid > zero())?;
    let sellable = positive(spot_held - decimal(config::HYPE_KEPT_FOR_SENDS_HOME));
    let excess = cap(spot_held + perp_held, sellable);
    if excess <= zero() {
        return None;
    }
    let size = round_down(
        cap(excess, order_size_cap(limits, state, bid)),
        config::SPOT_SIZE_DECIMALS,
    );
    let slip = decimal(config::SLIPPAGE);
    (size * bid >= decimal(config::MINIMUM_NOTIONAL)).then(|| {
        order(
            config::SPOT,
            Side::Sell,
            size,
            bid * (Decimal::from(1) - slip),
            false,
        )
    })
}

/// The vault's cash that leavers are waiting on, as far as the strategy can
/// tell.
///
/// A withdrawal the vault's cash can't cover waits for the next valuation,
/// and `buffer-low` says so: the agent brings the shortfall home from the
/// account. Until a valuation pays the leavers, everything the vault then
/// holds above its buffer is theirs, and moving it back out would only send
/// it on a round trip at the tank's expense. The vault's cash falling by
/// more than the agent itself took out is the leavers being paid, and it
/// frees what was held for them by as much.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Leavers {
    held: Decimal,
    last_idle: Option<Decimal>,
}

impl Leavers {
    /// Cash has been brought home for leavers, and the vault now looks like
    /// `state`.
    pub fn brought_home(&mut self, limits: &Limits, state: &AccountState) {
        self.held = positive(state.idle - state.vault_value * limits.idle_buffer);
        self.last_idle = Some(state.idle);
    }

    /// The vault's cash as read now.
    pub fn seen(&mut self, idle: Decimal) {
        if let Some(last) = self.last_idle
            && idle < last
        {
            self.held = positive(self.held - (last - idle));
        }
        self.last_idle = Some(idle);
    }

    /// The agent asked to take `amount` out of the vault's cash, which is not
    /// a leaver being paid. Counted whether or not it went, which at worst
    /// holds the leavers' cash a little longer.
    pub fn taken(&mut self, amount: Decimal) {
        if let Some(last) = &mut self.last_idle {
            *last -= amount;
        }
    }

    /// What is held for them now.
    pub fn held(&self) -> Decimal {
        self.held
    }
}

/// What the account looked like when the venue or the station last said no:
/// what only the strategy's own actions, a deposit or a withdrawal change.
#[derive(Clone, Debug, PartialEq)]
pub struct Snapshot {
    spot: Decimal,
    perp: Decimal,
    spot_dollars: Decimal,
    withdrawable: Decimal,
    idle: Decimal,
    station_idle: Decimal,
}

impl Snapshot {
    pub fn of(state: &AccountState) -> Self {
        let (spot, perp) = held(state);
        Self {
            spot,
            perp,
            spot_dollars: spot_dollars(state),
            withdrawable: state.withdrawable,
            idle: state.idle,
            station_idle: state.station_idle,
        }
    }
}

/// The most wake-ups a refusal is waited out for.
const PATIENCE_MOST: u32 = 64;

/// How long to leave a plan the venue or the station refused: a number of
/// wake-ups that doubles with each refusal in a row, up to
/// [`PATIENCE_MOST`], and ends at once when the account changes. It counts
/// events rather than time, so the agent still never sleeps on a timer.
#[derive(Debug, Default)]
pub struct Patience {
    refused_at: Option<Snapshot>,
    strikes: u32,
    waiting: u32,
}

impl Patience {
    /// Whether to hold back now, with the account as it is.
    pub fn holds_back(&mut self, now: &Snapshot) -> bool {
        match &self.refused_at {
            Some(then) if then == now => {
                if self.waiting > 0 {
                    self.waiting -= 1;
                    true
                } else {
                    false
                }
            }
            Some(_) => {
                *self = Self::default();
                false
            }
            None => false,
        }
    }

    /// The plan made with the account at `at` was refused.
    pub fn refused(&mut self, at: Snapshot) {
        self.strikes = if self.refused_at.as_ref() == Some(&at) {
            self.strikes + 1
        } else {
            1
        };
        self.waiting = (1u32 << self.strikes.min(6)).min(PATIENCE_MOST) - 1;
        self.refused_at = Some(at);
    }

    /// Something went through: the next plan is tried at once.
    pub fn went_through(&mut self) {
        *self = Self::default();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use hl::{Position, SpotBalance};

    fn d(text: &str) -> Decimal {
        decimal(text)
    }

    const ABOVE_ENTRY: &str = "0.001";
    const BELOW_EXIT: &str = "0.00001";

    fn quotes(funding: &str) -> Quotes {
        let top = Top {
            bid: Some(d("24.99")),
            ask: Some(d("25.01")),
        };
        Quotes {
            spot: top,
            perp: top,
            funding: Some(d(funding)),
        }
    }

    /// A vault with `idle` in its own cash and `perp_side` dollars on the
    /// account's perp side, nothing open.
    fn state(idle: &str, perp_side: &str) -> AccountState {
        let mut state = AccountState {
            vault_value: zero(),
            idle: d(idle),
            station_idle: zero(),
            account_value: d(perp_side),
            withdrawable: d(perp_side),
            positions: Vec::new(),
            spot: vec![
                SpotBalance {
                    token: "USDC".to_string(),
                    total: zero(),
                    hold: zero(),
                },
                SpotBalance {
                    token: config::SPOT_TOKEN.to_string(),
                    total: zero(),
                    hold: zero(),
                },
            ],
            open_orders: Vec::new(),
        };
        revalue(&mut state);
        state
    }

    fn balance<'a>(state: &'a mut AccountState, token: &str) -> &'a mut SpotBalance {
        state
            .spot
            .iter_mut()
            .find(|balance| balance.token == token)
            .unwrap()
    }

    fn revalue(state: &mut AccountState) {
        let (spot, _) = held(state);
        state.vault_value = state.idle
            + state.station_idle
            + state.account_value
            + spot_dollars(state)
            + spot * d("25");
    }

    fn perp_size(state: &mut AccountState) -> &mut Decimal {
        if state.positions.is_empty() {
            state.positions.push(Position {
                market: config::PERP.to_string(),
                size: zero(),
                entry_price: None,
                leverage: config::PERP_LEVERAGE,
            });
        }
        &mut state.positions[0].size
    }

    /// Fill `order` at the quote, and keep the account's books the way the
    /// venue does: the spot paid from the spot side's dollars, the short's
    /// margin held on the perp side.
    fn fill(state: &mut AccountState, order: &Order) {
        let margin = Decimal::from(config::PERP_LEVERAGE);
        match (order.market.as_str(), order.side) {
            (config::SPOT, Side::Buy) => {
                balance(state, "USDC").total -= order.size * d("25.01");
                balance(state, config::SPOT_TOKEN).total += order.size;
            }
            (config::SPOT, Side::Sell) => {
                balance(state, "USDC").total += order.size * d("24.99");
                balance(state, config::SPOT_TOKEN).total -= order.size;
            }
            (_, Side::Sell) => {
                *perp_size(state) -= order.size;
                state.withdrawable -= order.size * d("25") / margin;
            }
            (_, Side::Buy) => {
                *perp_size(state) += order.size;
                state.withdrawable += order.size * d("25") / margin;
            }
        }
        revalue(state);
    }

    /// Carry `plan` out as the agent would, counting what costs gas (a
    /// deposit for a move from the station, a pull and a deposit for one from
    /// the vault) apart from the actions on the venue, which don't.
    fn carry_out(state: &mut AccountState, plan: &Plan) -> (usize, usize) {
        let limits = limits();
        let quotes = quotes(ABOVE_ENTRY);
        let (mut gas, mut actions) = (0, 0);
        match plan {
            Plan::Nothing => {}
            Plan::Build { fund, spot } => {
                if fund.from_station > zero() {
                    state.station_idle -= fund.from_station;
                    state.account_value += fund.from_station;
                    state.withdrawable += fund.from_station;
                    gas += 1;
                }
                if fund.from_vault > zero() {
                    state.idle -= fund.from_vault;
                    state.account_value += fund.from_vault;
                    state.withdrawable += fund.from_vault;
                    gas += 2;
                }
                if let Some(order) = spot {
                    let cost = order.size * order.limit_price;
                    let short = cost - spot_dollars(state);
                    if short > zero() {
                        let moving = round_up_cents(short);
                        state.withdrawable -= moving;
                        state.account_value -= moving;
                        balance(state, "USDC").total += moving;
                        actions += 1;
                    }
                    fill(state, order);
                    actions += 1;
                }
                for _ in 0..8 {
                    let (spot, perp) = held(state);
                    let Some(order) = hedge(&limits, state, &quotes, spot, perp) else {
                        break;
                    };
                    fill(state, &order);
                    actions += 1;
                }
            }
            Plan::Reduce { perp } => {
                if let Some(order) = perp {
                    fill(state, order);
                    actions += 1;
                }
                let (spot, perp) = held(state);
                if let Some(order) = trim(&limits, state, &quotes, spot, perp) {
                    fill(state, &order);
                    actions += 1;
                }
            }
        }
        (gas, actions)
    }

    fn plan(state: &AccountState, quotes: &Quotes) -> Plan {
        decide(&limits(), state.vault_value, zero(), state, quotes)
    }

    fn settle(state: &mut AccountState) -> (usize, usize) {
        let quotes = quotes(ABOVE_ENTRY);
        let (mut gas, mut actions) = (0, 0);
        for _ in 0..100 {
            let next = plan(state, &quotes);
            if next == Plan::Nothing {
                return (gas, actions);
            }
            let (g, a) = carry_out(state, &next);
            gas += g;
            actions += a;
        }
        panic!("the agent never settled");
    }

    #[test]
    fn a_deposit_is_brought_to_the_venue_in_one_move() {
        let mut state = state("25000", "0");
        let Plan::Build { fund, .. } = plan(&state, &quotes(ABOVE_ENTRY)) else {
            panic!("a fresh deposit with funding above entry opens");
        };
        assert_eq!(fund.from_vault, d("20000"));
        let (gas, _) = settle(&mut state);
        assert_eq!(gas, 2, "one pull and one deposit");
        let (spot, perp) = held(&state);
        assert_eq!(spot, -perp, "the legs are level");
        let target = state.vault_value * d(config::TARGET_DEPLOYMENT);
        let gross = gross(&state, &quotes(ABOVE_ENTRY));
        assert!(gross >= target * d("0.9") && gross <= target, "{gross}");
    }

    #[test]
    fn a_quiet_market_sends_nothing() {
        let mut state = state("25000", "0");
        settle(&mut state);
        for _ in 0..1000 {
            state.account_value += d("0.01");
            state.withdrawable += d("0.01");
            revalue(&mut state);
            assert_eq!(plan(&state, &quotes(ABOVE_ENTRY)), Plan::Nothing);
        }
    }

    #[test]
    fn cash_already_at_the_venue_is_used_before_more_is_moved() {
        let state = state("2000", "23000");
        let Plan::Build { fund, spot } = plan(&state, &quotes(ABOVE_ENTRY)) else {
            panic!("it opens");
        };
        assert_eq!(fund, Funding::default());
        assert!(spot.is_some());
    }

    #[test]
    fn nothing_is_moved_when_no_order_could_follow() {
        let mut state = state("1500", "50");
        state.vault_value = d("25000");
        assert_eq!(plan(&state, &quotes(ABOVE_ENTRY)), Plan::Nothing);
    }

    #[test]
    fn funding_updates_on_the_same_side_of_the_thresholds_do_not_wake_an_idle_agent() {
        let above = d(ABOVE_ENTRY);
        assert!(steps_on_funding(None, above, false));
        assert!(!steps_on_funding(Some(above), above * d("1.1"), false));
        assert!(steps_on_funding(Some(above), d("0.0001"), false));
        assert!(steps_on_funding(Some(above), above, true));
    }

    #[test]
    fn an_order_changing_state_does_not_wake_it_but_a_fill_does() {
        let changed = strategy_sdk::to_payload(&AccountEvent::Order {
            market: config::PERP.to_string(),
            order_id: 1,
            client_id: None,
            status: "canceled".to_string(),
            time_ms: 0,
        });
        assert!(!wakes_for(&changed));
        let paid = strategy_sdk::to_payload(&AccountEvent::Funding {
            market: config::PERP.to_string(),
            amount: d("1"),
            time_ms: 0,
        });
        assert!(wakes_for(&paid));
    }

    #[test]
    fn an_unwind_never_sells_spot_ahead_of_the_short() {
        let mut state = state("5000", "20000");
        settle(&mut state);
        let exit = quotes(BELOW_EXIT);
        let Plan::Reduce { perp: Some(perp) } = plan(&state, &exit) else {
            panic!("funding below exit unwinds");
        };
        let (spot, short) = held(&state);
        assert_eq!(trim(&limits(), &state, &exit, spot, short), None);
        let spot_order = trim(&limits(), &state, &exit, spot, short + perp.size).unwrap();
        assert_eq!(spot_order.size, perp.size);
    }

    #[test]
    fn a_little_of_the_token_kept_for_sends_home_is_never_sold() {
        let mut state = state("15000", "10000");
        balance(&mut state, config::SPOT_TOKEN).total = d("0.5");
        revalue(&mut state);
        assert_eq!(plan(&state, &quotes(BELOW_EXIT)), Plan::Nothing);
    }

    /// The executor keeps up to a whole HYPE on the account to pay for
    /// sends home. However much spot an unwind or a halt sells, that much is
    /// left: the strategy can't tell it from its own, so it never sells it.
    #[test]
    fn the_hype_kept_for_sends_home_is_never_sold() {
        // The short is bought back; the account holds the carry's 9 HYPE and
        // the 0.1 HYPE the executor bought for sends home.
        let mut state = state("1000", "5000");
        balance(&mut state, config::SPOT_TOKEN).total = d("9.1");
        revalue(&mut state);
        let exit = quotes(BELOW_EXIT);
        let kept = d(config::HYPE_KEPT_FOR_SENDS_HOME);
        let order = trim(&limits(), &state, &exit, d("9.1"), zero()).expect("a sale");
        assert_eq!(order.size, d("9.1") - kept);

        // A halt lifts the order cap and sells everything it may, in one go.
        let halt = Limits {
            max_order_fraction: Decimal::from(1),
            ..limits()
        };
        balance(&mut state, config::SPOT_TOKEN).total = d("40");
        revalue(&mut state);
        let order = trim(&halt, &state, &exit, d("40"), zero()).expect("a sale");
        assert_eq!(order.size, d("40") - kept);
        // And with only the reserve left, nothing is sold.
        assert_eq!(trim(&halt, &state, &exit, kept, zero()), None);
    }

    /// Every order the strategy sends, filled at the furthest its slippage
    /// lets it, is still no more than 5% of the vault, as the manifest
    /// claims: the spot buys while building, the shorts that hedge them, the
    /// short bought back and the spot sold on the way out.
    #[test]
    fn an_order_filled_at_its_slippage_limit_is_never_above_its_share_of_the_vault() {
        let limits = limits();
        let open = quotes(ABOVE_ENTRY);
        let reach = Decimal::from(1) + d(config::SLIPPAGE);
        let within = |state: &AccountState, order: &Order| {
            let cap = state.vault_value * d(config::MAX_ORDER_FRACTION);
            let top = if order.market == config::SPOT {
                open.spot
            } else {
                open.perp
            };
            let price = match order.side {
                Side::Buy => top.ask.unwrap(),
                // A sale fills at the bid or below; the bid itself is the
                // most it is worth.
                Side::Sell => top.bid.unwrap(),
            };
            let furthest = order.size * price * reach;
            assert!(
                furthest <= cap,
                "{order:?} could fill at {furthest} of a {cap} cap"
            );
        };
        let mut state = state("100000", "0");
        let mut orders = 0;
        for _ in 0..40 {
            let next = plan(&state, &open);
            if let Plan::Build {
                spot: Some(order), ..
            } = &next
            {
                within(&state, order);
                let mut after = state.clone();
                balance(&mut after, "USDC").total += d("100000");
                fill(&mut after, order);
                let (spot, perp) = held(&after);
                within(&state, &hedge(&limits, &state, &open, spot, perp).unwrap());
                orders += 2;
            }
            if next == Plan::Nothing {
                break;
            }
            carry_out(&mut state, &next);
        }
        assert!(orders > 0);
        let exit = quotes(BELOW_EXIT);
        let Plan::Reduce { perp: Some(perp) } = plan(&state, &exit) else {
            panic!("funding below exit unwinds");
        };
        within(&state, &perp);
        let (spot, short) = held(&state);
        within(
            &state,
            &trim(&limits, &state, &exit, spot, short + perp.size).unwrap(),
        );
    }

    /// A spot buy whose short missed leaves the vault with a view on the
    /// price. The next step shorts against it before buying anything more,
    /// and keeps shorting, an order at a time, until the two legs are level.
    #[test]
    fn spot_left_without_its_short_is_hedged_before_more_is_bought() {
        // 500 HYPE ($12,500, two and a half orders' worth) bought in a
        // $100,000 vault; its short missed.
        let mut state = state("50000", "37500");
        balance(&mut state, config::SPOT_TOKEN).total = d("500");
        revalue(&mut state);
        let first = plan(&state, &quotes(ABOVE_ENTRY));
        let Plan::Build { fund, spot: None } = &first else {
            panic!("more spot is bought on top of an unhedged 500 HYPE: {first:?}");
        };
        assert_eq!(*fund, Funding::default(), "nothing is moved to hedge");
        let (gas, actions) = carry_out(&mut state, &first);
        assert_eq!((gas, actions), (0, 3), "three orders, each inside the cap");
        let (spot, perp) = held(&state);
        assert_eq!(spot, -perp);
    }

    /// Dollars waiting in the station earn nothing there. They go to the
    /// account first, in one deposit, and only the rest comes from the
    /// vault's cash.
    #[test]
    fn money_waiting_in_the_station_goes_on_before_any_more_is_pulled() {
        let mut state = state("15000", "0");
        state.station_idle = d("10000");
        revalue(&mut state);
        let Plan::Build { fund, .. } = plan(&state, &quotes(ABOVE_ENTRY)) else {
            panic!("it opens");
        };
        assert_eq!(fund.from_station, d("10000"));
        assert_eq!(fund.from_vault, d("10000"));
        let (gas, _) = settle(&mut state);
        assert_eq!(gas, 3, "one deposit from the station, one pull and deposit");
        assert_eq!(state.station_idle, zero());
    }

    /// `buffer-low` brings cash home from the account for leavers waiting on
    /// a valuation. Until the valuation pays them, that cash stays in the
    /// vault however far the carry is from its target.
    #[test]
    fn cash_brought_home_for_leavers_is_not_sent_back_out() {
        // A $25,000 vault with nothing open, and $20,000 just brought home
        // for leavers.
        let home = state("25000", "0");
        let mut leavers = Leavers::default();
        leavers.brought_home(&limits(), &home);
        let decided = |state: &AccountState, leavers: &Leavers| {
            decide(
                &limits(),
                state.vault_value,
                leavers.held(),
                state,
                &quotes(ABOVE_ENTRY),
            )
        };
        assert_eq!(decided(&home, &leavers), Plan::Nothing);

        // A valuation pays them, and the vault's cash falls by as much.
        leavers.seen(d("1500"));
        assert_eq!(leavers.held(), zero());
        let deposit = state("25000", "0");
        leavers.seen(deposit.idle);
        let Plan::Build { fund, .. } = decided(&deposit, &leavers) else {
            panic!("a deposit after the leavers are paid is put to work");
        };
        assert_eq!(fund.from_vault, d("20000"));
    }

    #[test]
    fn a_refusal_is_not_resent_on_every_event() {
        let at = Snapshot::of(&state("25000", "0"));
        let mut patience = Patience::default();
        let mut tried = 0;
        for _ in 0..200 {
            if !patience.holds_back(&at) {
                tried += 1;
                patience.refused(at.clone());
            }
        }
        assert!((4..=8).contains(&tried), "{tried} tries in 200 wake-ups");
    }

    #[test]
    fn prices_keep_five_figures_and_never_reach_further_than_meant() {
        assert_eq!(five_figures(d("22.51234"), Side::Buy), d("22.512"));
        assert_eq!(five_figures(d("22.51234"), Side::Sell), d("22.513"));
        assert_eq!(five_figures(d("2710.55"), Side::Buy), d("2710.5"));
        assert_eq!(five_figures(d("123456"), Side::Sell), d("123460"));
    }

    #[test]
    fn sizes_round_down_to_the_venues_decimals() {
        assert_eq!(round_down(d("1.239"), 2), d("1.23"));
        assert_eq!(round_down(d("7"), 0), d("7"));
    }
}

//! Holds spot, shorts the perpetual against it, and collects the funding, on
//! Hyperliquid.
//!
//! The same strategy as `funding-basis`, on the venue it was meant for: both
//! legs in one HyperCore account that the vault's station owns. The account
//! is the station's, so the agent's key can trade it and move dollars
//! between its own perp and spot balances, and nothing else.
//!
//! Prices and funding come from Shonin's shared Hyperliquid stream; the
//! account comes from the driver. The agent keeps the latest book of each
//! leg as they arrive, and takes one step towards what it wants to hold when
//! funding crosses a threshold or its account changes, if that step is worth
//! doing (`decide.rs` says when it is). It never polls.

mod config;
mod decide;

use decide::{
    Leavers, Patience, Plan, Quotes, Snapshot, Top, hedge, held, limits, spot_dollars, trim, unwind,
};
use futures::StreamExt;
use hl::{AccountState, Action, Balance, Order, Receipt, Side};
use sdk::streams::{self, HYPERLIQUID, HyperliquidFeed, HyperliquidValue};
use sdk::transfers::{self, Account, Moved, VenueAccount};
use sdk::{Decimal, Limits, drivers, from_payload, millionths, to_payload, vault};
use strategy_sdk as sdk;
use strategy_sdk::hyperliquid as hl;

/// The driver this agent trades through, as its manifest names it.
const DRIVER: &str = hl::DRIVER;

/// How many steps a halt may take to flatten the book before leaving the
/// rest to the contract.
const FLATTEN_STEPS: usize = 32;

/// How many perpetual orders one step may send to level the short with the
/// spot. One is almost always enough; more are for a gap wider than the
/// order cap, or an order that only partly filled.
const HEDGE_ORDERS: usize = 8;

struct FundingBasis;

/// What the strategy knows. Rebuilt from the venue and the stream whenever
/// it starts, so losing it to a restart costs a moment and nothing else.
struct Mind {
    limits: Limits,
    quotes: Quotes,
    /// The most the vault has been worth while this instance watched it.
    peak: Decimal,
    /// Whether the perp's leverage has been set since this instance began.
    levered: bool,
    /// Whether the last look found something to do, so the next funding
    /// update is worth another.
    busy: bool,
    /// How long to leave a plan the venue or the station refused.
    patience: Patience,
    /// The vault's cash that leavers are waiting on. Lost to a restart, which
    /// at worst sends it out once more for the next `buffer-low` to bring
    /// back.
    leavers: Leavers,
}

impl Mind {
    fn new() -> Self {
        Self {
            limits: limits(),
            quotes: Quotes::default(),
            peak: decide::zero(),
            levered: false,
            busy: false,
            patience: Patience::default(),
            leavers: Leavers::default(),
        }
    }
}

/// What woke the strategy up.
enum Woke {
    Venue(Vec<u8>),
    Vault(vault::VaultEvent),
    SpotBook(Top),
    PerpBook(Top),
    Funding(Decimal),
    /// A stream value that didn't read: ignored.
    Nothing,
}

fn top_of(value: Result<streams::Stamped<HyperliquidValue>, String>) -> Option<Top> {
    match value.ok()?.value {
        HyperliquidValue::Book(book) => Some(Top {
            bid: book.bids.first().map(|level| level.price),
            ask: book.asks.first().map(|level| level.price),
        }),
        _ => None,
    }
}

impl sdk::Agent for FundingBasis {
    async fn run() -> Result<(), String> {
        let mut mind = Mind::new();

        let spot_book = streams::subscribe::<_, HyperliquidValue>(
            HYPERLIQUID,
            &HyperliquidFeed::Book {
                coin: config::SPOT_BOOK.into(),
            },
        )?
        .map(|value| top_of(value).map_or(Woke::Nothing, Woke::SpotBook));
        let perp_book = streams::subscribe::<_, HyperliquidValue>(
            HYPERLIQUID,
            &HyperliquidFeed::Book {
                coin: config::PERP.into(),
            },
        )?
        .map(|value| top_of(value).map_or(Woke::Nothing, Woke::PerpBook));
        let funding = streams::subscribe::<_, HyperliquidValue>(
            HYPERLIQUID,
            &HyperliquidFeed::Funding {
                coin: config::PERP.into(),
            },
        )?
        .map(|value| match value.map(|stamped| stamped.value) {
            Ok(HyperliquidValue::Funding(funding)) => {
                Woke::Funding(funding.hourly_rate * Decimal::from(24))
            }
            _ => Woke::Nothing,
        });
        let account = drivers::account_events(DRIVER)
            .into_stream()
            .map(Woke::Venue);
        let vault_events = vault::events().into_stream().map(Woke::Vault);

        let mut waking = futures::stream::select_all([
            spot_book.boxed_local(),
            perp_book.boxed_local(),
            funding.boxed_local(),
            account.boxed_local(),
            vault_events.boxed_local(),
        ]);

        while let Some(woke) = waking.next().await {
            match woke {
                // Prices only update what the agent knows; it acts when
                // funding or its account moves, not on every quote.
                Woke::SpotBook(top) => mind.quotes.spot = top,
                Woke::PerpBook(top) => mind.quotes.perp = top,
                // Funding arrives every few seconds. It is looked at when it
                // crosses a threshold, or while there is still something to
                // do; otherwise the account's own events (fills, the hourly
                // funding payment) are what wake the strategy.
                Woke::Funding(daily) => {
                    let before = mind.quotes.funding.replace(daily);
                    if decide::steps_on_funding(before, daily, mind.busy) {
                        step(&mut mind, false).await?;
                    }
                }
                Woke::Venue(event) => {
                    if decide::wakes_for(&event) {
                        step(&mut mind, false).await?
                    }
                }
                Woke::Vault(vault::VaultEvent::ClaimPending(_)) => step(&mut mind, false).await?,
                Woke::Vault(vault::VaultEvent::BufferLow(short)) => {
                    // As much as the venue will let go of; a claim's close
                    // covers whatever this doesn't.
                    let _ = transfers::move_(venue(), Account::Vault, short).await;
                    step(&mut mind, true).await?
                }
                Woke::Vault(vault::VaultEvent::Halting(_)) => {
                    flatten(&mut mind).await?;
                    return Ok(());
                }
                Woke::Nothing => {}
            }
        }
        Ok(())
    }
}

fn venue() -> Account {
    Account::Venue(VenueAccount {
        chain: transfers::home_chain(),
        driver: DRIVER.to_string(),
    })
}

/// Look at what is there, work out what should be there, and act on it if
/// that is worth doing. `brought_home` says cash has just come home for
/// leavers.
async fn step(mind: &mut Mind, brought_home: bool) -> Result<(), String> {
    let state = read_state().await?;
    if state.vault_value > mind.peak {
        mind.peak = state.vault_value;
    }
    if brought_home {
        mind.leavers.brought_home(&mind.limits, &state);
    } else {
        mind.leavers.seen(state.idle);
    }
    let plan = decide::decide(
        &mind.limits,
        mind.peak,
        mind.leavers.held(),
        &state,
        &mind.quotes,
    );
    mind.busy = plan != Plan::Nothing;
    if !mind.busy {
        return Ok(());
    }
    let at = Snapshot::of(&state);
    if mind.patience.holds_back(&at) {
        return Ok(());
    }
    if let Plan::Build { fund, .. } = &plan {
        mind.leavers.taken(fund.from_vault);
    }
    let limits = mind.limits;
    if carry_out(mind, &limits, &state, &plan).await? {
        mind.patience.went_through();
    } else {
        mind.patience.refused(at);
    }
    Ok(())
}

async fn read_state() -> Result<AccountState, String> {
    from_payload(&drivers::account_state(DRIVER.to_string(), Vec::new()).await?)
}

/// Do what `plan` says, and say whether any of it went through.
///
/// The spot goes first and the short is sized to what it actually bought,
/// so an unfilled spot never leaves a short on its own, and the short is
/// levelled with the whole of the spot, an order's worth at a time, before
/// the step ends; on the way out the short goes first and the spot follows
/// what was bought back.
async fn carry_out(
    mind: &mut Mind,
    limits: &Limits,
    state: &AccountState,
    plan: &Plan,
) -> Result<bool, String> {
    let mut landed = false;
    match plan {
        Plan::Nothing => {}
        Plan::Build { fund, spot } => {
            // The money has to be at the venue before it can trade: the
            // station's idle dollars first, then the vault's cash; the
            // buffer stays in the vault, where a withdrawal reaches it
            // without a close. A move that stopped in the station, or whose
            // fate is unknown, is counted as outside the vault from then on,
            // so it is never sent twice.
            let home = transfers::home_chain();
            for (from, amount) in [
                (Account::Station(home), fund.from_station),
                (Account::Vault, fund.from_vault),
            ] {
                if amount > decide::zero() {
                    match transfers::move_(from, venue(), millionths(amount)).await {
                        Moved::Done => landed = true,
                        Moved::Partial(_) => return Ok(true),
                        Moved::Refused(_) | Moved::Unknown(_) => return Ok(landed),
                    }
                }
            }
            let (mut spot_held, mut perp_held) = held(state);
            if let Some(order) = spot {
                // The spot leg is paid for from the account's spot dollars;
                // the perp leg's margin stays on the perp side.
                let cost = order.size * order.limit_price;
                let spot_cash = spot_dollars(state);
                if spot_cash < cost {
                    let verdicts = submit(&[Action::MoveDollars {
                        from: Balance::Perp,
                        amount: decide::round_up_cents(cost - spot_cash),
                    }])
                    .await?;
                    if !matches!(verdicts.first(), Some(sdk::Verdict::Accepted(_))) {
                        return Ok(landed);
                    }
                }
                match place(order).await? {
                    Some(size) => {
                        landed = true;
                        spot_held += size;
                    }
                    None => return Ok(landed),
                }
            }
            for _ in 0..HEDGE_ORDERS {
                let Some(order) = hedge(limits, state, &mind.quotes, spot_held, perp_held) else {
                    break;
                };
                if !mind.levered {
                    let verdicts = submit(&[Action::Leverage {
                        market: config::PERP.into(),
                        leverage: config::PERP_LEVERAGE,
                    }])
                    .await?;
                    mind.levered = matches!(verdicts.first(), Some(sdk::Verdict::Accepted(_)));
                }
                match place(&order).await? {
                    Some(size) if size != decide::zero() => {
                        landed = true;
                        perp_held += size;
                    }
                    _ => break,
                }
            }
        }
        Plan::Reduce { perp } => {
            let (spot_held, mut perp_held) = held(state);
            if let Some(order) = perp
                && let Some(size) = place(order).await?
            {
                landed = true;
                perp_held += size;
            }
            if let Some(order) = trim(limits, state, &mind.quotes, spot_held, perp_held) {
                landed |= place(&order).await?.is_some();
            }
        }
    }
    Ok(landed)
}

/// Close everything, perp first, because a halt is an unwind with less time.
/// The per-order cap is lifted: leaving a leg on would cost the depositors
/// more than a wider fill.
async fn flatten(mind: &mut Mind) -> Result<(), String> {
    let limits = Limits {
        max_order_fraction: Decimal::from(1),
        ..mind.limits
    };
    for _ in 0..FLATTEN_STEPS {
        let state = read_state().await?;
        let plan = Plan::Reduce {
            perp: unwind(&limits, &state, &mind.quotes),
        };
        let (spot, perp) = held(&state);
        if perp == decide::zero() && trim(&limits, &state, &mind.quotes, spot, perp).is_none() {
            return Ok(());
        }
        carry_out(mind, &limits, &state, &plan).await?;
    }
    Ok(())
}

/// Send one order, and say how much of it filled, signed as the position
/// moved: nothing if it was refused, missed the book, or went unanswered.
async fn place(order: &Order) -> Result<Option<Decimal>, String> {
    let verdicts = submit(&[Action::Place(order.clone())]).await?;
    let Some(sdk::Verdict::Accepted(receipt)) = verdicts.first() else {
        return Ok(None);
    };
    let Ok(Receipt::Filled { size, .. }) = from_payload::<Receipt>(receipt) else {
        return Ok(None);
    };
    Ok(Some(match order.side {
        Side::Buy => size,
        Side::Sell => -size,
    }))
}

/// Send actions. A refusal is not a reason to stop: the next event is
/// another chance.
async fn submit(actions: &[Action]) -> Result<Vec<sdk::Verdict>, String> {
    let encoded: Vec<Vec<u8>> = actions.iter().map(to_payload).collect();
    Ok(drivers::submit(DRIVER.to_string(), encoded).await)
}

sdk::export_agent!(FundingBasis);

#[cfg(test)]
