//! The numbers this agent decides with. The claims in `shonin.toml` say the
//! same things in words.

/// The perpetual it quotes, and the size decimals the venue allows on it.
pub const MARKET: &str = "ETH";
pub const SIZE_DECIMALS: u32 = 4;
/// Cross margin at this leverage.
pub const LEVERAGE: u32 = 3;

/// Each side's distance from the mid, as a fraction of it.
pub const HALF_SPREAD: &str = "0.0008";
/// How far the quotes lean against inventory at the cap, as a fraction of
/// the mid: at full inventory long, both quotes sit this much lower.
pub const SKEW_AT_CAP: &str = "0.0010";
/// Quotes are renewed when the mid moves this far from where they were set.
pub const REQUOTE_MOVE: &str = "0.0004";
/// The venue's own cancel-everything deadline is set this far ahead of the
/// agent's clock: if the agent stops renewing it, the venue cancels every
/// quote at most this long after the last renewal.
pub const DEAD_MAN_MS: u64 = 60_000;
/// The deadline is renewed once less than this is left on it, so it is sent
/// at most about twice a minute however often the quotes move, rather than
/// with every requote: each renewal is an action the venue counts against
/// the account's request allowance.
pub const RENEW_WHEN_LEFT_MS: u64 = 30_000;
/// The venue fires a scheduled cancel at most ten times a UTC day. Once the
/// deadline has run out this many times in a day (each time the agent fell
/// silent), the agent stops quoting until the next UTC day, so it never
/// rests a quote without the venue's deadline behind it.
pub const STOP_AFTER_FIRES: u32 = 8;
// Always some of the venue's ten left over.
const _: () = assert!(STOP_AFTER_FIRES < 10);

/// Each quote at most 2% of the vault's value.
pub const QUOTE_FRACTION: &str = "0.02";
/// Inventory at most 50% of the vault's value.
pub const INVENTORY_CAP: &str = "0.50";
/// The venue refuses an order under ten dollars; below this a quote isn't
/// posted.
pub const MINIMUM_NOTIONAL: &str = "12";

//! Quotes both sides of one Hyperliquid perpetual and manages the inventory
//! it takes on.
//!
//! It reads the market's book from Shonin's shared stream and keeps one
//! resting bid and one resting ask around the mid, leaning both against its
//! inventory so fills that bring it back to flat are the likelier ones. It
//! renews its quotes only when the mid has moved far enough to matter.
//!
//! Behind the quotes stands the venue's own cancel-everything deadline,
//! renewed as the books arrive once less than half of it is left (not with
//! every requote: each renewal is an action the venue counts), so if the
//! agent stops, the venue pulls its quotes within a minute. The venue fires
//! that deadline at most ten times a UTC day; the agent counts each time it
//! ran out and, after eight in a day, pulls its quotes and stands aside until
//! the next day, so no quote of its rests without the deadline behind it.
//!
//! Its limits are in `config.rs`, where the reviewer reads them.

mod config;

use futures::StreamExt;
use hl::{AccountState, Action, Order, OrderRef, Side, Tif};
use sdk::streams::{self, HYPERLIQUID, HyperliquidFeed, HyperliquidValue};
use sdk::{Decimal, decimal, drivers, from_payload, to_payload, vault};
use strategy_sdk as sdk;
use strategy_sdk::hyperliquid as hl;

const DRIVER: &str = hl::DRIVER;
/// How many steps a halt may take to close the inventory.
const FLATTEN_STEPS: usize = 16;

struct MmQuoter;

fn zero() -> Decimal {
    Decimal::from(0)
}

fn one() -> Decimal {
    Decimal::from(1)
}

/// The quotes resting now, by the agent's own ids.
#[derive(Default)]
struct Quotes {
    bid: Option<u128>,
    ask: Option<u128>,
    /// The mid they were set around.
    mid: Option<Decimal>,
}

struct Mind {
    best_bid: Option<Decimal>,
    best_ask: Option<Decimal>,
    /// When the last book arrived, in milliseconds.
    now_ms: u64,
    quotes: Quotes,
    next_id: u128,
    levered: bool,
    dead_man: DeadMan,
}

const DAY_MS: u64 = 86_400_000;

/// The venue's cancel-everything deadline, as the agent has set it, and how
/// often it has run out today.
#[derive(Default, Debug)]
struct DeadMan {
    /// When the venue will cancel everything, unless renewed first.
    deadline_ms: Option<u64>,
    /// The UTC day the count is for, in days since 1970.
    day: u64,
    /// How many times the deadline ran out on that day.
    fired: u32,
}

impl DeadMan {
    /// Take note of the time: a deadline that has passed fired, and the
    /// venue cancelled every quote then. True if it did.
    fn observe(&mut self, now_ms: u64) -> bool {
        let fired = match self.deadline_ms {
            Some(deadline) if now_ms >= deadline => {
                self.deadline_ms = None;
                self.count(deadline / DAY_MS);
                true
            }
            _ => false,
        };
        // A new UTC day: the venue's count starts again.
        if now_ms / DAY_MS > self.day {
            self.day = now_ms / DAY_MS;
            self.fired = 0;
        }
        fired
    }

    fn count(&mut self, day: u64) {
        if day > self.day {
            self.day = day;
            self.fired = 0;
        }
        if day == self.day {
            self.fired += 1;
        }
    }

    /// Whether quotes may rest: the deadline has run out fewer times today
    /// than the agent allows itself, so the venue can still fire it.
    fn may_quote(&self) -> bool {
        self.fired < config::STOP_AFTER_FIRES
    }

    /// The deadline to renew to now, if a renewal is due: none set, or less
    /// than [`config::RENEW_WHEN_LEFT_MS`] left on it.
    fn renewal(&self, now_ms: u64) -> Option<u64> {
        self.deadline_ms
            .is_none_or(|deadline| deadline.saturating_sub(now_ms) < config::RENEW_WHEN_LEFT_MS)
            .then_some(now_ms + config::DEAD_MAN_MS)
    }

    /// The venue took a renewal to `at_ms`. One it refused leaves the
    /// deadline it had.
    fn renewed(&mut self, at_ms: u64) {
        self.deadline_ms = Some(at_ms);
    }

    /// Take the deadline off: nothing is resting.
    fn clear(&mut self) -> Action {
        self.deadline_ms = None;
        Action::CancelAllAt { at_ms: None }
    }
}

impl Mind {
    fn mid(&self) -> Option<Decimal> {
        match (self.best_bid, self.best_ask) {
            (Some(bid), Some(ask)) if bid > zero() && ask > bid => {
                Some((bid + ask) / Decimal::from(2))
            }
            _ => None,
        }
    }

    fn id(&mut self) -> u128 {
        self.next_id += 1;
        self.next_id
    }
}

enum Woke {
    Book {
        bid: Option<Decimal>,
        ask: Option<Decimal>,
        at_ms: u64,
    },
    Venue,
    Vault(vault::VaultEvent),
    Nothing,
}

impl sdk::Agent for MmQuoter {
    async fn run() -> Result<(), String> {
        let mut mind = Mind {
            best_bid: None,
            best_ask: None,
            now_ms: 0,
            quotes: Quotes::default(),
            next_id: 0,
            levered: false,
            dead_man: DeadMan::default(),
        };
        let book = streams::subscribe::<_, HyperliquidValue>(
            HYPERLIQUID,
            &HyperliquidFeed::Book {
                coin: config::MARKET.into(),
            },
        )?
        .map(|value| match value {
            Ok(stamped) => match stamped.value {
                HyperliquidValue::Book(book) => Woke::Book {
                    bid: book.bids.first().map(|level| level.price),
                    ask: book.asks.first().map(|level| level.price),
                    at_ms: stamped.received_ms,
                },
                _ => Woke::Nothing,
            },
            Err(_) => Woke::Nothing,
        });
        let account = drivers::account_events(DRIVER)
            .into_stream()
            .map(|_| Woke::Venue);
        let vault_events = vault::events().into_stream().map(Woke::Vault);
        let mut waking = futures::stream::select_all([
            book.boxed_local(),
            account.boxed_local(),
            vault_events.boxed_local(),
        ]);

        while let Some(woke) = waking.next().await {
            match woke {
                Woke::Book { bid, ask, at_ms } => {
                    mind.best_bid = bid;
                    mind.best_ask = ask;
                    mind.now_ms = at_ms;
                    // Ids carry the time, so a restarted agent never reuses
                    // one its predecessor left resting.
                    if mind.next_id == 0 {
                        mind.next_id = u128::from(at_ms) << 32;
                    }
                    if mind.dead_man.observe(at_ms) {
                        // The venue cancelled everything: nothing rests.
                        mind.quotes = Quotes::default();
                    }
                    if !mind.dead_man.may_quote() {
                        stand_aside(&mut mind).await?;
                    } else if moved_enough(&mind) {
                        requote(&mut mind).await?;
                    } else if let Some(until) = mind.dead_man.renewal(at_ms) {
                        let verdicts =
                            submit(&[Action::CancelAllAt { at_ms: Some(until) }]).await?;
                        if matches!(verdicts.first(), Some(sdk::Verdict::Accepted(_))) {
                            mind.dead_man.renewed(until);
                        }
                    }
                }
                // A fill changes the inventory: lean the quotes again.
                Woke::Venue | Woke::Vault(vault::VaultEvent::ClaimPending(_)) => {
                    if mind.mid().is_some() && mind.dead_man.may_quote() {
                        requote(&mut mind).await?;
                    }
                }
                Woke::Vault(vault::VaultEvent::BufferLow(_)) => {}
                Woke::Vault(vault::VaultEvent::Halting(_)) => {
                    flatten(&mut mind).await?;
                    return Ok(());
                }
                Woke::Nothing => {}
            }
        }
        Ok(())
    }
}

/// Whether the mid has moved far enough from where the quotes were set.
fn moved_enough(mind: &Mind) -> bool {
    let Some(mid) = mind.mid() else {
        return false;
    };
    match mind.quotes.mid {
        None => true,
        Some(quoted) => {
            let moved = if mid > quoted {
                mid - quoted
            } else {
                quoted - mid
            };
            moved / quoted >= decimal(config::REQUOTE_MOVE)
        }
    }
}

async fn read_state() -> Result<AccountState, String> {
    from_payload(&drivers::account_state(DRIVER.to_string(), Vec::new()).await?)
}

fn inventory(state: &AccountState) -> Decimal {
    state
        .positions
        .iter()
        .find(|position| position.market == config::MARKET)
        .map_or_else(zero, |position| position.size)
}

/// One side's quote: its price and size.
type Quote = Option<(Decimal, Decimal)>;

/// Where the two quotes go, and how big each is: `None` for a side that
/// would add to inventory already at its cap, or that is too small to post.
fn quotes_for(mid: Decimal, inventory: Decimal, vault_value: Decimal) -> (Quote, Quote) {
    if mid <= zero() || vault_value <= zero() {
        return (None, None);
    }
    let cap = vault_value * decimal(config::INVENTORY_CAP);
    let held = inventory * mid;
    // -1 at the cap short, +1 at the cap long.
    let mut lean = held / cap;
    if lean > one() {
        lean = one();
    }
    if lean < zero() - one() {
        lean = zero() - one();
    }
    let skew = lean * decimal(config::SKEW_AT_CAP);
    let half = decimal(config::HALF_SPREAD);
    let size = round_down(
        vault_value * decimal(config::QUOTE_FRACTION) / mid,
        config::SIZE_DECIMALS,
    );
    if size * mid < decimal(config::MINIMUM_NOTIONAL) {
        return (None, None);
    }
    let bid = (held < cap).then(|| (five_figures(mid * (one() - half - skew), Side::Buy), size));
    let ask = (held > zero() - cap)
        .then(|| (five_figures(mid * (one() + half - skew), Side::Sell), size));
    (bid, ask)
}

/// Cancel the quotes resting, push the venue's deadline back, and post new
/// ones around the mid.
async fn requote(mind: &mut Mind) -> Result<(), String> {
    let Some(mid) = mind.mid() else {
        return Ok(());
    };
    let state = read_state().await?;
    if !mind.levered {
        let verdicts = submit(&[Action::Leverage {
            market: config::MARKET.into(),
            leverage: config::LEVERAGE,
        }])
        .await?;
        mind.levered = matches!(verdicts.first(), Some(sdk::Verdict::Accepted(_)));
    }
    let mut actions = cancels(&mut mind.quotes);
    // Nothing is posted without the venue's deadline behind it, and the
    // deadline is renewed only when due.
    let renewal = mind.dead_man.renewal(mind.now_ms).map(|until| {
        actions.push(Action::CancelAllAt { at_ms: Some(until) });
        (actions.len() - 1, until)
    });
    let (bid, ask) = quotes_for(mid, inventory(&state), state.vault_value);
    if let Some((price, size)) = bid {
        let id = mind.id();
        mind.quotes.bid = Some(id);
        actions.push(Action::Place(quote(Side::Buy, price, size, id)));
    }
    if let Some((price, size)) = ask {
        let id = mind.id();
        mind.quotes.ask = Some(id);
        actions.push(Action::Place(quote(Side::Sell, price, size, id)));
    }
    mind.quotes.mid = Some(mid);
    let verdicts = submit(&actions).await?;
    if let Some((at, until)) = renewal
        && matches!(verdicts.get(at), Some(sdk::Verdict::Accepted(_)))
    {
        mind.dead_man.renewed(until);
    }
    Ok(())
}

/// Pull the quotes and take the deadline off, once: the deadline has run out
/// too often today for the venue to be relied on to fire it again.
async fn stand_aside(mind: &mut Mind) -> Result<(), String> {
    if mind.quotes.bid.is_none() && mind.quotes.ask.is_none() && mind.dead_man.deadline_ms.is_none()
    {
        return Ok(());
    }
    let mut actions = cancels(&mut mind.quotes);
    actions.push(mind.dead_man.clear());
    mind.quotes.mid = None;
    submit(&actions).await.map(|_| ())
}

/// Cancels for the quotes resting now, which are then forgotten.
fn cancels(quotes: &mut Quotes) -> Vec<Action> {
    [quotes.bid.take(), quotes.ask.take()]
        .into_iter()
        .flatten()
        .map(|id| Action::Cancel {
            market: config::MARKET.into(),
            order: OrderRef::Client(id),
        })
        .collect()
}

fn quote(side: Side, price: Decimal, size: Decimal, id: u128) -> Order {
    Order {
        market: config::MARKET.into(),
        side,
        size,
        limit_price: price,
        tif: Tif::PostOnly,
        reduce_only: false,
        client_id: Some(id),
    }
}

/// Pull the quotes and close the inventory, reduce-only, at the book.
async fn flatten(mind: &mut Mind) -> Result<(), String> {
    let mut actions = cancels(&mut mind.quotes);
    actions.push(mind.dead_man.clear());
    submit(&actions).await?;
    for _ in 0..FLATTEN_STEPS {
        let held = inventory(&read_state().await?);
        if held == zero() {
            return Ok(());
        }
        let (side, size, price) = if held > zero() {
            (Side::Sell, held, mind.best_bid)
        } else {
            (Side::Buy, zero() - held, mind.best_ask)
        };
        let Some(price) = price else {
            return Ok(());
        };
        // A wide reach: the vault is stopping, and the contract closes
        // whatever this leaves inside its own band.
        let reach = decimal("0.01");
        let limit = match side {
            Side::Sell => price * (one() - reach),
            Side::Buy => price * (one() + reach),
        };
        submit(&[Action::Place(Order {
            market: config::MARKET.into(),
            side,
            size,
            limit_price: five_figures(limit, side),
            tif: Tif::Ioc,
            reduce_only: true,
            client_id: None,
        })])
        .await?;
    }
    Ok(())
}

fn round_down(size: Decimal, decimals: u32) -> Decimal {
    let scale = Decimal::from(10u64.pow(decimals));
    (size * scale).floor() / scale
}

/// Five significant figures, the most the venue takes, rounded away from
/// the market: down for a bid, up for an ask.
fn five_figures(price: Decimal, side: Side) -> Decimal {
    if price <= zero() {
        return price;
    }
    let ten = Decimal::from(10);
    let mut scale = one();
    while price * scale < Decimal::from(10_000) {
        scale *= ten;
    }
    while price * scale >= Decimal::from(100_000) {
        scale /= ten;
    }
    let scaled = price * scale;
    let rounded = match side {
        Side::Buy => scaled.floor(),
        Side::Sell => scaled.ceil(),
    };
    rounded / scale
}

async fn submit(actions: &[Action]) -> Result<Vec<sdk::Verdict>, String> {
    let encoded: Vec<Vec<u8>> = actions.iter().map(to_payload).collect();
    Ok(drivers::submit(DRIVER.to_string(), encoded).await)
}

sdk::export_agent!(MmQuoter);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn flat_inventory_quotes_symmetrically_around_the_mid() {
        let (bid, ask) = quotes_for(decimal("2700"), zero(), decimal("10000"));
        let (bid, size) = bid.unwrap();
        let (ask, _) = ask.unwrap();
        assert!(bid < decimal("2700") && ask > decimal("2700"));
        assert_eq!(
            decimal("2700") - bid,
            ask - decimal("2700") - (ask - bid - (ask - bid))
        );
        // 2% of 10,000 at 2,700, to four decimals.
        assert_eq!(size, decimal("0.074"));
    }

    #[test]
    fn a_long_inventory_leans_both_quotes_down() {
        let (flat_bid, flat_ask) = quotes_for(decimal("2700"), zero(), decimal("10000"));
        let (long_bid, long_ask) = quotes_for(decimal("2700"), decimal("0.5"), decimal("10000"));
        assert!(long_bid.unwrap().0 < flat_bid.unwrap().0);
        assert!(long_ask.unwrap().0 < flat_ask.unwrap().0);
    }

    #[test]
    fn a_side_at_its_inventory_cap_is_not_quoted() {
        // 2 ETH at 2,700 is 5,400, past half of 10,000.
        let (bid, ask) = quotes_for(decimal("2700"), decimal("2"), decimal("10000"));
        assert!(bid.is_none(), "no more buying at the cap long");
        assert!(ask.is_some());
        let (bid, ask) = quotes_for(decimal("2700"), decimal("-2"), decimal("10000"));
        assert!(bid.is_some());
        assert!(ask.is_none(), "no more selling at the cap short");
    }

    #[test]
    fn a_vault_too_small_for_the_venues_minimum_posts_nothing() {
        assert_eq!(
            quotes_for(decimal("2700"), zero(), decimal("100")),
            (None, None)
        );
    }

    #[test]
    fn the_deadline_is_renewed_only_once_less_than_half_of_it_is_left() {
        let mut dead_man = DeadMan::default();
        let start = 1_000 * DAY_MS;
        dead_man.observe(start);
        let until = dead_man.renewal(start).expect("none set: renewed");
        dead_man.renewed(until);
        // Books every second for the next half minute renew nothing.
        for second in 1..30 {
            let now = start + second * 1_000;
            assert!(!dead_man.observe(now));
            assert!(dead_man.renewal(now).is_none(), "renewed at {second}s");
        }
        // With less than half left, it is renewed, and pushed a minute on.
        let now = start + 30_001;
        assert_eq!(dead_man.renewal(now), Some(now + config::DEAD_MAN_MS));
    }

    #[test]
    fn renewals_a_day_stay_far_below_one_per_requote() {
        // A book every 100 ms for a day.
        let mut dead_man = DeadMan::default();
        let mut renewals = 0;
        for tick in 0..(DAY_MS / 100) {
            let now = tick * 100;
            dead_man.observe(now);
            if let Some(until) = dead_man.renewal(now) {
                dead_man.renewed(until);
                renewals += 1;
            }
        }
        assert!(renewals <= 2 * 24 * 60 + 1, "{renewals}");
        assert_eq!(dead_man.fired, 0, "a renewed deadline never fires");
    }

    #[test]
    fn a_deadline_that_ran_out_is_counted_and_the_agent_stands_aside_after_eight_a_day() {
        let mut dead_man = DeadMan::default();
        let mut now = 2_000 * DAY_MS;
        for fired in 1..=config::STOP_AFTER_FIRES {
            assert!(dead_man.may_quote());
            let until = dead_man.renewal(now).unwrap();
            dead_man.renewed(until);
            // The agent falls silent past the deadline.
            now += config::DEAD_MAN_MS + 5_000;
            assert!(dead_man.observe(now), "a deadline that passed fired");
            assert_eq!(dead_man.fired, fired);
        }
        assert!(!dead_man.may_quote(), "stands aside, leaving the venue two");
        // The next UTC day it quotes again.
        let next_day = (now / DAY_MS + 1) * DAY_MS;
        assert!(!dead_man.observe(next_day));
        assert!(dead_man.may_quote());
    }

    #[test]
    fn a_deadline_cleared_never_counts_as_fired() {
        let mut dead_man = DeadMan::default();
        dead_man.renewed(dead_man.renewal(0).unwrap());
        assert_eq!(dead_man.clear(), Action::CancelAllAt { at_ms: None });
        assert!(!dead_man.observe(10 * config::DEAD_MAN_MS));
        assert_eq!(dead_man.fired, 0);
    }

    #[test]
    fn the_manifest_claims_the_limits_the_code_keeps() {
        let manifest = include_str!("../shonin.toml");
        assert!(manifest.contains("at most 50% of the vault") && config::INVENTORY_CAP == "0.50");
        assert!(manifest.contains("at most 2% of the vault") && config::QUOTE_FRACTION == "0.02");
        assert!(manifest.contains("within 60 seconds") && config::DEAD_MAN_MS == 60_000);
        assert!(manifest.contains("ten times a day") && manifest.contains("eight"));
        assert_eq!(config::STOP_AFTER_FIRES, 8);
        assert!(manifest.contains("leverage 3") && config::LEVERAGE == 3);
        assert!(manifest.contains("ETH perpetual") && config::MARKET == "ETH");
    }
}

//! The numbers this agent decides with.
//!
//! They are constants in the code rather than settings anywhere else, so the
//! reviewer reads them with the rest of the source, and the claims in
//! `shonin.toml` say the same thing in words.

/// The underlyings it trades: the stock token's symbol, the Lighter
/// perpetual's symbol, and the perpetual's market number on Lighter's
/// Robinhood Chain exchange (read from its order books).
pub const NAMES: &[(&str, &str, u32)] =
    &[("SPY", "SPY", 26), ("QQQ", "QQQ", 25), ("NVDA", "NVDA", 15)];

/// The perpetual's premium over the token (per share of the stock) at which
/// a carry is opened, and below which an open one is closed.
pub const ENTRY_PREMIUM: &str = "0.005";
pub const EXIT_PREMIUM: &str = "0.001";
/// How much of the vault to aim to have working across all names: each name
/// gets an equal part.
pub const TARGET_DEPLOYMENT: &str = "0.60";
/// Below this, an order is not worth the spread it would pay.
pub const MINIMUM_NOTIONAL: &str = "50";
/// What the short is margined with at Lighter, as a fraction of its notional:
/// well above the exchange's 2% so a weekend move doesn't liquidate it.
pub const PERP_MARGIN: &str = "0.25";
/// How far from the price seen a closing or opening order may fill.
pub const SLIPPAGE: &str = "0.01";

/// Gross exposure at most twice the vault's value.
pub const MAX_GROSS_LEVERAGE: &str = "2";
/// No single order above 5% of the vault.
pub const MAX_ORDER_FRACTION: &str = "0.05";
/// 6% of the vault kept liquid, so an ordinary withdrawal closes nothing.
pub const IDLE_BUFFER: &str = "0.06";
/// Both legs cut together after a 10% fall from the vault's peak.
pub const DRAWDOWN_STOP: &str = "0.10";

/// The weekend, in UTC: from Friday 21:00 (the cash market has closed) to
/// Monday 13:30 (it opens). Outside it, an open carry is closed.
pub const WEEKEND_FROM: (u8, u32) = (5, 21 * 3600);
pub const WEEKEND_UNTIL: (u8, u32) = (1, 13 * 3600 + 1800);

/// Steps at most this often, in seconds, however busy the books are.
pub const STEP_EVERY: u64 = 30;

//! Holds Robinhood stock tokens against Lighter perpetuals over the weekend.
//!
//! A stock token trades around the clock; the stock behind it, and the
//! channel that creates and redeems tokens against it, don't. From Friday's
//! close to Monday's open nothing pulls a token back to its stock, and the
//! perpetual on the same stock moves with the weekend's flow. When the
//! perpetual trades far enough above the token, this agent buys the token
//! and shorts the perpetual in matching shares, and carries the pair into
//! Monday, when the gap usually closes.
//!
//! The whole strategy is one long-lived program. It listens to the shared
//! Lighter books for its three stocks and to the vault's events, and at most
//! every `STEP_EVERY` seconds it works out what it would like to hold
//! (`plan.rs`) and takes one step towards it. Its limits are in `config.rs`,
//! and the manifest claims them in the same words.

mod config;
mod plan;
mod venues;

use std::collections::HashMap;

use futures::StreamExt;
use sdk::streams::{self, LIGHTER, LighterFeed, LighterValue};
use sdk::transfers::{self, Account, Moved, VenueAccount};
use sdk::{Decimal, Verdict, decimal, drivers, from_payload, millionths, to_payload, vault};
use strategy_sdk as sdk;
use venues::{lighter as lt, robinhood as rh};

use plan::{Name, Picture, Step, zero};

/// How many steps a halt may take to close everything before leaving the
/// rest to the contracts.
const FLATTEN_STEPS: usize = 64;

struct WeekendCarry;

/// What the agent remembers between steps: rebuilt from the venues whenever
/// it starts, so a restart costs a moment and nothing else.
struct Mind {
    peak: Decimal,
    /// Each perpetual's best bid and ask, by Lighter market number.
    books: HashMap<u32, (Decimal, Decimal)>,
    last_step: u64,
}

enum Woke {
    Book(u32, Decimal, Decimal),
    Vault(vault::VaultEvent),
    Nothing,
}

fn now() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|since| since.as_secs())
        .unwrap_or(0)
}

impl sdk::Agent for WeekendCarry {
    async fn run() -> Result<(), String> {
        let mut mind = Mind {
            peak: zero(),
            books: HashMap::new(),
            last_step: 0,
        };
        let mut books = Vec::new();
        for (_, _, market) in config::NAMES {
            let stream = streams::subscribe::<_, LighterValue>(
                LIGHTER,
                &LighterFeed::Book { market: *market },
            )?;
            let market = *market;
            books.push(stream.map(move |value| match value {
                Ok(stamped) => {
                    let LighterValue::Book(book) = stamped.value;
                    match (book.bids.first(), book.asks.first()) {
                        (Some(bid), Some(ask)) => Woke::Book(market, bid.price, ask.price),
                        _ => Woke::Nothing,
                    }
                }
                Err(_) => Woke::Nothing,
            }));
        }
        let books = futures::stream::select_all(books);
        let vault_events = vault::events().into_stream().map(Woke::Vault);
        let mut waking = futures::stream::select(books, vault_events);

        while let Some(woke) = waking.next().await {
            match woke {
                Woke::Book(market, bid, ask) => {
                    mind.books.insert(market, (bid, ask));
                    if now() >= mind.last_step + config::STEP_EVERY {
                        mind.last_step = now();
                        step(&mut mind).await?;
                    }
                }
                // A leaver's fraction of both legs is being closed by the
                // contracts; look again at what is left.
                Woke::Vault(vault::VaultEvent::ClaimPending(_)) => step(&mut mind).await?,
                // Leavers wait on more cash than the vault holds: bring idle
                // dollars home from the Safe, then from Lighter.
                Woke::Vault(vault::VaultEvent::BufferLow(short)) => {
                    let mut owed = short;
                    for driver in [rh::DRIVER, lt::DRIVER] {
                        if owed == 0 {
                            break;
                        }
                        if matches!(
                            transfers::move_(venue(driver), Account::Vault, owed).await,
                            Moved::Done
                        ) {
                            owed = 0;
                        }
                    }
                }
                Woke::Vault(vault::VaultEvent::Halting(_)) => {
                    flatten(&mut mind).await?;
                    return Ok(());
                }
                Woke::Nothing => {}
            }
        }
        Ok(())
    }
}

fn venue(driver: &str) -> Account {
    Account::Venue(VenueAccount {
        chain: transfers::home_chain(),
        driver: driver.to_string(),
    })
}

/// Everything the vault is worth, everywhere, in dollars.
async fn vault_value() -> Decimal {
    let total: u64 = transfers::balances()
        .await
        .iter()
        .map(|balance| balance.amount)
        .sum();
    Decimal::from(total) / Decimal::from(1_000_000u32)
}

async fn state<Q: serde::Serialize, A: serde::de::DeserializeOwned>(
    driver: &str,
    query: &Q,
) -> Result<A, String> {
    from_payload(&drivers::account_state(driver.to_string(), to_payload(query)).await?)
}

/// What the agent sees now.
async fn picture(mind: &mut Mind) -> Result<Picture, String> {
    let prices: Vec<rh::TokenPrice> = state(rh::DRIVER, &rh::Query::Prices).await?;
    let holdings: rh::AccountState = state(rh::DRIVER, &rh::Query::Holdings).await?;
    // No Lighter account before the first move to it: nothing is held there.
    let perps: Option<lt::AccountState> = state(lt::DRIVER, &lt::Query::Account).await.ok();
    let value = vault_value().await;
    if value > mind.peak {
        mind.peak = value;
    }
    let mut names = Vec::new();
    for (token, perp, market) in config::NAMES {
        let Some(price) = prices.iter().find(|p| p.token == *token) else {
            continue;
        };
        let Some((bid, ask)) = mind.books.get(market) else {
            continue;
        };
        let tokens = holdings
            .holdings
            .iter()
            .find(|h| h.token == *token)
            .map(|h| h.tokens)
            .unwrap_or_else(zero);
        let perp_position = perps
            .as_ref()
            .and_then(|state| state.positions.iter().find(|p| p.market == *perp))
            .map(|p| p.size)
            .unwrap_or_else(zero);
        names.push(Name {
            token: token.to_string(),
            perp: perp.to_string(),
            token_price: price.market_price,
            multiplier: price.multiplier,
            paused: price.paused,
            perp_bid: *bid,
            perp_ask: *ask,
            tokens,
            perp_position,
        });
    }
    Ok(Picture {
        now: now(),
        vault_value: value,
        peak: mind.peak,
        names,
    })
}

/// Look, decide, and take one step.
async fn step(mind: &mut Mind) -> Result<(), String> {
    let picture = picture(mind).await?;
    act(&picture, picture.next()).await
}

async fn act(picture: &Picture, step: Step) -> Result<(), String> {
    let slippage = decimal(config::SLIPPAGE);
    let one = Decimal::from(1u8);
    match step {
        Step::Nothing => Ok(()),
        Step::Open {
            index,
            dollars,
            tokens,
            shares,
        } => {
            let name = &picture.names[index];
            // The money has to be at each venue before it can trade there;
            // the buffer stays home, where a withdrawal reaches it.
            let margin = shares * name.perp_bid * decimal(config::PERP_MARGIN);
            if !fund(rh::DRIVER, dollars, picture.vault_value).await
                || !fund(lt::DRIVER, margin, picture.vault_value).await
            {
                return Ok(());
            }
            let bought = submit(
                rh::DRIVER,
                &rh::Action::Buy {
                    token: name.token.clone(),
                    amount: dollars,
                    min_tokens: tokens * (one - slippage),
                },
            )
            .await?;
            // No token, no short: a naked short is the one thing this
            // strategy never holds.
            if !bought {
                return Ok(());
            }
            submit(
                lt::DRIVER,
                &lt::Action::Place(lt::Order {
                    market: name.perp.clone(),
                    side: lt::Side::Sell,
                    size: shares,
                    limit_price: name.perp_bid * (one - slippage),
                    tif: lt::Tif::Ioc,
                    reduce_only: false,
                    client_id: None,
                }),
            )
            .await
            .map(|_| ())
        }
        Step::Close {
            index,
            shares,
            tokens,
        } => {
            let name = &picture.names[index];
            if shares > zero() {
                let bought_back = submit(
                    lt::DRIVER,
                    &lt::Action::Place(lt::Order {
                        market: name.perp.clone(),
                        side: lt::Side::Buy,
                        size: shares,
                        limit_price: name.perp_ask * (one + slippage),
                        tif: lt::Tif::Ioc,
                        reduce_only: true,
                        client_id: None,
                    }),
                )
                .await?;
                // The token waits for the short: the next step sees what
                // the buy-back really closed.
                if !bought_back {
                    return Ok(());
                }
            }
            if tokens > zero() {
                submit(
                    rh::DRIVER,
                    &rh::Action::Sell {
                        token: name.token.clone(),
                        tokens,
                        min_amount: tokens * name.token_price * (one - slippage),
                    },
                )
                .await?;
            }
            Ok(())
        }
    }
}

/// Make sure `driver`'s account holds `wanted` dollars, moving the shortfall
/// from the vault's cash without going below the buffer. Whether it holds
/// enough now.
async fn fund(driver: &str, wanted: Decimal, vault_value: Decimal) -> bool {
    let balances = transfers::balances().await;
    let amount_of = |wanted: &dyn Fn(&Account) -> bool| -> Decimal {
        balances
            .iter()
            .find(|b| wanted(&b.account))
            .map(|b| Decimal::from(b.amount) / Decimal::from(1_000_000u32))
            .unwrap_or_else(zero)
    };
    let there = amount_of(&|account| matches!(account, Account::Venue(v) if v.driver == driver));
    if there >= wanted {
        return true;
    }
    let cash = amount_of(&|account| matches!(account, Account::Vault));
    let keep = vault_value * decimal(config::IDLE_BUFFER);
    let spare = if cash > keep { cash - keep } else { zero() };
    let short = wanted - there;
    if spare < short {
        return false;
    }
    matches!(
        transfers::move_(Account::Vault, venue(driver), millionths(short)).await,
        Moved::Done
    )
}

/// Submit one action; whether the venue took it.
async fn submit<A: serde::Serialize>(driver: &str, action: &A) -> Result<bool, String> {
    let verdicts = drivers::submit(driver.to_string(), vec![to_payload(action)]).await;
    Ok(matches!(verdicts.first(), Some(Verdict::Accepted(_))))
}

/// Close everything, short first, because a halt is an unwind with less
/// time.
async fn flatten(mind: &mut Mind) -> Result<(), String> {
    for _ in 0..FLATTEN_STEPS {
        let mut picture = picture(mind).await?;
        // A halt closes regardless of the weekend or the premium: as if the
        // peak were far above.
        picture.peak = picture.vault_value * Decimal::from(10u8);
        match picture.next() {
            Step::Nothing => return Ok(()),
            close @ Step::Close { .. } => act(&picture, close).await?,
            Step::Open { .. } => return Ok(()),
        }
    }
    Ok(())
}

sdk::export_agent!(WeekendCarry);

//! What the agent would like to hold, worked out from what it sees: no I/O,
//! so every rule is tested here.

use strategy_sdk::{Decimal, decimal};

use crate::config;

pub fn zero() -> Decimal {
    Decimal::from(0)
}

fn abs(value: Decimal) -> Decimal {
    if value < zero() { -value } else { value }
}

/// Whether `unix_secs` falls in the weekend window: from Friday 21:00 UTC to
/// Monday 13:30 UTC.
pub fn in_weekend(unix_secs: u64) -> bool {
    let days = unix_secs / 86_400;
    // The epoch was a Thursday: 0 is Sunday, 5 is Friday.
    let weekday = ((days + 4) % 7) as u8;
    let second = (unix_secs % 86_400) as u32;
    let (from_day, from_second) = config::WEEKEND_FROM;
    let (until_day, until_second) = config::WEEKEND_UNTIL;
    match weekday {
        d if d == from_day => second >= from_second,
        6 | 0 => true,
        d if d == until_day => second < until_second,
        _ => false,
    }
}

/// One underlying, as seen now.
#[derive(Clone, Debug, PartialEq)]
pub struct Name {
    pub token: String,
    pub perp: String,
    /// The token's market price (its pool's), in dollars per token.
    pub token_price: Decimal,
    /// Shares of the stock per token.
    pub multiplier: Decimal,
    /// The issuer has paused the token's oracle: nothing is opened.
    pub paused: bool,
    /// The perpetual's best bid and ask, per share.
    pub perp_bid: Decimal,
    pub perp_ask: Decimal,
    /// Held now: tokens in the Safe, and the perpetual (negative is short).
    pub tokens: Decimal,
    pub perp_position: Decimal,
}

impl Name {
    /// What one share of the stock costs as the token.
    pub fn share_price(&self) -> Decimal {
        if self.multiplier <= zero() {
            return zero();
        }
        self.token_price / self.multiplier
    }

    /// How far the perpetual trades above the token, per share: the bid
    /// (what shorting it fetches) against the token's price.
    pub fn premium(&self) -> Decimal {
        let share = self.share_price();
        if share <= zero() || self.perp_bid <= zero() {
            return zero();
        }
        (self.perp_bid - share) / share
    }
}

/// The whole vault, as seen now.
#[derive(Clone, Debug, PartialEq)]
pub struct Picture {
    pub now: u64,
    /// Everything the vault is worth, everywhere.
    pub vault_value: Decimal,
    pub peak: Decimal,
    pub names: Vec<Name>,
}

/// One step towards what the agent would like to hold.
#[derive(Clone, Debug, PartialEq)]
pub enum Step {
    /// Buy `tokens` of the token (spending about `dollars`), then short the
    /// matching shares of the perpetual.
    Open {
        index: usize,
        dollars: Decimal,
        tokens: Decimal,
        shares: Decimal,
    },
    /// Buy back `shares` of the perpetual, then sell `tokens`: the short
    /// always goes first.
    Close {
        index: usize,
        shares: Decimal,
        tokens: Decimal,
    },
    Nothing,
}

impl Picture {
    pub fn only_reducing(&self) -> bool {
        self.peak > zero()
            && (self.peak - self.vault_value) / self.peak >= decimal(config::DRAWDOWN_STOP)
    }

    fn gross(&self) -> Decimal {
        self.names
            .iter()
            .map(|name| name.tokens * name.token_price + abs(name.perp_position) * name.perp_ask)
            .fold(zero(), |a, b| a + b)
    }

    /// The next step: a close first wherever one is due, else an opening
    /// where one is worth it, one order's worth at a time.
    pub fn next(&self) -> Step {
        let per_order = self.vault_value * decimal(config::MAX_ORDER_FRACTION);
        let weekend = in_weekend(self.now);
        let reducing = self.only_reducing();
        // Closes come first, everywhere.
        for (index, name) in self.names.iter().enumerate() {
            let carrying = name.tokens > zero() || name.perp_position < zero();
            let due = reducing || !weekend || name.premium() <= decimal(config::EXIT_PREMIUM);
            if carrying && due {
                let short = abs(name.perp_position.min(zero()));
                let per_share = name.perp_ask.max(name.share_price());
                let cap = if per_share > zero() {
                    per_order / per_share
                } else {
                    short
                };
                let shares = short.min(cap);
                // The tokens go only as far as the short already gone leaves
                // them hedged: never a naked short, never more than the
                // shares closed in this step allow.
                let left_short = short - shares;
                let tokens_hedged = if name.multiplier > zero() {
                    left_short / name.multiplier
                } else {
                    zero()
                };
                let tokens = if name.tokens > tokens_hedged {
                    name.tokens - tokens_hedged
                } else {
                    zero()
                };
                if shares > zero() || tokens > zero() {
                    return Step::Close {
                        index,
                        shares,
                        tokens,
                    };
                }
            }
        }
        if !weekend || reducing {
            return Step::Nothing;
        }
        let room = self.vault_value * decimal(config::MAX_GROSS_LEVERAGE) - self.gross();
        let per_name = self.vault_value * decimal(config::TARGET_DEPLOYMENT)
            / Decimal::from(self.names.len().max(1) as u64);
        for (index, name) in self.names.iter().enumerate() {
            if name.paused || name.premium() < decimal(config::ENTRY_PREMIUM) {
                continue;
            }
            let held = name.tokens * name.token_price;
            if held >= per_name {
                continue;
            }
            // Both legs count against the gross limit.
            let dollars = (per_name - held)
                .min(per_order)
                .min(room / Decimal::from(2u8));
            if dollars < decimal(config::MINIMUM_NOTIONAL) || name.token_price <= zero() {
                continue;
            }
            let tokens = dollars / name.token_price;
            return Step::Open {
                index,
                dollars,
                tokens,
                shares: tokens * name.multiplier,
            };
        }
        Step::Nothing
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Saturday 3 October 2026, 12:00 UTC.
    const SATURDAY: u64 = 1_791_028_800;

    fn spy(perp_bid: &str) -> Name {
        Name {
            token: "SPY".into(),
            perp: "SPY".into(),
            token_price: decimal("700"),
            multiplier: decimal("1"),
            paused: false,
            perp_bid: decimal(perp_bid),
            perp_ask: decimal(perp_bid) + decimal("0.05"),
            tokens: zero(),
            perp_position: zero(),
        }
    }

    fn picture(now: u64, names: Vec<Name>) -> Picture {
        Picture {
            now,
            vault_value: decimal("100000"),
            peak: decimal("100000"),
            names,
        }
    }

    #[test]
    fn the_weekend_runs_from_friday_evening_to_mondays_open() {
        assert!(in_weekend(SATURDAY));
        assert!(in_weekend(SATURDAY + 86_400), "Sunday");
        let friday_noon = SATURDAY - 86_400;
        assert!(!in_weekend(friday_noon));
        assert!(in_weekend(friday_noon + 9 * 3600 + 1), "Friday after 21:00");
        let monday_midnight = SATURDAY + 2 * 86_400 - 12 * 3600;
        assert!(in_weekend(monday_midnight + 13 * 3600));
        assert!(
            !in_weekend(monday_midnight + 13 * 3600 + 1800),
            "Monday's open"
        );
        assert!(!in_weekend(SATURDAY + 4 * 86_400), "Wednesday");
    }

    #[test]
    fn a_premium_over_the_entry_opens_one_orders_worth_hedged_share_for_share() {
        let step = picture(SATURDAY, vec![spy("704")]).next();
        let Step::Open {
            dollars,
            tokens,
            shares,
            ..
        } = step
        else {
            panic!("{step:?}")
        };
        assert_eq!(dollars, decimal("5000"), "one order: 5% of the vault");
        assert_eq!(shares, tokens, "a token is one share here");
    }

    #[test]
    fn nothing_opens_outside_the_weekend_below_the_entry_or_on_a_paused_oracle() {
        assert_eq!(
            picture(SATURDAY + 4 * 86_400, vec![spy("704")]).next(),
            Step::Nothing
        );
        assert_eq!(picture(SATURDAY, vec![spy("701")]).next(), Step::Nothing);
        let mut paused = spy("704");
        paused.paused = true;
        assert_eq!(picture(SATURDAY, vec![paused]).next(), Step::Nothing);
    }

    #[test]
    fn a_carry_closes_short_first_and_never_leaves_tokens_short_of_the_hedge() {
        let mut held = spy("700.2");
        held.tokens = decimal("20");
        held.perp_position = decimal("-20");
        let step = picture(SATURDAY, vec![held]).next();
        // The premium is below the exit: close, at most an order's worth.
        let Step::Close { shares, tokens, .. } = step else {
            panic!("{step:?}")
        };
        assert!(shares > zero());
        assert_eq!(tokens, shares, "only as many tokens as the short closed");
    }

    #[test]
    fn after_a_ten_percent_fall_it_only_reduces() {
        let mut held = spy("710");
        held.tokens = decimal("5");
        held.perp_position = decimal("-5");
        let mut p = picture(SATURDAY, vec![held]);
        p.vault_value = decimal("89000");
        assert!(p.only_reducing());
        assert!(matches!(p.next(), Step::Close { .. }));
    }

    #[test]
    fn mondays_open_closes_every_carry() {
        let mut held = spy("710");
        held.tokens = decimal("5");
        held.perp_position = decimal("-5");
        let monday_open = SATURDAY + 2 * 86_400 - 12 * 3600 + 14 * 3600;
        assert!(matches!(
            picture(monday_open, vec![held]).next(),
            Step::Close { .. }
        ));
    }

    #[test]
    fn gross_exposure_stays_within_twice_the_vault() {
        let mut held = spy("710");
        // Already 199k gross of a 100k vault.
        held.tokens = decimal("142");
        held.perp_position = decimal("-142");
        held.token_price = decimal("700");
        let mut other = spy("710");
        other.token = "QQQ".into();
        let step = picture(SATURDAY, vec![held, other]).next();
        assert_eq!(step, Step::Nothing, "{step:?}");
    }
}

//! What this agent says to its two drivers, and hears back: the
//! `robinhood` driver's payloads (stock tokens in the station's Safe) and
//! the `lighter` driver's (the station's Lighter account).
//!
//! These are the drivers' own published payload types, copied verbatim (the
//! same names, fields and serde attributes, so they encode to the same
//! canonical CBOR). They move to the SDK beside Hyperliquid's; this file then
//! becomes two `use` lines.

#![allow(dead_code)]

pub mod robinhood {
    use serde::{Deserialize, Serialize};
    pub use strategy_sdk::Decimal;

    /// The driver's name, as `shonin.toml` writes it.
    pub const DRIVER: &str = "robinhood";

    /// The dollar's symbol: USDG, the chain's native dollar.
    pub const DOLLAR: &str = "USDG";

    /// What a strategy submits.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Action {
        /// Spend `amount` of the dollar on stock token `token`, receiving at
        /// least `min_tokens`.
        Buy {
            token: String,
            amount: Decimal,
            min_tokens: Decimal,
        },
        /// Sell `tokens` of stock token `token` for at least `min_amount`
        /// dollars.
        Sell {
            token: String,
            tokens: Decimal,
            min_amount: Decimal,
        },
    }

    /// What came back inside an accepted verdict.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Receipt {
        /// The swap landed: what was spent and what came back.
        Swapped {
            token: String,
            spent: Decimal,
            received: Decimal,
            transaction: String,
        },
    }

    /// What `account-state` is asked.
    #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Query {
        /// The Safe's holdings, priced.
        Holdings,
        /// Every listed token's prices: its feed's and its pool's.
        Prices,
    }

    /// One listed token's prices, as `Query::Prices` answers.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct TokenPrice {
        pub token: String,
        /// Chainlink's price for the token (the multiplier already applied).
        pub feed_price: Decimal,
        /// When the feed last moved, in seconds since the Unix epoch.
        pub feed_updated_at: u64,
        /// What the token's pool says, averaged over the driver's window.
        pub market_price: Decimal,
        /// Shares of the underlying per token.
        pub multiplier: Decimal,
        /// The issuer has paused the token's oracle.
        pub paused: bool,
    }

    /// One stock token the Safe holds.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct Holding {
        pub token: String,
        /// In shares of the token (its own units, not multiplied: the
        /// multiplier only matters for what a share is a claim on).
        pub tokens: Decimal,
        /// The token's Chainlink price, which already applies the multiplier.
        pub feed_price: Decimal,
        /// When the feed last moved, in seconds since the Unix epoch.
        pub feed_updated_at: u64,
        /// Shares of the underlying per token, from the token's multiplier:
        /// for display, never for valuing.
        pub multiplier: Decimal,
    }

    /// What `account-state` answers.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct AccountState {
        /// The Safe's address.
        pub safe: String,
        /// Idle dollars in the Safe.
        pub dollars: Decimal,
        pub holdings: Vec<Holding>,
    }

    /// Something that happened to the Safe, read from the chain.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum AccountEvent {
        /// Tokens moved into or out of the Safe: a swap, a deposit, a close.
        Moved {
            token: String,
            /// Positive when the Safe received.
            amount: Decimal,
            transaction: String,
            block: u64,
        },
    }
}

