//! The numbers this agent decides with.
//!
//! They are constants in the code rather than settings anywhere else, so the
//! reviewer reads them with the rest of the source, and the claims in
//! `shonin.toml` say the same thing in words.

/// The spot pair held long, as the driver names it, and the venue's own
/// name for its book.
pub const SPOT: &str = "HYPE/USDC";
pub const SPOT_BOOK: &str = "@107";
/// The token the spot leg is held in.
pub const SPOT_TOKEN: &str = "HYPE";
/// Size decimals the venue allows on the spot pair.
pub const SPOT_SIZE_DECIMALS: u32 = 2;
/// The perpetual shorted against it, and its size decimals.
pub const PERP: &str = "HYPE";
pub const PERP_SIZE_DECIMALS: u32 = 2;
/// The HYPE the account keeps for its sends home, which the strategy never
/// sells. Every send of dollars from HyperCore back to the vault costs the
/// account a little HYPE, and the executor buys it from the account's own
/// dollars, never past one HYPE in all. The strategy can't tell that HYPE
/// from its own spot leg, so it leaves the most the executor may hold.
pub const HYPE_KEPT_FOR_SENDS_HOME: &str = "1";
/// The leverage the perp leg is held at: cross margin, and low, since the
/// spot leg is the hedge and the perp only needs to survive the basis.
pub const PERP_LEVERAGE: u32 = 2;

/// Funding, as a fraction of notional per day, at which carrying is worth it.
pub const ENTRY_FUNDING: &str = "0.0002";
/// And at which an open carry is unwound.
pub const EXIT_FUNDING: &str = "0.00005";
/// How much of the vault to aim to have working.
pub const TARGET_DEPLOYMENT: &str = "0.80";
/// Below this, an order is not worth the spread it would pay (and the venue
/// refuses anything under ten dollars).
pub const MINIMUM_NOTIONAL: &str = "100";
/// How far past the best price an immediate order may reach, as a fraction.
pub const SLIPPAGE: &str = "0.002";
/// How far short of its target the carry, or the money behind it at the
/// venue, may fall before anything is done about it, as a fraction of the
/// target. Drift inside it is not worth the transactions it would take.
pub const REBALANCE_BAND: &str = "0.10";

/// Gross exposure at most twice the vault's value.
pub const MAX_GROSS_LEVERAGE: &str = "2";
/// No single order above 5% of the vault.
pub const MAX_ORDER_FRACTION: &str = "0.05";
/// 6% of the vault kept liquid, so an ordinary withdrawal closes nothing:
/// a little above the vault's own 5% idle floor, which it never moves past.
pub const IDLE_BUFFER: &str = "0.06";
/// Only reduces after a 10% fall from the vault's peak.
pub const DRAWDOWN_STOP: &str = "0.10";

//! What the strategy wants to do, worked out from what it can see.
//!
//! Everything here is arithmetic on the account and the latest quotes: no
//! host call, nothing sent. The program around it reads the account, asks
//! what to do, and does it, which is what lets the tests below pin down when
//! the strategy spends gas and when it doesn't.
//!
//! Orders and moves between the account's own perp and spot balances are
//! signed actions on HyperCore and cost no gas. Bringing money from the
//! vault does: a pull and a deposit on HyperEVM, paid from the vault's tank.
//! So the account is funded for the whole carry in one move, counting what
//! is already outside the vault's cash, and only when an order can follow;
//! dollars already waiting in the station go in first.

use hl::{AccountEvent, AccountState, Order, Side, Tif};
use strategy_sdk::hyperliquid as hl;
use strategy_sdk::{Decimal, Limits, decimal, from_payload, size_for};

use crate::config;

/// The limits in `config.rs`, as numbers.
pub fn limits() -> Limits {
    Limits {
        max_gross_leverage: decimal(config::MAX_GROSS_LEVERAGE),
        max_order_fraction: decimal(config::MAX_ORDER_FRACTION),
        idle_buffer: decimal(config::IDLE_BUFFER),
        drawdown_stop: decimal(config::DRAWDOWN_STOP),
    }
}

pub fn zero() -> Decimal {
    Decimal::from(0)
}

fn positive(value: Decimal) -> Decimal {
    if value > zero() { value } else { zero() }
}

fn cap(size: Decimal, most: Decimal) -> Decimal {
    if size > most { most } else { size }
}

/// The first of the fewest equal orders, none above `most`, that add up to
/// `size`.
fn in_equal_orders(size: Decimal, most: Decimal) -> Decimal {
    if size <= most || most <= zero() {
        return cap(size, most);
    }
    size / (size / most).ceil()
}

/// The most of `price` an order may be for: its share of the vault, priced at
/// the furthest the order may fill, so even a fill at the slippage limit stays
/// inside the cap.
pub fn order_size_cap(limits: &Limits, state: &AccountState, price: Decimal) -> Decimal {
    state.vault_value * limits.max_order_fraction
        / (price * (Decimal::from(1) + decimal(config::SLIPPAGE)))
}

/// The best bid and ask of one leg, as last heard.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Top {
    pub bid: Option<Decimal>,
    pub ask: Option<Decimal>,
}

/// What the strategy knows of the market: both legs' books and the funding.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Quotes {
    pub spot: Top,
    pub perp: Top,
    /// Funding, as a fraction of notional per day.
    pub funding: Option<Decimal>,
}

/// The legs as the account holds them: spot tokens, and the perp position
/// (negative when short).
pub fn held(state: &AccountState) -> (Decimal, Decimal) {
    let spot = state
        .spot
        .iter()
        .find(|balance| balance.token == config::SPOT_TOKEN)
        .map_or_else(zero, |balance| balance.total);
    let perp = state
        .positions
        .iter()
        .find(|position| position.market == config::PERP)
        .map_or_else(zero, |position| position.size);
    (spot, perp)
}

/// The dollars on the account's spot side that no order holds.
pub fn spot_dollars(state: &AccountState) -> Decimal {
    state
        .spot
        .iter()
        .find(|balance| balance.token == "USDC")
        .map_or_else(zero, |balance| balance.total - balance.hold)
}

/// `size` rounded down to `decimals` places.
pub fn round_down(size: Decimal, decimals: u32) -> Decimal {
    let scale = Decimal::from(10u64.pow(decimals));
    (size * scale).floor() / scale
}

/// `amount` rounded up to whole cents.
pub fn round_up_cents(amount: Decimal) -> Decimal {
    let scale = Decimal::from(100);
    (amount * scale).ceil() / scale
}

/// An immediate-or-cancel order, its limit written as the venue takes it.
pub fn order(market: &str, side: Side, size: Decimal, limit: Decimal, reduce_only: bool) -> Order {
    Order {
        market: market.to_string(),
        side,
        size,
        limit_price: five_figures(limit, side),
        tif: Tif::Ioc,
        reduce_only,
        client_id: None,
    }
}

/// A price at five significant figures, the most the venue takes, rounded
/// away from the market (down for a buy, up for a sell) so it never reaches
/// further than meant.
pub fn five_figures(price: Decimal, side: Side) -> Decimal {
    if price <= zero() {
        return price;
    }
    let mut scale = Decimal::from(1);
    let ten = Decimal::from(10);
    while price * scale < Decimal::from(10_000) {
        scale *= ten;
    }
    while price * scale >= Decimal::from(100_000) {
        scale /= ten;
    }
    let scaled = price * scale;
    let rounded = match side {
        Side::Buy => scaled.floor(),
        Side::Sell => scaled.ceil(),
    };
    rounded / scale
}

/// Dollars to bring to the account before trading. Each part is one move:
/// the station's idle dollars in one deposit, the vault's cash in a pull and
/// a deposit.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Funding {
    pub from_station: Decimal,
    pub from_vault: Decimal,
}

/// What to do now.
#[derive(Clone, Debug, PartialEq)]
pub enum Plan {
    /// Nothing would move the carry far enough to be worth doing.
    Nothing,
    /// Fund the account as `fund` says, buy `spot` if there is one, then
    /// short the perpetual to match what the spot holds (see [`hedge`]).
    Build { fund: Funding, spot: Option<Order> },
    /// Buy back `perp` if there is one, then sell the spot down to what is
    /// still short (see [`trim`]).
    Reduce { perp: Option<Order> },
}

/// Which side of the funding thresholds the market is on.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Regime {
    /// Worth opening.
    Open,
    /// Worth holding, not adding to.
    Hold,
    /// Worth unwinding.
    Exit,
}

pub fn regime(funding: Decimal) -> Regime {
    if funding >= decimal(config::ENTRY_FUNDING) {
        Regime::Open
    } else if funding < decimal(config::EXIT_FUNDING) {
        Regime::Exit
    } else {
        Regime::Hold
    }
}

/// Whether a funding update is worth looking at the account for.
///
/// The venue sends one every few seconds. When the last look found nothing
/// to do and the funding is on the same side of its thresholds, nothing it
/// says can change the answer; the account's own events (fills, the hourly
/// funding payment) still wake the strategy whatever the funding does.
pub fn steps_on_funding(before: Option<Decimal>, now: Decimal, busy: bool) -> bool {
    busy || before.map(regime) != Some(regime(now))
}

/// Whether an event on the account is worth looking at it for. An order's
/// change of state says nothing a fill doesn't: an order that filled sends
/// its fill too, and one cancelled unfilled changed nothing.
pub fn wakes_for(event: &[u8]) -> bool {
    !matches!(
        from_payload::<AccountEvent>(event),
        Ok(AccountEvent::Order { .. })
    )
}

/// Whether the vault has fallen far enough from its peak that this strategy
/// should stop opening anything and only get smaller.
pub fn only_reducing(peak: Decimal, value: Decimal, limits: &Limits) -> bool {
    peak > zero() && (peak - value) / peak >= limits.drawdown_stop
}

/// What both legs are worth at the prices they would close at.
pub fn gross(state: &AccountState, quotes: &Quotes) -> Decimal {
    let (spot, perp) = held(state);
    legs_gross(quotes, spot, perp)
}

/// What the legs would be worth at those prices, held as `spot` and `perp`.
fn legs_gross(quotes: &Quotes, spot: Decimal, perp: Decimal) -> Decimal {
    let spot_price = quotes.spot.ask.unwrap_or_else(zero);
    let perp_price = quotes.perp.bid.unwrap_or_else(zero);
    positive(spot) * spot_price + positive(-perp) * perp_price
}

/// Work out what to do, given the account, the market, the most the vault
/// has been worth, and the vault's cash that leavers are waiting on (see
/// [`Leavers`]).
pub fn decide(
    limits: &Limits,
    peak: Decimal,
    for_leavers: Decimal,
    state: &AccountState,
    quotes: &Quotes,
) -> Plan {
    let Some(funding) = quotes.funding else {
        return Plan::Nothing;
    };
    let (spot, perp) = held(state);
    let holding = spot > zero() || perp < zero();
    let reducing = only_reducing(peak, state.vault_value, limits);

    if holding && (reducing || regime(funding) == Regime::Exit) {
        let perp_order = unwind(limits, state, quotes);
        if perp_order.is_none() && trim(limits, state, quotes, spot, perp).is_none() {
            return Plan::Nothing;
        }
        return Plan::Reduce { perp: perp_order };
    }
    if reducing {
        return Plan::Nothing;
    }
    // A leg that didn't fill last time may have left the two sides apart.
    // They are levelled before anything is added: buying more spot while
    // some is still unhedged would only grow a position with a view on the
    // price.
    if hedge(limits, state, quotes, spot, perp).is_some() {
        return Plan::Build {
            fund: Funding::default(),
            spot: None,
        };
    }
    if regime(funding) == Regime::Open
        && let Some((fund, spot_order)) = build_step(limits, for_leavers, state, quotes)
    {
        return Plan::Build {
            fund,
            spot: Some(spot_order),
        };
    }
    Plan::Nothing
}

/// The notional of each leg of the next pair: half what is still wanted,
/// since a pair adds both legs to the gross, inside the order cap and the
/// leverage ceiling.
pub fn pair_notional(
    wanted: Decimal,
    vault_value: Decimal,
    gross: Decimal,
    limits: &Limits,
    minimum: Decimal,
) -> Decimal {
    let two = Decimal::from(2);
    let per_leg = size_for(wanted / two, vault_value, gross, limits, minimum);
    let headroom = positive(vault_value * limits.max_gross_leverage - gross) / two;
    let per_leg = cap(per_leg, headroom);
    if per_leg < minimum { zero() } else { per_leg }
}

/// The dollars one dollar of pair takes from the account: the spot paid in
/// full at its limit, and the short's margin at its leverage.
fn dollars_per_dollar() -> Decimal {
    Decimal::from(1)
        + decimal(config::SLIPPAGE)
        + Decimal::from(1) / Decimal::from(config::PERP_LEVERAGE)
}

/// The next pair's spot leg, and what has to reach the account first to pay
/// for it; nothing if the carry is close enough to its target, or if the
/// order couldn't be paid for even after moving what may be moved.
fn build_step(
    limits: &Limits,
    for_leavers: Decimal,
    state: &AccountState,
    quotes: &Quotes,
) -> Option<(Funding, Order)> {
    let (Some(spot_ask), Some(perp_bid)) = (quotes.spot.ask, quotes.perp.bid) else {
        return None;
    };
    if spot_ask <= zero() || perp_bid <= zero() || state.vault_value <= zero() {
        return None;
    }
    let minimum = decimal(config::MINIMUM_NOTIONAL);
    let band = decimal(config::REBALANCE_BAND);
    let working = state.vault_value * decimal(config::TARGET_DEPLOYMENT);
    let gross = gross(state, quotes);
    let wanted = positive(working - gross);
    if wanted < working * band {
        return None;
    }
    let per_leg = pair_notional(wanted, state.vault_value, gross, limits, minimum);
    if per_leg <= zero() {
        return None;
    }

    let fund = funding_for(limits, for_leavers, state, per_leg);
    let available = positive(spot_dollars(state))
        + positive(state.withdrawable)
        + fund.from_station
        + fund.from_vault;
    let notional = cap(per_leg, available / dollars_per_dollar());
    let size = round_down(
        cap(notional / spot_ask, order_size_cap(limits, state, spot_ask)),
        config::SPOT_SIZE_DECIMALS,
    );
    if size * spot_ask < minimum {
        // No order can follow, so nothing is moved either.
        return None;
    }
    let reach = Decimal::from(1) + decimal(config::SLIPPAGE);
    Some((
        fund,
        order(config::SPOT, Side::Buy, size, spot_ask * reach, false),
    ))
}

/// What to bring to the account before buying `per_leg` of spot.
///
/// The account is meant to hold the whole carry at target: the spot leg paid
/// in full and the short's notional again as its margin, which is the
/// deployment target of the vault. Every dollar outside the vault's cash
/// counts towards it, including any waiting in the station. Money is moved
/// only when the next pair couldn't be paid without it, or when the account
/// is short of that by more than the band, and then the whole shortfall goes
/// in one move rather than an order's worth at a time: the station's idle
/// dollars first, then the vault's cash. The vault's cash that leavers are
/// waiting on, `for_leavers`, is never part of it.
pub fn funding_for(
    limits: &Limits,
    for_leavers: Decimal,
    state: &AccountState,
    per_leg: Decimal,
) -> Funding {
    let goal = state.vault_value * decimal(config::TARGET_DEPLOYMENT);
    let outside = positive(state.vault_value - state.idle);
    let short_of_goal = positive(goal - outside);
    let available = positive(spot_dollars(state)) + positive(state.withdrawable);
    let needed_now = positive(per_leg * dollars_per_dollar() - available);
    if needed_now <= zero() && short_of_goal < goal * decimal(config::REBALANCE_BAND) {
        return Funding::default();
    }
    // A move too small to place an order with is not worth its gas.
    let worth = |amount: Decimal| {
        if amount < decimal(config::MINIMUM_NOTIONAL) {
            zero()
        } else {
            amount
        }
    };
    // What waits in the station earns nothing there, and it takes one
    // deposit however much of it goes, so all of it goes.
    let from_station = worth(positive(state.station_idle));
    // The buffer stays in the vault, where a withdrawal reaches it without
    // closing anything, and so does what leavers are waiting on.
    let spare =
        positive(state.idle - state.vault_value * limits.idle_buffer - positive(for_leavers));
    // The shortfall from the goal already counts the station's dollars; the
    // next pair's needs don't.
    let still = if short_of_goal > needed_now - from_station {
        short_of_goal
    } else {
        positive(needed_now - from_station)
    };
    let from_vault = worth(cap(still, spare));
    Funding {
        from_station,
        from_vault,
    }
}

/// The perpetual order that brings the short level with `spot_held`, as long
/// as the gap is worth an order: a sale when the spot is ahead, a reduce-only
/// purchase when the short is. A gap wider than one order is closed in equal
/// orders, so the last of it is never a sliver too small to send.
pub fn hedge(
    limits: &Limits,
    state: &AccountState,
    quotes: &Quotes,
    spot_held: Decimal,
    perp_held: Decimal,
) -> Option<Order> {
    let minimum = decimal(config::MINIMUM_NOTIONAL);
    let slip = decimal(config::SLIPPAGE);
    let one = Decimal::from(1);
    let gap = round_down(spot_held, config::PERP_SIZE_DECIMALS) + perp_held;
    if gap > zero() {
        let bid = quotes.perp.bid.filter(|bid| *bid > zero())?;
        let gross = legs_gross(quotes, spot_held, perp_held);
        let headroom = positive(state.vault_value * limits.max_gross_leverage - gross);
        let size = round_down(
            cap(
                in_equal_orders(gap, order_size_cap(limits, state, bid)),
                headroom / bid,
            ),
            config::PERP_SIZE_DECIMALS,
        );
        (size * bid >= minimum)
            .then(|| order(config::PERP, Side::Sell, size, bid * (one - slip), false))
    } else if gap < zero() && perp_held < zero() {
        let ask = quotes.perp.ask.filter(|ask| *ask > zero())?;
        let size = round_down(
            in_equal_orders(cap(-gap, -perp_held), order_size_cap(limits, state, ask)),
            config::PERP_SIZE_DECIMALS,
        );
        (size * ask >= minimum)
            .then(|| order(config::PERP, Side::Buy, size, ask * (one + slip), true))
    } else {
        None
    }
}

/// One order's worth of the short bought back, if there is a short.
pub fn unwind(limits: &Limits, state: &AccountState, quotes: &Quotes) -> Option<Order> {
    let (_, perp) = held(state);
    let ask = quotes.perp.ask.filter(|ask| *ask > zero())?;
    if perp >= zero() {
        return None;
    }
    let size = round_down(
        cap(-perp, order_size_cap(limits, state, ask)),
        config::PERP_SIZE_DECIMALS,
    );
    let slip = decimal(config::SLIPPAGE);
    (size > zero()).then(|| {
        order(
            config::PERP,
            Side::Buy,
            size,
            ask * (Decimal::from(1) + slip),
            true,
        )
    })
}

/// The spot sale that brings the spot down to what is still short. Closing
/// the spot ahead of the short would leave a naked short. The account keeps
/// some of the same token to pay for its sends home, and that is not the
/// strategy's to sell: [`config::HYPE_KEPT_FOR_SENDS_HOME`] always stays,
/// however much is sold around it. A remainder too small to be worth an
/// order stays too.
pub fn trim(
    limits: &Limits,
    state: &AccountState,
    quotes: &Quotes,
    spot_held: Decimal,
    perp_held: Decimal,
) -> Option<Order> {
    let bid = quotes.spot.bid.filter(|bid| *bid > zero())?;
    let sellable = positive(spot_held - decimal(config::HYPE_KEPT_FOR_SENDS_HOME));
    let excess = cap(spot_held + perp_held, sellable);
    if excess <= zero() {
        return None;
    }
    let size = round_down(
        cap(excess, order_size_cap(limits, state, bid)),
        config::SPOT_SIZE_DECIMALS,
    );
    let slip = decimal(config::SLIPPAGE);
    (size * bid >= decimal(config::MINIMUM_NOTIONAL)).then(|| {
        order(
            config::SPOT,
            Side::Sell,
            size,
            bid * (Decimal::from(1) - slip),
            false,
        )
    })
}

/// The vault's cash that leavers are waiting on, as far as the strategy can
/// tell.
///
/// A withdrawal the vault's cash can't cover waits for the next valuation,
/// and `buffer-low` says so: the agent brings the shortfall home from the
/// account. Until a valuation pays the leavers, everything the vault then
/// holds above its buffer is theirs, and moving it back out would only send
/// it on a round trip at the tank's expense. The vault's cash falling by
/// more than the agent itself took out is the leavers being paid, and it
/// frees what was held for them by as much.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Leavers {
    held: Decimal,
    last_idle: Option<Decimal>,
}

impl Leavers {
    /// Cash has been brought home for leavers, and the vault now looks like
    /// `state`.
    pub fn brought_home(&mut self, limits: &Limits, state: &AccountState) {
        self.held = positive(state.idle - state.vault_value * limits.idle_buffer);
        self.last_idle = Some(state.idle);
    }

    /// The vault's cash as read now.
    pub fn seen(&mut self, idle: Decimal) {
        if let Some(last) = self.last_idle
            && idle < last
        {
            self.held = positive(self.held - (last - idle));
        }
        self.last_idle = Some(idle);
    }

    /// The agent asked to take `amount` out of the vault's cash, which is not
    /// a leaver being paid. Counted whether or not it went, which at worst
    /// holds the leavers' cash a little longer.
    pub fn taken(&mut self, amount: Decimal) {
        if let Some(last) = &mut self.last_idle {
            *last -= amount;
        }
    }

    /// What is held for them now.
    pub fn held(&self) -> Decimal {
        self.held
    }
}

/// What the account looked like when the venue or the station last said no:
/// what only the strategy's own actions, a deposit or a withdrawal change.
#[derive(Clone, Debug, PartialEq)]
pub struct Snapshot {
    spot: Decimal,
    perp: Decimal,
    spot_dollars: Decimal,
    withdrawable: Decimal,
    idle: Decimal,
    station_idle: Decimal,
}

impl Snapshot {
    pub fn of(state: &AccountState) -> Self {
        let (spot, perp) = held(state);
        Self {
            spot,
            perp,
            spot_dollars: spot_dollars(state),
            withdrawable: state.withdrawable,
            idle: state.idle,
            station_idle: state.station_idle,
        }
    }
}

/// The most wake-ups a refusal is waited out for.
const PATIENCE_MOST: u32 = 64;

/// How long to leave a plan the venue or the station refused: a number of
/// wake-ups that doubles with each refusal in a row, up to
/// [`PATIENCE_MOST`], and ends at once when the account changes. It counts
/// events rather than time, so the agent still never sleeps on a timer.
#[derive(Debug, Default)]
pub struct Patience {
    refused_at: Option<Snapshot>,
    strikes: u32,
    waiting: u32,
}

impl Patience {
    /// Whether to hold back now, with the account as it is.
    pub fn holds_back(&mut self, now: &Snapshot) -> bool {
        match &self.refused_at {
            Some(then) if then == now => {
                if self.waiting > 0 {
                    self.waiting -= 1;
                    true
                } else {
                    false
                }
            }
            Some(_) => {
                *self = Self::default();
                false
            }
            None => false,
        }
    }

    /// The plan made with the account at `at` was refused.
    pub fn refused(&mut self, at: Snapshot) {
        self.strikes = if self.refused_at.as_ref() == Some(&at) {
            self.strikes + 1
        } else {
            1
        };
        self.waiting = (1u32 << self.strikes.min(6)).min(PATIENCE_MOST) - 1;
        self.refused_at = Some(at);
    }

    /// Something went through: the next plan is tried at once.
    pub fn went_through(&mut self) {
        *self = Self::default();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use hl::{Position, SpotBalance};

    fn d(text: &str) -> Decimal {
        decimal(text)
    }

    const ABOVE_ENTRY: &str = "0.001";
    const BELOW_EXIT: &str = "0.00001";

    fn quotes(funding: &str) -> Quotes {
        let top = Top {
            bid: Some(d("24.99")),
            ask: Some(d("25.01")),
        };
        Quotes {
            spot: top,
            perp: top,
            funding: Some(d(funding)),
        }
    }

    /// A vault with `idle` in its own cash and `perp_side` dollars on the
    /// account's perp side, nothing open.
    fn state(idle: &str, perp_side: &str) -> AccountState {
        let mut state = AccountState {
            vault_value: zero(),
            idle: d(idle),
            station_idle: zero(),
            account_value: d(perp_side),
            withdrawable: d(perp_side),
            positions: Vec::new(),
            spot: vec![
                SpotBalance {
                    token: "USDC".to_string(),
                    total: zero(),
                    hold: zero(),
                },
                SpotBalance {
                    token: config::SPOT_TOKEN.to_string(),
                    total: zero(),
                    hold: zero(),
                },
            ],
            open_orders: Vec::new(),
        };
        revalue(&mut state);
        state
    }

    fn balance<'a>(state: &'a mut AccountState, token: &str) -> &'a mut SpotBalance {
        state
            .spot
            .iter_mut()
            .find(|balance| balance.token == token)
            .unwrap()
    }

    fn revalue(state: &mut AccountState) {
        let (spot, _) = held(state);
        state.vault_value = state.idle
            + state.station_idle
            + state.account_value
            + spot_dollars(state)
            + spot * d("25");
    }

    fn perp_size(state: &mut AccountState) -> &mut Decimal {
        if state.positions.is_empty() {
            state.positions.push(Position {
                market: config::PERP.to_string(),
                size: zero(),
                entry_price: None,
                leverage: config::PERP_LEVERAGE,
            });
        }
        &mut state.positions[0].size
    }

    /// Fill `order` at the quote, and keep the account's books the way the
    /// venue does: the spot paid from the spot side's dollars, the short's
    /// margin held on the perp side.
    fn fill(state: &mut AccountState, order: &Order) {
        let margin = Decimal::from(config::PERP_LEVERAGE);
        match (order.market.as_str(), order.side) {
            (config::SPOT, Side::Buy) => {
                balance(state, "USDC").total -= order.size * d("25.01");
                balance(state, config::SPOT_TOKEN).total += order.size;
            }
            (config::SPOT, Side::Sell) => {
                balance(state, "USDC").total += order.size * d("24.99");
                balance(state, config::SPOT_TOKEN).total -= order.size;
            }
            (_, Side::Sell) => {
                *perp_size(state) -= order.size;
                state.withdrawable -= order.size * d("25") / margin;
            }
            (_, Side::Buy) => {
                *perp_size(state) += order.size;
                state.withdrawable += order.size * d("25") / margin;
            }
        }
        revalue(state);
    }

    /// Carry `plan` out as the agent would, counting what costs gas (a
    /// deposit for a move from the station, a pull and a deposit for one from
    /// the vault) apart from the actions on the venue, which don't.
    fn carry_out(state: &mut AccountState, plan: &Plan) -> (usize, usize) {
        let limits = limits();
        let quotes = quotes(ABOVE_ENTRY);
        let (mut gas, mut actions) = (0, 0);
        match plan {
            Plan::Nothing => {}
            Plan::Build { fund, spot } => {
                if fund.from_station > zero() {
                    state.station_idle -= fund.from_station;
                    state.account_value += fund.from_station;
                    state.withdrawable += fund.from_station;
                    gas += 1;
                }
                if fund.from_vault > zero() {
                    state.idle -= fund.from_vault;
                    state.account_value += fund.from_vault;
                    state.withdrawable += fund.from_vault;
                    gas += 2;
                }
                if let Some(order) = spot {
                    let cost = order.size * order.limit_price;
                    let short = cost - spot_dollars(state);
                    if short > zero() {
                        let moving = round_up_cents(short);
                        state.withdrawable -= moving;
                        state.account_value -= moving;
                        balance(state, "USDC").total += moving;
                        actions += 1;
                    }
                    fill(state, order);
                    actions += 1;
                }
                for _ in 0..8 {
                    let (spot, perp) = held(state);
                    let Some(order) = hedge(&limits, state, &quotes, spot, perp) else {
                        break;
                    };
                    fill(state, &order);
                    actions += 1;
                }
            }
            Plan::Reduce { perp } => {
                if let Some(order) = perp {
                    fill(state, order);
                    actions += 1;
                }
                let (spot, perp) = held(state);
                if let Some(order) = trim(&limits, state, &quotes, spot, perp) {
                    fill(state, &order);
                    actions += 1;
                }
            }
        }
        (gas, actions)
    }

    fn plan(state: &AccountState, quotes: &Quotes) -> Plan {
        decide(&limits(), state.vault_value, zero(), state, quotes)
    }

    fn settle(state: &mut AccountState) -> (usize, usize) {
        let quotes = quotes(ABOVE_ENTRY);
        let (mut gas, mut actions) = (0, 0);
        for _ in 0..100 {
            let next = plan(state, &quotes);
            if next == Plan::Nothing {
                return (gas, actions);
            }
            let (g, a) = carry_out(state, &next);
            gas += g;
            actions += a;
        }
        panic!("the agent never settled");
    }

    #[test]
    fn a_deposit_is_brought_to_the_venue_in_one_move() {
        let mut state = state("25000", "0");
        let Plan::Build { fund, .. } = plan(&state, &quotes(ABOVE_ENTRY)) else {
            panic!("a fresh deposit with funding above entry opens");
        };
        assert_eq!(fund.from_vault, d("20000"));
        let (gas, _) = settle(&mut state);
        assert_eq!(gas, 2, "one pull and one deposit");
        let (spot, perp) = held(&state);
        assert_eq!(spot, -perp, "the legs are level");
        let target = state.vault_value * d(config::TARGET_DEPLOYMENT);
        let gross = gross(&state, &quotes(ABOVE_ENTRY));
        assert!(gross >= target * d("0.9") && gross <= target, "{gross}");
    }

    #[test]
    fn a_quiet_market_sends_nothing() {
        let mut state = state("25000", "0");
        settle(&mut state);
        for _ in 0..1000 {
            state.account_value += d("0.01");
            state.withdrawable += d("0.01");
            revalue(&mut state);
            assert_eq!(plan(&state, &quotes(ABOVE_ENTRY)), Plan::Nothing);
        }
    }

    #[test]
    fn cash_already_at_the_venue_is_used_before_more_is_moved() {
        let state = state("2000", "23000");
        let Plan::Build { fund, spot } = plan(&state, &quotes(ABOVE_ENTRY)) else {
            panic!("it opens");
        };
        assert_eq!(fund, Funding::default());
        assert!(spot.is_some());
    }

    #[test]
    fn nothing_is_moved_when_no_order_could_follow() {
        let mut state = state("1500", "50");
        state.vault_value = d("25000");
        assert_eq!(plan(&state, &quotes(ABOVE_ENTRY)), Plan::Nothing);
    }

    #[test]
    fn funding_updates_on_the_same_side_of_the_thresholds_do_not_wake_an_idle_agent() {
        let above = d(ABOVE_ENTRY);
        assert!(steps_on_funding(None, above, false));
        assert!(!steps_on_funding(Some(above), above * d("1.1"), false));
        assert!(steps_on_funding(Some(above), d("0.0001"), false));
        assert!(steps_on_funding(Some(above), above, true));
    }

    #[test]
    fn an_order_changing_state_does_not_wake_it_but_a_fill_does() {
        let changed = strategy_sdk::to_payload(&AccountEvent::Order {
            market: config::PERP.to_string(),
            order_id: 1,
            client_id: None,
            status: "canceled".to_string(),
            time_ms: 0,
        });
        assert!(!wakes_for(&changed));
        let paid = strategy_sdk::to_payload(&AccountEvent::Funding {
            market: config::PERP.to_string(),
            amount: d("1"),
            time_ms: 0,
        });
        assert!(wakes_for(&paid));
    }

    #[test]
    fn an_unwind_never_sells_spot_ahead_of_the_short() {
        let mut state = state("5000", "20000");
        settle(&mut state);
        let exit = quotes(BELOW_EXIT);
        let Plan::Reduce { perp: Some(perp) } = plan(&state, &exit) else {
            panic!("funding below exit unwinds");
        };
        let (spot, short) = held(&state);
        assert_eq!(trim(&limits(), &state, &exit, spot, short), None);
        let spot_order = trim(&limits(), &state, &exit, spot, short + perp.size).unwrap();
        assert_eq!(spot_order.size, perp.size);
    }

    #[test]
    fn a_little_of_the_token_kept_for_sends_home_is_never_sold() {
        let mut state = state("15000", "10000");
        balance(&mut state, config::SPOT_TOKEN).total = d("0.5");
        revalue(&mut state);
        assert_eq!(plan(&state, &quotes(BELOW_EXIT)), Plan::Nothing);
    }

    /// The executor keeps up to a whole HYPE on the account to pay for
    /// sends home. However much spot an unwind or a halt sells, that much is
    /// left: the strategy can't tell it from its own, so it never sells it.
    #[test]
    fn the_hype_kept_for_sends_home_is_never_sold() {
        // The short is bought back; the account holds the carry's 9 HYPE and
        // the 0.1 HYPE the executor bought for sends home.
        let mut state = state("1000", "5000");
        balance(&mut state, config::SPOT_TOKEN).total = d("9.1");
        revalue(&mut state);
        let exit = quotes(BELOW_EXIT);
        let kept = d(config::HYPE_KEPT_FOR_SENDS_HOME);
        let order = trim(&limits(), &state, &exit, d("9.1"), zero()).expect("a sale");
        assert_eq!(order.size, d("9.1") - kept);

        // A halt lifts the order cap and sells everything it may, in one go.
        let halt = Limits {
            max_order_fraction: Decimal::from(1),
            ..limits()
        };
        balance(&mut state, config::SPOT_TOKEN).total = d("40");
        revalue(&mut state);
        let order = trim(&halt, &state, &exit, d("40"), zero()).expect("a sale");
        assert_eq!(order.size, d("40") - kept);
        // And with only the reserve left, nothing is sold.
        assert_eq!(trim(&halt, &state, &exit, kept, zero()), None);
    }

    /// Every order the strategy sends, filled at the furthest its slippage
    /// lets it, is still no more than 5% of the vault, as the manifest
    /// claims: the spot buys while building, the shorts that hedge them, the
    /// short bought back and the spot sold on the way out.
    #[test]
    fn an_order_filled_at_its_slippage_limit_is_never_above_its_share_of_the_vault() {
        let limits = limits();
        let open = quotes(ABOVE_ENTRY);
        let reach = Decimal::from(1) + d(config::SLIPPAGE);
        let within = |state: &AccountState, order: &Order| {
            let cap = state.vault_value * d(config::MAX_ORDER_FRACTION);
            let top = if order.market == config::SPOT {
                open.spot
            } else {
                open.perp
            };
            let price = match order.side {
                Side::Buy => top.ask.unwrap(),
                // A sale fills at the bid or below; the bid itself is the
                // most it is worth.
                Side::Sell => top.bid.unwrap(),
            };
            let furthest = order.size * price * reach;
            assert!(
                furthest <= cap,
                "{order:?} could fill at {furthest} of a {cap} cap"
            );
        };
        let mut state = state("100000", "0");
        let mut orders = 0;
        for _ in 0..40 {
            let next = plan(&state, &open);
            if let Plan::Build {
                spot: Some(order), ..
            } = &next
            {
                within(&state, order);
                let mut after = state.clone();
                balance(&mut after, "USDC").total += d("100000");
                fill(&mut after, order);
                let (spot, perp) = held(&after);
                within(&state, &hedge(&limits, &state, &open, spot, perp).unwrap());
                orders += 2;
            }
            if next == Plan::Nothing {
                break;
            }
            carry_out(&mut state, &next);
        }
        assert!(orders > 0);
        let exit = quotes(BELOW_EXIT);
        let Plan::Reduce { perp: Some(perp) } = plan(&state, &exit) else {
            panic!("funding below exit unwinds");
        };
        within(&state, &perp);
        let (spot, short) = held(&state);
        within(
            &state,
            &trim(&limits, &state, &exit, spot, short + perp.size).unwrap(),
        );
    }

    /// A spot buy whose short missed leaves the vault with a view on the
    /// price. The next step shorts against it before buying anything more,
    /// and keeps shorting, an order at a time, until the two legs are level.
    #[test]
    fn spot_left_without_its_short_is_hedged_before_more_is_bought() {
        // 500 HYPE ($12,500, two and a half orders' worth) bought in a
        // $100,000 vault; its short missed.
        let mut state = state("50000", "37500");
        balance(&mut state, config::SPOT_TOKEN).total = d("500");
        revalue(&mut state);
        let first = plan(&state, &quotes(ABOVE_ENTRY));
        let Plan::Build { fund, spot: None } = &first else {
            panic!("more spot is bought on top of an unhedged 500 HYPE: {first:?}");
        };
        assert_eq!(*fund, Funding::default(), "nothing is moved to hedge");
        let (gas, actions) = carry_out(&mut state, &first);
        assert_eq!((gas, actions), (0, 3), "three orders, each inside the cap");
        let (spot, perp) = held(&state);
        assert_eq!(spot, -perp);
    }

    /// Dollars waiting in the station earn nothing there. They go to the
    /// account first, in one deposit, and only the rest comes from the
    /// vault's cash.
    #[test]
    fn money_waiting_in_the_station_goes_on_before_any_more_is_pulled() {
        let mut state = state("15000", "0");
        state.station_idle = d("10000");
        revalue(&mut state);
        let Plan::Build { fund, .. } = plan(&state, &quotes(ABOVE_ENTRY)) else {
            panic!("it opens");
        };
        assert_eq!(fund.from_station, d("10000"));
        assert_eq!(fund.from_vault, d("10000"));
        let (gas, _) = settle(&mut state);
        assert_eq!(gas, 3, "one deposit from the station, one pull and deposit");
        assert_eq!(state.station_idle, zero());
    }

    /// `buffer-low` brings cash home from the account for leavers waiting on
    /// a valuation. Until the valuation pays them, that cash stays in the
    /// vault however far the carry is from its target.
    #[test]
    fn cash_brought_home_for_leavers_is_not_sent_back_out() {
        // A $25,000 vault with nothing open, and $20,000 just brought home
        // for leavers.
        let home = state("25000", "0");
        let mut leavers = Leavers::default();
        leavers.brought_home(&limits(), &home);
        let decided = |state: &AccountState, leavers: &Leavers| {
            decide(
                &limits(),
                state.vault_value,
                leavers.held(),
                state,
                &quotes(ABOVE_ENTRY),
            )
        };
        assert_eq!(decided(&home, &leavers), Plan::Nothing);

        // A valuation pays them, and the vault's cash falls by as much.
        leavers.seen(d("1500"));
        assert_eq!(leavers.held(), zero());
        let deposit = state("25000", "0");
        leavers.seen(deposit.idle);
        let Plan::Build { fund, .. } = decided(&deposit, &leavers) else {
            panic!("a deposit after the leavers are paid is put to work");
        };
        assert_eq!(fund.from_vault, d("20000"));
    }

    #[test]
    fn a_refusal_is_not_resent_on_every_event() {
        let at = Snapshot::of(&state("25000", "0"));
        let mut patience = Patience::default();
        let mut tried = 0;
        for _ in 0..200 {
            if !patience.holds_back(&at) {
                tried += 1;
                patience.refused(at.clone());
            }
        }
        assert!((4..=8).contains(&tried), "{tried} tries in 200 wake-ups");
    }

    #[test]
    fn prices_keep_five_figures_and_never_reach_further_than_meant() {
        assert_eq!(five_figures(d("22.51234"), Side::Buy), d("22.512"));
        assert_eq!(five_figures(d("22.51234"), Side::Sell), d("22.513"));
        assert_eq!(five_figures(d("2710.55"), Side::Buy), d("2710.5"));
        assert_eq!(five_figures(d("123456"), Side::Sell), d("123460"));
    }

    #[test]
    fn sizes_round_down_to_the_venues_decimals() {
        assert_eq!(round_down(d("1.239"), 2), d("1.23"));
        assert_eq!(round_down(d("7"), 0), d("7"));
    }
}

//! Holds spot, shorts the perpetual against it, and collects the funding, on
//! Hyperliquid.
//!
//! The same strategy as `funding-basis`, on the venue it was meant for: both
//! legs in one HyperCore account that the vault's station owns. The account
//! is the station's, so the agent's key can trade it and move dollars
//! between its own perp and spot balances, and nothing else.
//!
//! Prices and funding come from Shonin's shared Hyperliquid stream; the
//! account comes from the driver. The agent keeps the latest book of each
//! leg as they arrive, and takes one step towards what it wants to hold when
//! funding crosses a threshold or its account changes, if that step is worth
//! doing (`decide.rs` says when it is). It never polls.

mod config;
mod decide;

use decide::{
    Leavers, Patience, Plan, Quotes, Snapshot, Top, hedge, held, limits, spot_dollars, trim, unwind,
};
use futures::StreamExt;
use hl::{AccountState, Action, Balance, Order, Receipt, Side};
use sdk::streams::{self, HYPERLIQUID, HyperliquidFeed, HyperliquidValue};
use sdk::transfers::{self, Account, Moved, VenueAccount};
use sdk::{Decimal, Limits, drivers, from_payload, millionths, to_payload, vault};
use strategy_sdk as sdk;
use strategy_sdk::hyperliquid as hl;

/// The driver this agent trades through, as its manifest names it.
const DRIVER: &str = hl::DRIVER;

/// How many steps a halt may take to flatten the book before leaving the
/// rest to the contract.
const FLATTEN_STEPS: usize = 32;

/// How many perpetual orders one step may send to level the short with the
/// spot. One is almost always enough; more are for a gap wider than the
/// order cap, or an order that only partly filled.
const HEDGE_ORDERS: usize = 8;

struct FundingBasis;

/// What the strategy knows. Rebuilt from the venue and the stream whenever
/// it starts, so losing it to a restart costs a moment and nothing else.
struct Mind {
    limits: Limits,
    quotes: Quotes,
    /// The most the vault has been worth while this instance watched it.
    peak: Decimal,
    /// Whether the perp's leverage has been set since this instance began.
    levered: bool,
    /// Whether the last look found something to do, so the next funding
    /// update is worth another.
    busy: bool,
    /// How long to leave a plan the venue or the station refused.
    patience: Patience,
    /// The vault's cash that leavers are waiting on. Lost to a restart, which
    /// at worst sends it out once more for the next `buffer-low` to bring
    /// back.
    leavers: Leavers,
}

impl Mind {
    fn new() -> Self {
        Self {
            limits: limits(),
            quotes: Quotes::default(),
            peak: decide::zero(),
            levered: false,
            busy: false,
            patience: Patience::default(),
            leavers: Leavers::default(),
        }
    }
}

/// What woke the strategy up.
enum Woke {
    Venue(Vec<u8>),
    Vault(vault::VaultEvent),
    SpotBook(Top),
    PerpBook(Top),
    Funding(Decimal),
    /// A stream value that didn't read: ignored.
    Nothing,
}

fn top_of(value: Result<streams::Stamped<HyperliquidValue>, String>) -> Option<Top> {
    match value.ok()?.value {
        HyperliquidValue::Book(book) => Some(Top {
            bid: book.bids.first().map(|level| level.price),
            ask: book.asks.first().map(|level| level.price),
        }),
        _ => None,
    }
}

impl sdk::Agent for FundingBasis {
    async fn run() -> Result<(), String> {
        let mut mind = Mind::new();

        let spot_book = streams::subscribe::<_, HyperliquidValue>(
            HYPERLIQUID,
            &HyperliquidFeed::Book {
                coin: config::SPOT_BOOK.into(),
            },
        )?
        .map(|value| top_of(value).map_or(Woke::Nothing, Woke::SpotBook));
        let perp_book = streams::subscribe::<_, HyperliquidValue>(
            HYPERLIQUID,
            &HyperliquidFeed::Book {
                coin: config::PERP.into(),
            },
        )?
        .map(|value| top_of(value).map_or(Woke::Nothing, Woke::PerpBook));
        let funding = streams::subscribe::<_, HyperliquidValue>(
            HYPERLIQUID,
            &HyperliquidFeed::Funding {
                coin: config::PERP.into(),
            },
        )?
        .map(|value| match value.map(|stamped| stamped.value) {
            Ok(HyperliquidValue::Funding(funding)) => {
                Woke::Funding(funding.hourly_rate * Decimal::from(24))
            }
            _ => Woke::Nothing,
        });
        let account = drivers::account_events(DRIVER)
            .into_stream()
            .map(Woke::Venue);
        let vault_events = vault::events().into_stream().map(Woke::Vault);

        let mut waking = futures::stream::select_all([
            spot_book.boxed_local(),
            perp_book.boxed_local(),
            funding.boxed_local(),
            account.boxed_local(),
            vault_events.boxed_local(),
        ]);

        while let Some(woke) = waking.next().await {
            match woke {
                // Prices only update what the agent knows; it acts when
                // funding or its account moves, not on every quote.
                Woke::SpotBook(top) => mind.quotes.spot = top,
                Woke::PerpBook(top) => mind.quotes.perp = top,
                // Funding arrives every few seconds. It is looked at when it
                // crosses a threshold, or while there is still something to
                // do; otherwise the account's own events (fills, the hourly
                // funding payment) are what wake the strategy.
                Woke::Funding(daily) => {
                    let before = mind.quotes.funding.replace(daily);
                    if decide::steps_on_funding(before, daily, mind.busy) {
                        step(&mut mind, false).await?;
                    }
                }
                Woke::Venue(event) => {
                    if decide::wakes_for(&event) {
                        step(&mut mind, false).await?
                    }
                }
                Woke::Vault(vault::VaultEvent::ClaimPending(_)) => step(&mut mind, false).await?,
                Woke::Vault(vault::VaultEvent::BufferLow(short)) => {
                    // As much as the venue will let go of; a claim's close
                    // covers whatever this doesn't.
                    let _ = transfers::move_(venue(), Account::Vault, short).await;
                    step(&mut mind, true).await?
                }
                Woke::Vault(vault::VaultEvent::Halting(_)) => {
                    flatten(&mut mind).await?;
                    return Ok(());
                }
                Woke::Nothing => {}
            }
        }
        Ok(())
    }
}

fn venue() -> Account {
    Account::Venue(VenueAccount {
        chain: transfers::home_chain(),
        driver: DRIVER.to_string(),
    })
}

/// Look at what is there, work out what should be there, and act on it if
/// that is worth doing. `brought_home` says cash has just come home for
/// leavers.
async fn step(mind: &mut Mind, brought_home: bool) -> Result<(), String> {
    let state = read_state().await?;
    if state.vault_value > mind.peak {
        mind.peak = state.vault_value;
    }
    if brought_home {
        mind.leavers.brought_home(&mind.limits, &state);
    } else {
        mind.leavers.seen(state.idle);
    }
    let plan = decide::decide(
        &mind.limits,
        mind.peak,
        mind.leavers.held(),
        &state,
        &mind.quotes,
    );
    mind.busy = plan != Plan::Nothing;
    if !mind.busy {
        return Ok(());
    }
    let at = Snapshot::of(&state);
    if mind.patience.holds_back(&at) {
        return Ok(());
    }
    if let Plan::Build { fund, .. } = &plan {
        mind.leavers.taken(fund.from_vault);
    }
    let limits = mind.limits;
    if carry_out(mind, &limits, &state, &plan).await? {
        mind.patience.went_through();
    } else {
        mind.patience.refused(at);
    }
    Ok(())
}

async fn read_state() -> Result<AccountState, String> {
    from_payload(&drivers::account_state(DRIVER.to_string(), Vec::new()).await?)
}

/// Do what `plan` says, and say whether any of it went through.
///
/// The spot goes first and the short is sized to what it actually bought,
/// so an unfilled spot never leaves a short on its own, and the short is
/// levelled with the whole of the spot, an order's worth at a time, before
/// the step ends; on the way out the short goes first and the spot follows
/// what was bought back.
async fn carry_out(
    mind: &mut Mind,
    limits: &Limits,
    state: &AccountState,
    plan: &Plan,
) -> Result<bool, String> {
    let mut landed = false;
    match plan {
        Plan::Nothing => {}
        Plan::Build { fund, spot } => {
            // The money has to be at the venue before it can trade: the
            // station's idle dollars first, then the vault's cash; the
            // buffer stays in the vault, where a withdrawal reaches it
            // without a close. A move that stopped in the station, or whose
            // fate is unknown, is counted as outside the vault from then on,
            // so it is never sent twice.
            let home = transfers::home_chain();
            for (from, amount) in [
                (Account::Station(home), fund.from_station),
                (Account::Vault, fund.from_vault),
            ] {
                if amount > decide::zero() {
                    match transfers::move_(from, venue(), millionths(amount)).await {
                        Moved::Done => landed = true,
                        Moved::Partial(_) => return Ok(true),
                        Moved::Refused(_) | Moved::Unknown(_) => return Ok(landed),
                    }
                }
            }
            let (mut spot_held, mut perp_held) = held(state);
            if let Some(order) = spot {
                // The spot leg is paid for from the account's spot dollars;
                // the perp leg's margin stays on the perp side.
                let cost = order.size * order.limit_price;
                let spot_cash = spot_dollars(state);
                if spot_cash < cost {
                    let verdicts = submit(&[Action::MoveDollars {
                        from: Balance::Perp,
                        amount: decide::round_up_cents(cost - spot_cash),
                    }])
                    .await?;
                    if !matches!(verdicts.first(), Some(sdk::Verdict::Accepted(_))) {
                        return Ok(landed);
                    }
                }
                match place(order).await? {
                    Some(size) => {
                        landed = true;
                        spot_held += size;
                    }
                    None => return Ok(landed),
                }
            }
            for _ in 0..HEDGE_ORDERS {
                let Some(order) = hedge(limits, state, &mind.quotes, spot_held, perp_held) else {
                    break;
                };
                if !mind.levered {
                    let verdicts = submit(&[Action::Leverage {
                        market: config::PERP.into(),
                        leverage: config::PERP_LEVERAGE,
                    }])
                    .await?;
                    mind.levered = matches!(verdicts.first(), Some(sdk::Verdict::Accepted(_)));
                }
                match place(&order).await? {
                    Some(size) if size != decide::zero() => {
                        landed = true;
                        perp_held += size;
                    }
                    _ => break,
                }
            }
        }
        Plan::Reduce { perp } => {
            let (spot_held, mut perp_held) = held(state);
            if let Some(order) = perp
                && let Some(size) = place(order).await?
            {
                landed = true;
                perp_held += size;
            }
            if let Some(order) = trim(limits, state, &mind.quotes, spot_held, perp_held) {
                landed |= place(&order).await?.is_some();
            }
        }
    }
    Ok(landed)
}

/// Close everything, perp first, because a halt is an unwind with less time.
/// The per-order cap is lifted: leaving a leg on would cost the depositors
/// more than a wider fill.
async fn flatten(mind: &mut Mind) -> Result<(), String> {
    let limits = Limits {
        max_order_fraction: Decimal::from(1),
        ..mind.limits
    };
    for _ in 0..FLATTEN_STEPS {
        let state = read_state().await?;
        let plan = Plan::Reduce {
            perp: unwind(&limits, &state, &mind.quotes),
        };
        let (spot, perp) = held(&state);
        if perp == decide::zero() && trim(&limits, &state, &mind.quotes, spot, perp).is_none() {
            return Ok(());
        }
        carry_out(mind, &limits, &state, &plan).await?;
    }
    Ok(())
}

/// Send one order, and say how much of it filled, signed as the position
/// moved: nothing if it was refused, missed the book, or went unanswered.
async fn place(order: &Order) -> Result<Option<Decimal>, String> {
    let verdicts = submit(&[Action::Place(order.clone())]).await?;
    let Some(sdk::Verdict::Accepted(receipt)) = verdicts.first() else {
        return Ok(None);
    };
    let Ok(Receipt::Filled { size, .. }) = from_payload::<Receipt>(receipt) else {
        return Ok(None);
    };
    Ok(Some(match order.side {
        Side::Buy => size,
        Side::Sell => -size,
    }))
}

/// Send actions. A refusal is not a reason to stop: the next event is
/// another chance.
async fn submit(actions: &[Action]) -> Result<Vec<sdk::Verdict>, String> {
    let encoded: Vec<Vec<u8>> = actions.iter().map(to_payload).collect();
    Ok(drivers::submit(DRIVER.to_string(), encoded).await)
}

sdk::export_agent!(FundingBasis);

#[cfg(test)]
mod tests {
    use super::*;
    use sdk::decimal;

    #[test]
    fn the_shipped_limits_can_open_a_position() {
        let minimum = decimal(config::MINIMUM_NOTIONAL);
        let smallest_vault = decimal("2000");
        let wanted = smallest_vault * decimal(config::TARGET_DEPLOYMENT);
        let step =
            decide::pair_notional(wanted, smallest_vault, decide::zero(), &limits(), minimum);
        assert!(
            step > decide::zero(),
            "a {smallest_vault} vault could not open a position"
        );
    }

    #[test]
    fn the_manifest_claims_the_limits_the_code_keeps() {
        let manifest = include_str!("../shonin.toml");
        assert!(
            manifest.contains("at most twice the vault's value")
                && config::MAX_GROSS_LEVERAGE == "2"
        );
        assert!(manifest.contains("above 5% of the vault") && config::MAX_ORDER_FRACTION == "0.05");
        assert!(manifest.contains("6% of the vault kept liquid") && config::IDLE_BUFFER == "0.06");
        assert!(manifest.contains("a 10% fall") && config::DRAWDOWN_STOP == "0.10");
        assert!(manifest.contains("[drivers.hyperliquid]"));
    }
}

//! The numbers this agent decides with.
//!
//! They are constants in the code rather than settings anywhere else, so the
//! reviewer reads them with the rest of the source, and the claims in
//! `shonin.toml` say the same thing in words.

/// The market held long, and the perpetual shorted against it.
pub const SPOT: &str = "BTC";
pub const PERP: &str = "BTC-PERP";

/// Funding, as a fraction of notional per day, at which carrying is worth it.
pub const ENTRY_FUNDING: &str = "0.0002";
/// And at which an open carry is unwound.
pub const EXIT_FUNDING: &str = "0.00005";
/// How much of the vault to aim to have working.
pub const TARGET_DEPLOYMENT: &str = "0.80";
/// Below this, an order is not worth the spread it would pay.
pub const MINIMUM_NOTIONAL: &str = "100";
/// How far past the quoted price an order may fill, as a fraction. The
/// market moves between reading a price and the order landing; an order held
/// to the exact quote misses whenever it does, and a miss costs as much gas
/// as a fill.
pub const SLIPPAGE: &str = "0.002";
/// How far short of its target the carry, or the money behind it at the
/// venue, may fall before anything is done about it, as a fraction of the
/// target. Drift inside it is not worth the transactions it would take.
pub const REBALANCE_BAND: &str = "0.10";

/// Gross exposure at most twice the vault's value.
pub const MAX_GROSS_LEVERAGE: &str = "2";
/// No single order above 5% of the vault.
pub const MAX_ORDER_FRACTION: &str = "0.05";
/// 6% of the vault kept liquid, so an ordinary withdrawal closes nothing:
/// a little above the vault's own 5% idle floor, which it never moves past.
pub const IDLE_BUFFER: &str = "0.06";
/// Only reduces after a 10% fall from the vault's peak.
pub const DRAWDOWN_STOP: &str = "0.10";

//! What the strategy wants to do, worked out from what it can see.
//!
//! Everything here is arithmetic on an [`AccountState`]: no host call, no
//! clock, nothing sent. The program around it reads the state, asks what to
//! do, and does it. Keeping the decision apart is what lets the tests below
//! pin down when the strategy spends gas and when it doesn't.
//!
//! Every transaction costs the vault's tank, so the rules are written to send
//! only what moves the carry meaningfully towards its target:
//!
//! - the money the venue already holds is counted before any more is moved,
//!   and the venue is funded for the whole carry in one move rather than an
//!   order's worth at a time;
//! - nothing is moved unless an order can follow it;
//! - a carry that has drifted less than [`config::REBALANCE_BAND`] from its
//!   target is left alone;
//! - the short leg is sized to what the spot actually bought, so an order
//!   that didn't fill leaves nothing to repair and nothing to resend; and
//!   spot left without its short is hedged before any more is bought.

use strategy_sdk::{
    AccountEvent, AccountState, Decimal, Limits, Order, Side, decimal, from_payload, size_for,
};

use crate::config;

/// The settings the strategy decides with, as numbers.
pub struct Settings {
    pub spot: String,
    pub perp: String,
    /// Funding, as a fraction of notional per day, worth carrying.
    pub entry_funding: Decimal,
    /// And below which an open carry is unwound.
    pub exit_funding: Decimal,
    /// How much of the vault to aim to have working.
    pub target_deployment: Decimal,
    /// Below this, an order is not worth the spread it would pay.
    pub minimum_notional: Decimal,
    /// How far past the quoted price an order may fill.
    pub slippage: Decimal,
    /// How far short of its target the carry may be before more is added.
    pub rebalance_band: Decimal,
}

impl Settings {
    /// The numbers in `config.rs`.
    pub fn shipped() -> Self {
        Self {
            spot: config::SPOT.to_string(),
            perp: config::PERP.to_string(),
            entry_funding: decimal(config::ENTRY_FUNDING),
            exit_funding: decimal(config::EXIT_FUNDING),
            target_deployment: decimal(config::TARGET_DEPLOYMENT),
            minimum_notional: decimal(config::MINIMUM_NOTIONAL),
            slippage: decimal(config::SLIPPAGE),
            rebalance_band: decimal(config::REBALANCE_BAND),
        }
    }
}

/// The limits in `config.rs`, as numbers.
pub fn limits() -> Limits {
    Limits {
        max_gross_leverage: decimal(config::MAX_GROSS_LEVERAGE),
        max_order_fraction: decimal(config::MAX_ORDER_FRACTION),
        idle_buffer: decimal(config::IDLE_BUFFER),
        drawdown_stop: decimal(config::DRAWDOWN_STOP),
    }
}

fn zero() -> Decimal {
    Decimal::from(0)
}

fn positive(value: Decimal) -> Decimal {
    if value > zero() { value } else { zero() }
}

/// Dollars to put on the venue before trading. Each part is one move: the
/// station's idle dollars go in one deposit, the vault's cash in a pull and
/// a deposit.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Funding {
    pub from_station: Decimal,
    pub from_vault: Decimal,
}

/// What to do now.
#[derive(Clone, Debug, PartialEq)]
pub enum Plan {
    /// Nothing would move the carry far enough to be worth a transaction.
    Nothing,
    /// Fund the venue as `fund` says, buy `spot` if there is one, then short
    /// the perpetual to match what the spot holds (see [`hedge`]).
    Build { fund: Funding, spot: Option<Order> },
    /// Buy back `perp` if there is one, then sell the spot down to what is
    /// still short (see [`trim`]).
    Reduce { perp: Option<Order> },
}

/// Whether an event from the venue is worth looking at the account for.
///
/// The venue's market operator posts funding for every market it lists, and
/// a post for a market this strategy doesn't trade can't change what it
/// wants to hold. Its own fills, and anything it can't read, are looked at.
pub fn wakes_for(settings: &Settings, event: &[u8]) -> bool {
    match from_payload::<AccountEvent>(event) {
        Ok(AccountEvent::Funding { market, .. }) => market == settings.perp,
        Ok(AccountEvent::Prices(market)) => {
            market.market == settings.spot || market.market == settings.perp
        }
        Ok(AccountEvent::Filled { .. }) | Err(_) => true,
    }
}

/// Whether the vault has fallen far enough from its peak that this strategy
/// should stop opening anything and only get smaller.
pub fn only_reducing(peak: Decimal, value: Decimal, limits: &Limits) -> bool {
    peak > zero() && (peak - value) / peak >= limits.drawdown_stop
}

/// Work out what to do, given what the account holds, the most the vault has
/// been worth, and the vault's cash that leavers are waiting on (see
/// [`Leavers`]).
pub fn decide(
    settings: &Settings,
    limits: &Limits,
    peak: Decimal,
    for_leavers: Decimal,
    state: &AccountState,
) -> Plan {
    let Some(perp) = state.market(&settings.perp) else {
        return Plan::Nothing;
    };
    if state.market(&settings.spot).is_none() {
        return Plan::Nothing;
    }
    let spot_held = state.position(&settings.spot);
    let perp_held = state.position(&settings.perp);
    let holding = spot_held > zero() || perp_held < zero();
    let funding = perp.funding_fraction();
    let reducing = only_reducing(peak, state.vault_value, limits);

    if holding && (reducing || funding < settings.exit_funding) {
        let perp = unwind(settings, limits, state);
        if perp.is_none() && trim(settings, limits, state, spot_held, perp_held).is_none() {
            return Plan::Nothing;
        }
        return Plan::Reduce { perp };
    }
    if reducing {
        return Plan::Nothing;
    }
    // A leg that didn't fill last time may have left the two sides apart.
    // They are levelled before anything is added: buying more spot while
    // some is still unhedged would only grow a position with a view on the
    // price.
    if hedge(settings, limits, state, spot_held, perp_held).is_some() {
        return Plan::Build {
            fund: Funding::default(),
            spot: None,
        };
    }
    if funding >= settings.entry_funding
        && let Some((fund, spot)) = build_step(settings, limits, for_leavers, state)
    {
        return Plan::Build {
            fund,
            spot: Some(spot),
        };
    }
    Plan::Nothing
}

/// The most of `price` an order may be for: its share of the vault, priced at
/// the furthest the order may fill, so even a fill at the slippage limit stays
/// inside the cap.
pub fn order_size_cap(
    settings: &Settings,
    limits: &Limits,
    state: &AccountState,
    price: Decimal,
) -> Decimal {
    state.vault_value * limits.max_order_fraction / (price * (Decimal::from(1) + settings.slippage))
}

/// What the two legs are worth at mark, held as `spot_held` and `perp_held`,
/// without regard to sign.
fn legs_gross(
    settings: &Settings,
    state: &AccountState,
    spot_held: Decimal,
    perp_held: Decimal,
) -> Decimal {
    let mark = |market: &str| state.market(market).map_or_else(zero, |held| held.mark);
    spot_held.abs() * mark(&settings.spot) + perp_held.abs() * mark(&settings.perp)
}

/// What every open position is worth at mark, added up without regard to
/// sign.
pub fn gross_notional(state: &AccountState) -> Decimal {
    state
        .positions
        .iter()
        .map(|held| {
            let price = state
                .market(&held.market)
                .map(|market| market.mark)
                .unwrap_or_else(zero);
            let size = if held.size < zero() {
                -held.size
            } else {
                held.size
            };
            size * price
        })
        .fold(zero(), |total, one| total + one)
}

/// The notional of each leg of the next pair: half what is still wanted,
/// since a pair adds both legs to the gross, inside the order cap and the
/// leverage ceiling.
pub fn pair_notional(
    wanted: Decimal,
    vault_value: Decimal,
    gross: Decimal,
    limits: &Limits,
    minimum: Decimal,
) -> Decimal {
    let two = Decimal::from(2);
    let per_leg = size_for(wanted / two, vault_value, gross, limits, minimum);
    let headroom = positive(vault_value * limits.max_gross_leverage - gross) / two;
    let per_leg = if per_leg > headroom {
        headroom
    } else {
        per_leg
    };
    if per_leg < minimum { zero() } else { per_leg }
}

/// The next pair's spot leg, and what has to reach the venue first to pay
/// for it; nothing if the carry is close enough to its target, or if the
/// order couldn't be paid for even after moving what may be moved.
fn build_step(
    settings: &Settings,
    limits: &Limits,
    for_leavers: Decimal,
    state: &AccountState,
) -> Option<(Funding, Order)> {
    let spot = state.market(&settings.spot)?;
    let perp = state.market(&settings.perp)?;
    if spot.ask <= zero() || perp.bid <= zero() || state.vault_value <= zero() {
        return None;
    }

    let working = state.vault_value * settings.target_deployment;
    let gross = gross_notional(state);
    let wanted = positive(working - gross);
    // Drift inside the band is not worth the cost of trading it away.
    if wanted < working * settings.rebalance_band {
        return None;
    }
    let per_leg = pair_notional(
        wanted,
        state.vault_value,
        gross,
        limits,
        settings.minimum_notional,
    );
    if per_leg <= zero() {
        return None;
    }

    let fund = funding_for(settings, limits, for_leavers, state, per_leg);
    // The spot is bought with the venue's cash; the short's sale gives it
    // back, so the same dollars pay for every pair in turn. The order is
    // sized so that what it pays at its limit fits both the cash and the
    // order cap.
    let payable = positive(state.cash) + fund.from_station + fund.from_vault;
    let reach = Decimal::from(1) + settings.slippage;
    let most = state.vault_value * limits.max_order_fraction;
    let notional = cap(cap(per_leg * reach, payable), most) / reach;
    if notional < settings.minimum_notional {
        // No order can follow, so nothing is moved either.
        return None;
    }
    Some((
        fund,
        Order {
            market: settings.spot.clone(),
            side: Side::Buy,
            size: notional / spot.ask,
            limit_price: spot.ask * reach,
            reduce_only: false,
        },
    ))
}

/// What to move to the venue before buying `per_leg` of spot.
///
/// The venue is meant to hold the short's whole notional at target, once
/// over: the spot leg's purchase price, which the short's sale hands back,
/// and then the collateral the short rests on. Everything already there
/// counts, at the venue or waiting in the station beside it. Money is moved
/// only when the next order couldn't be paid without it, or when the venue
/// is short of that by more than the band, and then the whole shortfall goes
/// in one move rather than an order's worth at a time. The vault's cash that
/// leavers are waiting on, `for_leavers`, is never part of it.
pub fn funding_for(
    settings: &Settings,
    limits: &Limits,
    for_leavers: Decimal,
    state: &AccountState,
    per_leg: Decimal,
) -> Funding {
    let goal = state.vault_value * settings.target_deployment / Decimal::from(2);
    let there = positive(state.value) + positive(state.station_idle);
    let short_of_goal = positive(goal - there);
    let reach = Decimal::from(1) + settings.slippage;
    let needed_now = positive(per_leg * reach - positive(state.cash));
    if needed_now <= zero() && short_of_goal < goal * settings.rebalance_band {
        return Funding::default();
    }

    // A move too small to place an order with is not worth its gas.
    let worth = |amount: Decimal| {
        if amount < settings.minimum_notional {
            zero()
        } else {
            amount
        }
    };
    // What waits in the station earns nothing there, and it takes one
    // deposit however much of it goes, so all of it goes.
    let from_station = worth(positive(state.station_idle));
    // The buffer stays in the vault, where a withdrawal reaches it without
    // closing anything, and so does what leavers are waiting on.
    let spare =
        positive(state.idle - state.vault_value * limits.idle_buffer - positive(for_leavers));
    // The shortfall from the goal already counts the station's dollars; the
    // next order's needs don't.
    let still = if short_of_goal > needed_now - from_station {
        short_of_goal
    } else {
        positive(needed_now - from_station)
    };
    let from_vault = worth(if spare < still { spare } else { still });
    Funding {
        from_station,
        from_vault,
    }
}

/// The perpetual order that brings the short level with `spot_held`, as long
/// as the gap is worth an order: a sale when the spot is ahead, a reduce-only
/// purchase when the short is. A gap wider than one order is closed in equal
/// orders, so the last of it is never a sliver too small to send.
pub fn hedge(
    settings: &Settings,
    limits: &Limits,
    state: &AccountState,
    spot_held: Decimal,
    perp_held: Decimal,
) -> Option<Order> {
    let perp = state.market(&settings.perp)?;
    let gap = spot_held + perp_held;
    let one = Decimal::from(1);
    if gap > zero() {
        if perp.bid <= zero() {
            return None;
        }
        let gross = legs_gross(settings, state, spot_held, perp_held);
        let headroom = positive(state.vault_value * limits.max_gross_leverage - gross);
        let size = cap(
            in_equal_orders(gap, order_size_cap(settings, limits, state, perp.bid)),
            headroom / perp.bid,
        );
        (size * perp.bid >= settings.minimum_notional).then(|| Order {
            market: settings.perp.clone(),
            side: Side::Sell,
            size,
            limit_price: perp.bid * (one - settings.slippage),
            reduce_only: false,
        })
    } else if gap < zero() && perp_held < zero() {
        if perp.ask <= zero() {
            return None;
        }
        let size = in_equal_orders(
            cap(-gap, -perp_held),
            order_size_cap(settings, limits, state, perp.ask),
        );
        (size * perp.ask >= settings.minimum_notional).then(|| Order {
            market: settings.perp.clone(),
            side: Side::Buy,
            size,
            limit_price: perp.ask * (one + settings.slippage),
            reduce_only: true,
        })
    } else {
        None
    }
}

/// One order's worth of the short bought back, if there is a short.
pub fn unwind(settings: &Settings, limits: &Limits, state: &AccountState) -> Option<Order> {
    let perp = state.market(&settings.perp)?;
    let short = -state.position(&settings.perp);
    if short <= zero() || perp.ask <= zero() {
        return None;
    }
    Some(Order {
        market: settings.perp.clone(),
        side: Side::Buy,
        size: cap(short, order_size_cap(settings, limits, state, perp.ask)),
        limit_price: perp.ask * (Decimal::from(1) + settings.slippage),
        reduce_only: true,
    })
}

/// The spot sale that brings the spot down to what is still short. Closing
/// the spot ahead of the short would leave a naked short, which is exactly
/// the exposure this strategy exists to avoid. While a short is still open a
/// sliver too small to be worth an order waits; once the short is gone,
/// whatever spot is left goes.
pub fn trim(
    settings: &Settings,
    limits: &Limits,
    state: &AccountState,
    spot_held: Decimal,
    perp_held: Decimal,
) -> Option<Order> {
    let spot = state.market(&settings.spot)?;
    let excess = spot_held + perp_held;
    if excess <= zero() || spot.bid <= zero() {
        return None;
    }
    let size = cap(excess, order_size_cap(settings, limits, state, spot.bid));
    if perp_held < zero() && size * spot.bid < settings.minimum_notional {
        return None;
    }
    Some(Order {
        market: settings.spot.clone(),
        side: Side::Sell,
        size,
        limit_price: spot.bid * (Decimal::from(1) - settings.slippage),
        reduce_only: true,
    })
}

fn cap(size: Decimal, most: Decimal) -> Decimal {
    if size > most { most } else { size }
}

/// The first of the fewest equal orders, none above `most`, that add up to
/// `size`.
fn in_equal_orders(size: Decimal, most: Decimal) -> Decimal {
    if size <= most || most <= zero() {
        return cap(size, most);
    }
    size / (size / most).ceil()
}

/// The vault's cash that leavers are waiting on, as far as the strategy can
/// tell.
///
/// A withdrawal the vault's cash can't cover waits for the next valuation,
/// and `buffer-low` says so: the agent brings the shortfall home from the
/// venue. Until a valuation pays the leavers, everything the vault then
/// holds above its buffer is theirs, and moving it back out would only send
/// it on a round trip at the tank's expense. The vault's cash falling by
/// more than the agent itself took out is the leavers being paid, and it
/// frees what was held for them by as much.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Leavers {
    held: Decimal,
    last_idle: Option<Decimal>,
}

impl Leavers {
    /// Cash has been brought home for leavers, and the vault now looks like
    /// `state`.
    pub fn brought_home(&mut self, limits: &Limits, state: &AccountState) {
        self.held = positive(state.idle - state.vault_value * limits.idle_buffer);
        self.last_idle = Some(state.idle);
    }

    /// The vault's cash as read now.
    pub fn seen(&mut self, idle: Decimal) {
        if let Some(last) = self.last_idle
            && idle < last
        {
            self.held = positive(self.held - (last - idle));
        }
        self.last_idle = Some(idle);
    }

    /// The agent asked to take `amount` out of the vault's cash, which is not
    /// a leaver being paid. Counted whether or not it went, which at worst
    /// holds the leavers' cash a little longer.
    pub fn taken(&mut self, amount: Decimal) {
        if let Some(last) = &mut self.last_idle {
            *last -= amount;
        }
    }

    /// What is held for them now.
    pub fn held(&self) -> Decimal {
        self.held
    }
}

/// What the account looked like when the venue or the station last said no:
/// what only the strategy's own actions, a deposit or a withdrawal change,
/// and never a price.
#[derive(Clone, Debug, PartialEq)]
pub struct Snapshot {
    spot: Decimal,
    perp: Decimal,
    cash: Decimal,
    idle: Decimal,
    station_idle: Decimal,
}

impl Snapshot {
    pub fn of(settings: &Settings, state: &AccountState) -> Self {
        Self {
            spot: state.position(&settings.spot),
            perp: state.position(&settings.perp),
            cash: state.cash,
            idle: state.idle,
            station_idle: state.station_idle,
        }
    }
}

/// The most wake-ups a refusal is waited out for.
const PATIENCE_MOST: u32 = 64;

/// How long to leave a plan the venue or the station refused.
///
/// Sending the same thing into the same refusal on every event is how an
/// agent burns gas doing nothing. After a refusal the agent waits out a
/// number of wake-ups before trying again, doubling with each refusal in a
/// row, up to [`PATIENCE_MOST`]; anything that changes the account (a fill,
/// a deposit, a withdrawal, a move landing) ends the wait at once. It counts
/// events rather than time, so the agent still never sleeps on a timer.
#[derive(Debug, Default)]
pub struct Patience {
    refused_at: Option<Snapshot>,
    strikes: u32,
    waiting: u32,
}

impl Patience {
    /// Whether to hold back now, with the account as it is.
    pub fn holds_back(&mut self, now: &Snapshot) -> bool {
        match &self.refused_at {
            Some(then) if then == now => {
                if self.waiting > 0 {
                    self.waiting -= 1;
                    true
                } else {
                    false
                }
            }
            Some(_) => {
                *self = Self::default();
                false
            }
            None => false,
        }
    }

    /// The plan made with the account at `at` was refused.
    pub fn refused(&mut self, at: Snapshot) {
        self.strikes = if self.refused_at.as_ref() == Some(&at) {
            self.strikes + 1
        } else {
            1
        };
        self.waiting = (1u32 << self.strikes.min(6)).min(PATIENCE_MOST) - 1;
        self.refused_at = Some(at);
    }

    /// Something went through: the next plan is tried at once.
    pub fn went_through(&mut self) {
        *self = Self::default();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use strategy_sdk::{MarketState, PositionState};

    fn d(text: &str) -> Decimal {
        decimal(text)
    }

    /// A vault with `idle` in its own cash and the venue holding `cash`, the
    /// spot and the perpetual both at 50,000 with a dollar either side, and
    /// funding at `funding` of the mark a day.
    fn state(idle: &str, cash: &str, funding: &str) -> AccountState {
        let price = d("50000");
        let market = |name: &str, is_perp: bool| MarketState {
            market: name.to_string(),
            is_perp,
            mark: price,
            oracle: price,
            bid: price - d("1"),
            ask: price + d("1"),
            funding_index: zero(),
            funding_rate: if is_perp { price * d(funding) } else { zero() },
        };
        let mut state = AccountState {
            cash: d(cash),
            value: d(cash),
            exit_value: d(cash),
            vault_value: zero(),
            idle: d(idle),
            station_idle: zero(),
            margin_bps: 1000,
            positions: Vec::new(),
            markets: vec![market(config::SPOT, false), market(config::PERP, true)],
        };
        state.vault_value = state.idle + state.value;
        state
    }

    /// Hold `spot` and short `perp` (both in units), the venue's value
    /// following them at mark.
    fn holding(mut state: AccountState, spot: &str, perp: &str) -> AccountState {
        let price = d("50000");
        state.positions = vec![
            PositionState {
                market: config::SPOT.to_string(),
                size: d(spot),
            },
            PositionState {
                market: config::PERP.to_string(),
                size: -d(perp),
            },
        ];
        state.value = state.cash + d(spot) * price - d(perp) * price;
        state.vault_value = state.idle + state.station_idle + state.value;
        state
    }

    const ABOVE_ENTRY: &str = "0.001";
    const BELOW_EXIT: &str = "0.00001";

    fn plan(state: &AccountState) -> Plan {
        decide(
            &Settings::shipped(),
            &limits(),
            state.vault_value,
            zero(),
            state,
        )
    }

    /// Fill `order` at its quoted price (one dollar either side of the
    /// mark), and keep the venue's books the way the stand-in venue does:
    /// cash pays for a purchase and is credited for a sale.
    fn fill(state: &mut AccountState, order: &Order) {
        let quoted = match order.side {
            Side::Buy => d("50001"),
            Side::Sell => d("49999"),
        };
        let signed = match order.side {
            Side::Buy => order.size,
            Side::Sell => -order.size,
        };
        state.cash -= signed * quoted;
        match state
            .positions
            .iter_mut()
            .find(|held| held.market == order.market)
        {
            Some(held) => held.size += signed,
            None => state.positions.push(PositionState {
                market: order.market.clone(),
                size: signed,
            }),
        }
        state.positions.retain(|held| held.size != zero());
        let price = d("50000");
        state.value = state.cash
            + state
                .positions
                .iter()
                .fold(zero(), |sum, held| sum + held.size * price);
        state.vault_value = state.idle + state.station_idle + state.value;
    }

    /// The transactions the agent would send to carry out `plan`, carried
    /// out against `state` as the stand-in venue would: a pull and a deposit
    /// for a move from the vault, a deposit for one from the station, and
    /// one transaction per order, the short levelled an order at a time.
    fn carry_out(state: &mut AccountState, plan: &Plan) -> usize {
        let settings = Settings::shipped();
        let limits = limits();
        let mut sent = 0;
        match plan {
            Plan::Nothing => {}
            Plan::Build { fund, spot } => {
                if fund.from_station > zero() {
                    state.station_idle -= fund.from_station;
                    state.cash += fund.from_station;
                    sent += 1;
                }
                if fund.from_vault > zero() {
                    state.idle -= fund.from_vault;
                    state.cash += fund.from_vault;
                    sent += 2;
                }
                if let Some(order) = spot {
                    fill(state, order);
                    sent += 1;
                }
                for _ in 0..8 {
                    let spot_held = state.position(config::SPOT);
                    let perp_held = state.position(config::PERP);
                    let Some(order) = hedge(&settings, &limits, state, spot_held, perp_held) else {
                        break;
                    };
                    fill(state, &order);
                    sent += 1;
                }
            }
            Plan::Reduce { perp } => {
                if let Some(order) = perp {
                    fill(state, order);
                    sent += 1;
                }
                let spot_held = state.position(config::SPOT);
                let perp_held = state.position(config::PERP);
                if let Some(order) = trim(&settings, &limits, state, spot_held, perp_held) {
                    fill(state, &order);
                    sent += 1;
                }
            }
        }
        sent
    }

    /// Wake the agent until it has nothing more to do, and count what it
    /// sent.
    fn settle(state: &mut AccountState) -> usize {
        let mut sent = 0;
        for _ in 0..100 {
            let next = plan(state);
            if next == Plan::Nothing {
                return sent;
            }
            sent += carry_out(state, &next);
        }
        panic!("the agent never settled");
    }

    #[test]
    fn a_deposit_is_deployed_with_one_move_and_one_order_per_leg_per_step() {
        let mut state = state("25000", "0", ABOVE_ENTRY);
        let first = plan(&state);
        let Plan::Build { fund, spot } = &first else {
            panic!("a fresh deposit with funding above entry opens: {first:?}");
        };
        // The whole carry's worth, once: the short's notional at target.
        assert_eq!(fund.from_vault, d("10000"));
        assert_eq!(fund.from_station, zero());
        assert!(spot.is_some());

        let sent = settle(&mut state);
        // One pull and one deposit, then eight pairs of 5% of the vault.
        assert_eq!(sent, 2 + 8 * 2);
        let gross = gross_notional(&state);
        let target = state.vault_value * d(config::TARGET_DEPLOYMENT);
        assert!(gross <= target && gross >= target * d("0.9"), "{gross}");
        assert_eq!(
            state.position(config::SPOT),
            -state.position(config::PERP),
            "the legs are level"
        );
    }

    #[test]
    fn a_quiet_market_sends_nothing() {
        let mut state = state("25000", "0", ABOVE_ENTRY);
        settle(&mut state);
        // A day of funding posts every few minutes: the price still, the
        // funding paid into the account a few cents at a time.
        for _ in 0..(24 * 60 / 3) {
            state.cash += d("0.01");
            state.value += d("0.01");
            state.vault_value += d("0.01");
            assert_eq!(plan(&state), Plan::Nothing);
        }
    }

    #[test]
    fn small_price_drift_inside_the_band_sends_nothing() {
        let mut state = state("25000", "0", ABOVE_ENTRY);
        settle(&mut state);
        for market in &mut state.markets {
            market.mark *= d("0.95");
            market.bid = market.mark - d("1");
            market.ask = market.mark + d("1");
            market.funding_rate = if market.is_perp {
                market.mark * d(ABOVE_ENTRY)
            } else {
                zero()
            };
        }
        // Hedged, so the value hardly moves; the gross falls 5%.
        assert_eq!(plan(&state), Plan::Nothing);
    }

    #[test]
    fn cash_already_at_the_venue_is_used_before_more_is_moved() {
        // Most of the vault is already at the venue and nothing is open.
        let state = state("2000", "23000", ABOVE_ENTRY);
        let Plan::Build { fund, spot } = plan(&state) else {
            panic!("it opens");
        };
        assert_eq!(fund, Funding::default(), "nothing more is moved");
        assert!(spot.is_some());
    }

    #[test]
    fn money_waiting_in_the_station_goes_on_before_any_more_is_pulled() {
        let mut state = state("15000", "0", ABOVE_ENTRY);
        state.station_idle = d("10000");
        state.vault_value = d("25000");
        let Plan::Build { fund, .. } = plan(&state) else {
            panic!("it opens");
        };
        assert_eq!(fund.from_station, d("10000"));
        assert_eq!(fund.from_vault, zero());
    }

    #[test]
    fn nothing_is_moved_when_no_order_could_follow() {
        // The vault is down to its buffer and the venue holds too little for
        // the smallest order: moving what little there is would be gas for
        // nothing.
        let mut state = state("1500", "50", ABOVE_ENTRY);
        state.vault_value = d("25000");
        assert_eq!(plan(&state), Plan::Nothing);
    }

    #[test]
    fn funding_below_entry_opens_nothing() {
        let state = state("25000", "0", "0.0001");
        assert_eq!(plan(&state), Plan::Nothing);
    }

    #[test]
    fn a_spot_leg_that_did_not_fill_is_not_shorted() {
        let state = state("25000", "0", ABOVE_ENTRY);
        let settings = Settings::shipped();
        // The spot leg missed: nothing to short against.
        assert_eq!(hedge(&settings, &limits(), &state, zero(), zero()), None);
    }

    #[test]
    fn a_short_left_without_its_spot_is_bought_back_before_more_is_added() {
        // The spot leg missed on an earlier step and the short went through.
        let state = holding(state("15000", "11000", "0.0001"), "0", "0.02");
        let Plan::Build { fund, spot: None } = plan(&state) else {
            panic!("the legs are levelled");
        };
        assert_eq!(fund, Funding::default());
        let order = hedge(&Settings::shipped(), &limits(), &state, zero(), -d("0.02")).unwrap();
        assert_eq!(order.side, Side::Buy);
        assert!(order.reduce_only);
    }

    #[test]
    fn an_unwind_never_sells_spot_ahead_of_the_short() {
        let state = holding(state("15000", "10000", BELOW_EXIT), "0.2", "0.2");
        let Plan::Reduce { perp: Some(perp) } = plan(&state) else {
            panic!("funding below exit unwinds");
        };
        assert_eq!(perp.side, Side::Buy);
        let settings = Settings::shipped();
        // The short's purchase missed: the spot stays.
        assert_eq!(
            trim(&settings, &limits(), &state, d("0.2"), -d("0.2")),
            None
        );
        // It went through: the spot follows it down.
        let after = -d("0.2") + perp.size;
        let spot = trim(&settings, &limits(), &state, d("0.2"), after).unwrap();
        // Level, to the last of the decimal's 34 digits.
        let apart = spot.size - perp.size;
        assert!(apart < d("1e-30") && apart > -d("1e-30"), "{apart}");
    }

    #[test]
    fn spot_left_over_from_an_unwind_is_still_sold() {
        // The short is gone and spot is left: a carry this strategy no longer
        // has, and a view on the price it never means to hold.
        let state = holding(state("15000", "0", BELOW_EXIT), "0.1", "0");
        let Plan::Reduce { perp: None } = plan(&state) else {
            panic!("the spot is sold");
        };
    }

    /// Every order the strategy sends, filled at the furthest its slippage
    /// lets it, is still no more than 5% of the vault, as the manifest
    /// claims: the spot buys while building, the shorts that hedge them, the
    /// short bought back and the spot sold on the way out.
    #[test]
    fn an_order_filled_at_its_slippage_limit_is_never_above_its_share_of_the_vault() {
        let settings = Settings::shipped();
        let limits = limits();
        let within = |state: &AccountState, order: &Order| {
            let cap = state.vault_value * d(config::MAX_ORDER_FRACTION);
            let price = state.market(&order.market).unwrap();
            let furthest = match order.side {
                Side::Buy => price.ask * (Decimal::from(1) + settings.slippage),
                // A sale fills at the bid or below; the bid itself is the
                // most it is worth.
                Side::Sell => price.bid * (Decimal::from(1) + settings.slippage),
            };
            assert!(
                order.size * furthest <= cap,
                "{order:?} could fill at {} of a {cap} cap",
                order.size * furthest
            );
        };
        let mut state = state("100000", "0", ABOVE_ENTRY);
        let mut orders = 0;
        for _ in 0..40 {
            let next = plan(&state);
            if let Plan::Build {
                spot: Some(order), ..
            } = &next
            {
                within(&state, order);
                let mut after = state.clone();
                fill(&mut after, order);
                let spot = after.position(config::SPOT);
                let perp = after.position(config::PERP);
                within(
                    &state,
                    &hedge(&settings, &limits, &state, spot, perp).unwrap(),
                );
                orders += 2;
            }
            if next == Plan::Nothing {
                break;
            }
            carry_out(&mut state, &next);
        }
        assert!(orders > 0);
        for market in &mut state.markets {
            market.funding_rate = market.mark * d(BELOW_EXIT);
        }
        let Plan::Reduce { perp: Some(perp) } = plan(&state) else {
            panic!("funding below exit unwinds");
        };
        within(&state, &perp);
        let spot = state.position(config::SPOT);
        let short = state.position(config::PERP) + perp.size;
        within(
            &state,
            &trim(&settings, &limits, &state, spot, short).unwrap(),
        );
    }

    /// A spot buy whose short missed leaves the vault with a view on the
    /// price. The next step shorts against it before buying anything more,
    /// and keeps shorting, an order at a time, until the two legs are level.
    #[test]
    fn spot_left_without_its_short_is_hedged_before_more_is_bought() {
        // 0.1 BTC ($5,000) bought on the last step; its short missed.
        let mut state = holding(state("50000", "45000", ABOVE_ENTRY), "0.1", "0");
        let first = plan(&state);
        let Plan::Build { fund, spot: None } = &first else {
            panic!("more spot is bought on top of an unhedged 0.1 BTC: {first:?}");
        };
        assert_eq!(*fund, Funding::default(), "nothing is moved to hedge");
        carry_out(&mut state, &first);
        assert_eq!(state.position(config::SPOT), -state.position(config::PERP));
    }

    /// Once the hedge has missed more than once, the unhedged spot can be
    /// wider than one order. It is still all shorted before more is bought,
    /// within the per-order cap, across as many orders as it takes.
    #[test]
    fn a_gap_wider_than_one_order_is_hedged_in_full_before_more_is_bought() {
        // 0.25 BTC ($12,500) unhedged in a $100,000 vault: two and a half
        // orders' worth.
        let mut state = holding(state("50000", "37500", ABOVE_ENTRY), "0.25", "0");
        let first = plan(&state);
        assert!(matches!(first, Plan::Build { spot: None, .. }), "{first:?}");
        let sent = carry_out(&mut state, &first);
        assert_eq!(sent, 3, "three orders, each inside the cap");
        assert_eq!(state.position(config::SPOT), -state.position(config::PERP));
    }

    /// When a fresh spot buy lands on top of spot whose short missed, the
    /// short that follows covers all of it, not just the new order.
    #[test]
    fn the_short_after_a_spot_buy_covers_everything_unhedged() {
        // A sliver unhedged, under the smallest order, so the step builds.
        let mut state = holding(state("50000", "45000", ABOVE_ENTRY), "0.001", "0");
        let next = plan(&state);
        assert!(
            matches!(next, Plan::Build { spot: Some(_), .. }),
            "{next:?}"
        );
        carry_out(&mut state, &next);
        assert_eq!(state.position(config::SPOT), -state.position(config::PERP));
    }

    /// `buffer-low` brings cash home from the venue for leavers waiting on a
    /// valuation. Until the valuation pays them, that cash stays in the vault
    /// however far the carry is from its target.
    #[test]
    fn cash_brought_home_for_leavers_is_not_sent_back_out() {
        // A $100,000 vault half way to its target carry, funding above
        // entry. A holder of 92% asks to leave and $91,000 comes home: the
        // vault now holds $97,000, the venue $3,000 and the carry.
        let mut home = holding(state("97000", "3000", ABOVE_ENTRY), "0.4", "0.4");
        home.vault_value = d("100000");
        let mut leavers = Leavers::default();
        leavers.brought_home(&limits(), &home);
        let decided = |state: &AccountState, leavers: &Leavers| {
            decide(
                &Settings::shipped(),
                &limits(),
                state.vault_value,
                leavers.held(),
                state,
            )
        };
        let plan = decided(&home, &leavers);
        if let Plan::Build { fund, .. } = &plan {
            assert_eq!(fund.from_vault, zero(), "{plan:?}");
        }

        // A valuation pays them: the vault's cash falls by what they were
        // owed. Nothing is held for them any more, so a deposit after that
        // is put to work as usual.
        leavers.seen(d("6000"));
        assert_eq!(leavers.held(), zero());
        let deposit = state("25000", "0", ABOVE_ENTRY);
        leavers.seen(deposit.idle);
        let Plan::Build { fund, .. } = decided(&deposit, &leavers) else {
            panic!("a deposit after the leavers are paid is put to work");
        };
        assert_eq!(fund.from_vault, d("10000"));
    }

    /// The agent's own pulls from the vault's cash don't count as leavers
    /// being paid.
    #[test]
    fn the_agents_own_pull_does_not_free_the_leavers_cash() {
        let mut state = state("50000", "0", ABOVE_ENTRY);
        let mut leavers = Leavers::default();
        leavers.brought_home(&limits(), &state);
        let held = leavers.held();
        leavers.taken(d("1000"));
        state.idle -= d("1000");
        leavers.seen(state.idle);
        assert_eq!(leavers.held(), held);
    }

    #[test]
    fn funding_posted_for_another_market_does_not_wake_it() {
        let settings = Settings::shipped();
        let funding = |market: &str| {
            strategy_sdk::to_payload(&AccountEvent::Funding {
                market: market.to_string(),
                paid_per_unit: d("0.5"),
            })
        };
        assert!(!wakes_for(&settings, &funding("ETH-PERP")));
        assert!(wakes_for(&settings, &funding(config::PERP)));
        assert!(wakes_for(&settings, b"not an event"));
    }

    #[test]
    fn a_refusal_is_not_resent_on_every_event() {
        let settings = Settings::shipped();
        let state = state("25000", "0", ABOVE_ENTRY);
        let at = Snapshot::of(&settings, &state);
        let mut patience = Patience::default();
        let mut tried = 0;
        for _ in 0..200 {
            if !patience.holds_back(&at) {
                tried += 1;
                patience.refused(at.clone());
            }
        }
        // Waits of 1, 3, 7, 15, 31, 63, then 63 again.
        assert!(tried <= 8, "{tried} tries in 200 wake-ups");
        assert!(tried >= 4, "it never gives up for good");
    }

    #[test]
    fn a_change_to_the_account_ends_the_wait() {
        let settings = Settings::shipped();
        let before = state("25000", "0", ABOVE_ENTRY);
        let mut patience = Patience::default();
        patience.refused(Snapshot::of(&settings, &before));
        patience.refused(Snapshot::of(&settings, &before));
        let after = state("30000", "0", ABOVE_ENTRY);
        assert!(!patience.holds_back(&Snapshot::of(&settings, &after)));
    }
}

//! Holds spot, shorts the perpetual against it, and collects the funding.
//!
//! The position has no view on the price: whatever the asset does, the long
//! and the short move against each other and cancel. What is left is the
//! funding the shorts are paid while the perpetual trades above the spot, less
//! the spread it costs to get into both legs and out of them again.
//!
//! The whole strategy is one long-lived program. It waits on the venue's own
//! account stream and on the vault's, and each time it learns something it
//! works out what it would like to hold and takes one step towards it, if
//! that step is worth the gas it costs (`decide.rs` says when it is). It
//! never polls and it never sleeps on a timer, so a quiet market costs
//! nothing.
//!
//! Its limits are in `config.rs` rather than in a platform policy, because
//! there is no platform policy. The manifest claims them in the same words, so
//! a depositor reading the page and a reviewer reading the source are looking
//! at the same promises.

mod config;
mod decide;

use decide::{Leavers, Patience, Plan, Settings, Snapshot, hedge, limits, trim, unwind};
use futures::StreamExt;
use sdk::transfers::{self, Account, Moved, VenueAccount};
use sdk::{
    AccountState, Action, Decimal, Limits, Order, Query, Receipt, from_payload, millionths,
    to_payload,
};
use sdk::{drivers, vault};
use strategy_sdk as sdk;

/// The driver this agent trades through, as its manifest names it.
const DRIVER: &str = "local";

/// How many steps a halt may take to flatten the book before giving up and
/// letting the contract finish the job.
const FLATTEN_STEPS: usize = 32;

/// How many perpetual orders one step may send to level the short with the
/// spot. One is almost always enough; more are for a gap wider than the
/// order cap, or an order that only partly filled.
const HEDGE_ORDERS: usize = 8;

struct FundingBasis;

/// What the strategy decided last time it looked. It is rebuilt from the venue
/// whenever it runs, so losing it to a restart costs a moment and nothing else.
struct Mind {
    settings: Settings,
    limits: Limits,
    /// The most the vault has been worth while this instance watched it: what
    /// the drawdown stop is measured from.
    peak: Decimal,
    /// How long to leave a plan the venue or the station refused.
    patience: Patience,
    /// The vault's cash that leavers are waiting on. Lost to a restart, which
    /// at worst sends it out once more for the next `buffer-low` to bring
    /// back.
    leavers: Leavers,
}

impl Mind {
    fn new() -> Self {
        Self {
            settings: Settings::shipped(),
            limits: limits(),
            peak: Decimal::from(0),
            patience: Patience::default(),
            leavers: Leavers::default(),
        }
    }
}

/// What woke the strategy up.
enum Woke {
    /// The venue says something happened to the account or its markets.
    Venue(Vec<u8>),
    Vault(vault::VaultEvent),
}

impl sdk::Agent for FundingBasis {
    async fn run() -> Result<(), String> {
        let mut mind = Mind::new();

        // Whatever a previous instance left behind is still on the venue, so
        // look before doing anything.
        step(&mut mind, false).await?;

        let account = drivers::account_events(DRIVER)
            .into_stream()
            .map(Woke::Venue);
        let vault_events = vault::events().into_stream().map(Woke::Vault);
        let mut waking = futures::stream::select(account, vault_events);

        while let Some(woke) = waking.next().await {
            match woke {
                // A fill, a funding payment, a price: look again, if it is
                // about this strategy's markets at all.
                Woke::Venue(event) => {
                    if decide::wakes_for(&mind.settings, &event) {
                        step(&mut mind, false).await?
                    }
                }
                // A depositor is leaving, and the contract is closing their
                // fraction of both legs together. Nothing to do but let it,
                // then rebalance what is left.
                Woke::Vault(vault::VaultEvent::ClaimPending(_)) => step(&mut mind, false).await?,
                // Leavers are waiting on more cash than the vault holds:
                // bring the shortfall home from the venue, so they are paid
                // without waiting for a claim.
                Woke::Vault(vault::VaultEvent::BufferLow(short)) => {
                    // As much as the venue will let go of: a refusal leaves
                    // the claim to the contract, which closes the fraction
                    // itself.
                    let _ = transfers::move_(venue(), Account::Vault, short).await;
                    step(&mut mind, true).await?
                }
                // Unwind rather than be unwound.
                Woke::Vault(vault::VaultEvent::Halting(_)) => {
                    flatten(&mind).await?;
                    return Ok(());
                }
            }
        }
        Ok(())
    }
}

/// The venue account the vault's station owns.
fn venue() -> Account {
    Account::Venue(VenueAccount {
        chain: transfers::home_chain(),
        driver: DRIVER.to_string(),
    })
}

/// Look at what is there, work out what should be there, and act on it if
/// that is worth a transaction. `brought_home` says cash has just come home
/// for leavers.
async fn step(mind: &mut Mind, brought_home: bool) -> Result<(), String> {
    let state = read_state().await?;
    if state.vault_value > mind.peak {
        mind.peak = state.vault_value;
    }
    if brought_home {
        mind.leavers.brought_home(&mind.limits, &state);
    } else {
        mind.leavers.seen(state.idle);
    }
    let plan = decide::decide(
        &mind.settings,
        &mind.limits,
        mind.peak,
        mind.leavers.held(),
        &state,
    );
    if plan == Plan::Nothing {
        return Ok(());
    }
    let at = Snapshot::of(&mind.settings, &state);
    if mind.patience.holds_back(&at) {
        return Ok(());
    }
    if let Plan::Build { fund, .. } = &plan {
        mind.leavers.taken(fund.from_vault);
    }
    if carry_out(&mind.settings, &mind.limits, &state, &plan).await {
        mind.patience.went_through();
    } else {
        mind.patience.refused(at);
    }
    Ok(())
}

/// The account, asked about the two markets this strategy trades. Naming them
/// also tells the executor which markets' news should wake it, so a price or
/// funding posted for any other market costs nothing.
async fn read_state() -> Result<AccountState, String> {
    let query = Query {
        markets: vec![config::SPOT.to_string(), config::PERP.to_string()],
    };
    from_payload(&drivers::account_state(DRIVER.to_string(), to_payload(&query)).await?)
}

/// Do what `plan` says, and say whether any of it went through.
///
/// Each leg is its own submission and the second is sized from what the
/// first actually did, so a leg that misses never leaves the other on its
/// own, and a refusal stops the plan where it is: the next event reads the
/// account again. The short is levelled with the whole of the spot, an
/// order's worth at a time, before the step ends.
async fn carry_out(
    settings: &Settings,
    limits: &Limits,
    state: &AccountState,
    plan: &Plan,
) -> bool {
    let mut landed = false;
    match plan {
        Plan::Nothing => {}
        Plan::Build { fund, spot } => {
            // From the station's idle dollars, or from the vault's cash
            // through its station, into the venue account the station owns.
            // The vault holds its idle floor however much is asked for. A
            // move it refuses, one that stopped on the way, or one whose fate
            // is unknown means trading nothing until the next event says
            // where the money is.
            let home = transfers::home_chain();
            for (from, amount) in [
                (Account::Station(home), fund.from_station),
                (Account::Vault, fund.from_vault),
            ] {
                if amount > Decimal::from(0) {
                    match transfers::move_(from, venue(), millionths(amount)).await {
                        Moved::Done => landed = true,
                        // Some of it reached the station, which the next
                        // step counts and sends on.
                        Moved::Partial(_) => return true,
                        Moved::Refused(_) | Moved::Unknown(_) => return landed,
                    }
                }
            }
            let mut spot_held = state.position(&settings.spot);
            let mut perp_held = state.position(&settings.perp);
            if let Some(order) = spot {
                match place(order).await {
                    Some(size) => {
                        landed = true;
                        spot_held += size;
                    }
                    None => return landed,
                }
            }
            for _ in 0..HEDGE_ORDERS {
                let Some(order) = hedge(settings, limits, state, spot_held, perp_held) else {
                    break;
                };
                match place(&order).await {
                    Some(size) if size != Decimal::from(0) => {
                        landed = true;
                        perp_held += size;
                    }
                    _ => break,
                }
            }
        }
        Plan::Reduce { perp } => {
            let spot_held = state.position(&settings.spot);
            let mut perp_held = state.position(&settings.perp);
            if let Some(order) = perp
                && let Some(size) = place(order).await
            {
                landed = true;
                perp_held += size;
            }
            if let Some(order) = trim(settings, limits, state, spot_held, perp_held) {
                landed |= place(&order).await.is_some();
            }
        }
    }
    landed
}

/// Close everything, the short first, because a halt is an unwind with less
/// time. The order cap is lifted: the vault is stopping, and leaving a leg on
/// would cost its depositors more than a wider fill will.
async fn flatten(mind: &Mind) -> Result<(), String> {
    let limits = Limits {
        max_order_fraction: Decimal::from(1),
        ..mind.limits
    };
    let zero = Decimal::from(0);
    for _ in 0..FLATTEN_STEPS {
        let state = read_state().await?;
        if state.position(&mind.settings.spot) == zero
            && state.position(&mind.settings.perp) == zero
        {
            return Ok(());
        }
        let plan = Plan::Reduce {
            perp: unwind(&mind.settings, &limits, &state),
        };
        carry_out(&mind.settings, &limits, &state, &plan).await;
    }
    // The market would not take it inside the limits. The contract closes the
    // rest through the same reduce-only path, so stopping here is safe.
    Ok(())
}

/// Send one order, and say how much of it filled, signed as the position
/// moved: nothing if it was refused, missed the market, or went unanswered.
/// A refusal is not a reason to stop: the next event is another chance, and
/// a strategy that gives up on one refusal is a strategy that stops trading
/// the first time a market moves.
async fn place(order: &Order) -> Option<Decimal> {
    let verdicts = drivers::submit(
        DRIVER.to_string(),
        vec![to_payload(&Action::Place(order.clone()))],
    )
    .await;
    let Some(sdk::Verdict::Accepted(receipt)) = verdicts.first() else {
        return None;
    };
    let Ok(Receipt::Filled { size, side, .. }) = from_payload::<Receipt>(receipt) else {
        return None;
    };
    Some(match side {
        sdk::Side::Buy => size,
        sdk::Side::Sell => -size,
    })
}

sdk::export_agent!(FundingBasis);

#[cfg(test)]
mod tests {
    use super::{config, limits};
    use crate::decide::pair_notional;
    use strategy_sdk::decimal;

    /// An agent whose own per-order cap is below its own minimum order can
    /// never open a position, and would sit there looking healthy while doing
    /// nothing. The two numbers have to leave room for each other at the size
    /// a vault this agent is meant for actually holds.
    #[test]
    fn the_shipped_limits_can_open_a_position() {
        let minimum = decimal(config::MINIMUM_NOTIONAL);
        let smallest_vault = decimal("2000");
        let wanted = smallest_vault * decimal(config::TARGET_DEPLOYMENT);
        let step = pair_notional(wanted, smallest_vault, decimal("0"), &limits(), minimum);
        assert!(
            step > decimal("0"),
            "a {smallest_vault} vault could not open a position: a step of \
             {step} against a minimum of {minimum}"
        );
    }

    /// The claims in the manifest are the limits in the code, in words.
    #[test]
    fn the_manifest_claims_the_limits_the_code_keeps() {
        let manifest = include_str!("../shonin.toml");
        assert!(
            manifest.contains("at most twice the vault's value")
                && config::MAX_GROSS_LEVERAGE == "2"
        );
        assert!(manifest.contains("above 5% of the vault") && config::MAX_ORDER_FRACTION == "0.05");
        assert!(manifest.contains("6% of the vault kept liquid") && config::IDLE_BUFFER == "0.06");
        assert!(manifest.contains("a 10% fall") && config::DRAWDOWN_STOP == "0.10");
        assert!(manifest.contains(config::SPOT) && manifest.contains(config::PERP));
    }
}

//! The numbers this agent decides with. The claims in `shonin.toml` say the
//! same things in words.

/// The perpetual it quotes, and the size decimals the venue allows on it.
pub const MARKET: &str = "ETH";
pub const SIZE_DECIMALS: u32 = 4;
/// Cross margin at this leverage.
pub const LEVERAGE: u32 = 3;

/// Each side's distance from the mid, as a fraction of it.
pub const HALF_SPREAD: &str = "0.0008";
/// How far the quotes lean against inventory at the cap, as a fraction of
/// the mid: at full inventory long, both quotes sit this much lower.
pub const SKEW_AT_CAP: &str = "0.0010";
/// Quotes are renewed when the mid moves this far from where they were set.
pub const REQUOTE_MOVE: &str = "0.0004";
/// The venue's own cancel-everything deadline is set this far ahead of the
/// agent's clock: if the agent stops renewing it, the venue cancels every
/// quote at most this long after the last renewal.
pub const DEAD_MAN_MS: u64 = 60_000;
/// The deadline is renewed once less than this is left on it, so it is sent
/// at most about twice a minute however often the quotes move, rather than
/// with every requote: each renewal is an action the venue counts against
/// the account's request allowance.
pub const RENEW_WHEN_LEFT_MS: u64 = 30_000;
/// The venue fires a scheduled cancel at most ten times a UTC day. Once the
/// deadline has run out this many times in a day (each time the agent fell
/// silent), the agent stops quoting until the next UTC day, so it never
/// rests a quote without the venue's deadline behind it.
pub const STOP_AFTER_FIRES: u32 = 8;
// Always some of the venue's ten left over.
const _: () = assert!(STOP_AFTER_FIRES < 10);

/// Each quote at most 2% of the vault's value.
pub const QUOTE_FRACTION: &str = "0.02";
/// Inventory at most 50% of the vault's value.
pub const INVENTORY_CAP: &str = "0.50";
/// The venue refuses an order under ten dollars; below this a quote isn't
/// posted.
pub const MINIMUM_NOTIONAL: &str = "12";

//! Quotes both sides of one Hyperliquid perpetual and manages the inventory
//! it takes on.
//!
//! It reads the market's book from Shonin's shared stream and keeps one
//! resting bid and one resting ask around the mid, leaning both against its
//! inventory so fills that bring it back to flat are the likelier ones. It
//! renews its quotes only when the mid has moved far enough to matter.
//!
//! Behind the quotes stands the venue's own cancel-everything deadline,
//! renewed as the books arrive once less than half of it is left (not with
//! every requote: each renewal is an action the venue counts), so if the
//! agent stops, the venue pulls its quotes within a minute. The venue fires
//! that deadline at most ten times a UTC day; the agent counts each time it
//! ran out and, after eight in a day, pulls its quotes and stands aside until
//! the next day, so no quote of its rests without the deadline behind it.
//!
//! Its limits are in `config.rs`, where the reviewer reads them.

mod config;

use futures::StreamExt;
use hl::{AccountState, Action, Order, OrderRef, Side, Tif};
use sdk::streams::{self, HYPERLIQUID, HyperliquidFeed, HyperliquidValue};
use sdk::{Decimal, decimal, drivers, from_payload, to_payload, vault};
use strategy_sdk as sdk;
use strategy_sdk::hyperliquid as hl;

const DRIVER: &str = hl::DRIVER;
/// How many steps a halt may take to close the inventory.
const FLATTEN_STEPS: usize = 16;

struct MmQuoter;

fn zero() -> Decimal {
    Decimal::from(0)
}

fn one() -> Decimal {
    Decimal::from(1)
}

/// The quotes resting now, by the agent's own ids.
#[derive(Default)]
struct Quotes {
    bid: Option<u128>,
    ask: Option<u128>,
    /// The mid they were set around.
    mid: Option<Decimal>,
}

struct Mind {
    best_bid: Option<Decimal>,
    best_ask: Option<Decimal>,
    /// When the last book arrived, in milliseconds.
    now_ms: u64,
    quotes: Quotes,
    next_id: u128,
    levered: bool,
    dead_man: DeadMan,
}

const DAY_MS: u64 = 86_400_000;

/// The venue's cancel-everything deadline, as the agent has set it, and how
/// often it has run out today.
#[derive(Default, Debug)]
struct DeadMan {
    /// When the venue will cancel everything, unless renewed first.
    deadline_ms: Option<u64>,
    /// The UTC day the count is for, in days since 1970.
    day: u64,
    /// How many times the deadline ran out on that day.
    fired: u32,
}

impl DeadMan {
    /// Take note of the time: a deadline that has passed fired, and the
    /// venue cancelled every quote then. True if it did.
    fn observe(&mut self, now_ms: u64) -> bool {
        let fired = match self.deadline_ms {
            Some(deadline) if now_ms >= deadline => {
                self.deadline_ms = None;
                self.count(deadline / DAY_MS);
                true
            }
            _ => false,
        };
        // A new UTC day: the venue's count starts again.
        if now_ms / DAY_MS > self.day {
            self.day = now_ms / DAY_MS;
            self.fired = 0;
        }
        fired
    }

    fn count(&mut self, day: u64) {
        if day > self.day {
            self.day = day;
            self.fired = 0;
        }
        if day == self.day {
            self.fired += 1;
        }
    }

    /// Whether quotes may rest: the deadline has run out fewer times today
    /// than the agent allows itself, so the venue can still fire it.
    fn may_quote(&self) -> bool {
        self.fired < config::STOP_AFTER_FIRES
    }

    /// The deadline to renew to now, if a renewal is due: none set, or less
    /// than [`config::RENEW_WHEN_LEFT_MS`] left on it.
    fn renewal(&self, now_ms: u64) -> Option<u64> {
        self.deadline_ms
            .is_none_or(|deadline| deadline.saturating_sub(now_ms) < config::RENEW_WHEN_LEFT_MS)
            .then_some(now_ms + config::DEAD_MAN_MS)
    }

    /// The venue took a renewal to `at_ms`. One it refused leaves the
    /// deadline it had.
    fn renewed(&mut self, at_ms: u64) {
        self.deadline_ms = Some(at_ms);
    }

    /// Take the deadline off: nothing is resting.
    fn clear(&mut self) -> Action {
        self.deadline_ms = None;
        Action::CancelAllAt { at_ms: None }
    }
}

impl Mind {
    fn mid(&self) -> Option<Decimal> {
        match (self.best_bid, self.best_ask) {
            (Some(bid), Some(ask)) if bid > zero() && ask > bid => {
                Some((bid + ask) / Decimal::from(2))
            }
            _ => None,
        }
    }

    fn id(&mut self) -> u128 {
        self.next_id += 1;
        self.next_id
    }
}

enum Woke {
    Book {
        bid: Option<Decimal>,
        ask: Option<Decimal>,
        at_ms: u64,
    },
    Venue,
    Vault(vault::VaultEvent),
    Nothing,
}

impl sdk::Agent for MmQuoter {
    async fn run() -> Result<(), String> {
        let mut mind = Mind {
            best_bid: None,
            best_ask: None,
            now_ms: 0,
            quotes: Quotes::default(),
            next_id: 0,
            levered: false,
            dead_man: DeadMan::default(),
        };
        let book = streams::subscribe::<_, HyperliquidValue>(
            HYPERLIQUID,
            &HyperliquidFeed::Book {
                coin: config::MARKET.into(),
            },
        )?
        .map(|value| match value {
            Ok(stamped) => match stamped.value {
                HyperliquidValue::Book(book) => Woke::Book {
                    bid: book.bids.first().map(|level| level.price),
                    ask: book.asks.first().map(|level| level.price),
                    at_ms: stamped.received_ms,
                },
                _ => Woke::Nothing,
            },
            Err(_) => Woke::Nothing,
        });
        let account = drivers::account_events(DRIVER)
            .into_stream()
            .map(|_| Woke::Venue);
        let vault_events = vault::events().into_stream().map(Woke::Vault);
        let mut waking = futures::stream::select_all([
            book.boxed_local(),
            account.boxed_local(),
            vault_events.boxed_local(),
        ]);

        while let Some(woke) = waking.next().await {
            match woke {
                Woke::Book { bid, ask, at_ms } => {
                    mind.best_bid = bid;
                    mind.best_ask = ask;
                    mind.now_ms = at_ms;
                    // Ids carry the time, so a restarted agent never reuses
                    // one its predecessor left resting.
                    if mind.next_id == 0 {
                        mind.next_id = u128::from(at_ms) << 32;
                    }
                    if mind.dead_man.observe(at_ms) {
                        // The venue cancelled everything: nothing rests.
                        mind.quotes = Quotes::default();
                    }
                    if !mind.dead_man.may_quote() {
                        stand_aside(&mut mind).await?;
                    } else if moved_enough(&mind) {
                        requote(&mut mind).await?;
                    } else if let Some(until) = mind.dead_man.renewal(at_ms) {
                        let verdicts =
                            submit(&[Action::CancelAllAt { at_ms: Some(until) }]).await?;
                        if matches!(verdicts.first(), Some(sdk::Verdict::Accepted(_))) {
                            mind.dead_man.renewed(until);
                        }
                    }
                }
                // A fill changes the inventory: lean the quotes again.
                Woke::Venue | Woke::Vault(vault::VaultEvent::ClaimPending(_)) => {
                    if mind.mid().is_some() && mind.dead_man.may_quote() {
                        requote(&mut mind).await?;
                    }
                }
                Woke::Vault(vault::VaultEvent::BufferLow(_)) => {}
                Woke::Vault(vault::VaultEvent::Halting(_)) => {
                    flatten(&mut mind).await?;
                    return Ok(());
                }
                Woke::Nothing => {}
            }
        }
        Ok(())
    }
}

/// Whether the mid has moved far enough from where the quotes were set.
fn moved_enough(mind: &Mind) -> bool {
    let Some(mid) = mind.mid() else {
        return false;
    };
    match mind.quotes.mid {
        None => true,
        Some(quoted) => {
            let moved = if mid > quoted {
                mid - quoted
            } else {
                quoted - mid
            };
            moved / quoted >= decimal(config::REQUOTE_MOVE)
        }
    }
}

async fn read_state() -> Result<AccountState, String> {
    from_payload(&drivers::account_state(DRIVER.to_string(), Vec::new()).await?)
}

fn inventory(state: &AccountState) -> Decimal {
    state
        .positions
        .iter()
        .find(|position| position.market == config::MARKET)
        .map_or_else(zero, |position| position.size)
}

/// One side's quote: its price and size.
type Quote = Option<(Decimal, Decimal)>;

/// Where the two quotes go, and how big each is: `None` for a side that
/// would add to inventory already at its cap, or that is too small to post.
fn quotes_for(mid: Decimal, inventory: Decimal, vault_value: Decimal) -> (Quote, Quote) {
    if mid <= zero() || vault_value <= zero() {
        return (None, None);
    }
    let cap = vault_value * decimal(config::INVENTORY_CAP);
    let held = inventory * mid;
    // -1 at the cap short, +1 at the cap long.
    let mut lean = held / cap;
    if lean > one() {
        lean = one();
    }
    if lean < zero() - one() {
        lean = zero() - one();
    }
    let skew = lean * decimal(config::SKEW_AT_CAP);
    let half = decimal(config::HALF_SPREAD);
    let size = round_down(
        vault_value * decimal(config::QUOTE_FRACTION) / mid,
        config::SIZE_DECIMALS,
    );
    if size * mid < decimal(config::MINIMUM_NOTIONAL) {
        return (None, None);
    }
    let bid = (held < cap).then(|| (five_figures(mid * (one() - half - skew), Side::Buy), size));
    let ask = (held > zero() - cap)
        .then(|| (five_figures(mid * (one() + half - skew), Side::Sell), size));
    (bid, ask)
}

/// Cancel the quotes resting, push the venue's deadline back, and post new
/// ones around the mid.
async fn requote(mind: &mut Mind) -> Result<(), String> {
    let Some(mid) = mind.mid() else {
        return Ok(());
    };
    let state = read_state().await?;
    if !mind.levered {
        let verdicts = submit(&[Action::Leverage {
            market: config::MARKET.into(),
            leverage: config::LEVERAGE,
        }])
        .await?;
        mind.levered = matches!(verdicts.first(), Some(sdk::Verdict::Accepted(_)));
    }
    let mut actions = cancels(&mut mind.quotes);
    // Nothing is posted without the venue's deadline behind it, and the
    // deadline is renewed only when due.
    let renewal = mind.dead_man.renewal(mind.now_ms).map(|until| {
        actions.push(Action::CancelAllAt { at_ms: Some(until) });
        (actions.len() - 1, until)
    });
    let (bid, ask) = quotes_for(mid, inventory(&state), state.vault_value);
    if let Some((price, size)) = bid {
        let id = mind.id();
        mind.quotes.bid = Some(id);
        actions.push(Action::Place(quote(Side::Buy, price, size, id)));
    }
    if let Some((price, size)) = ask {
        let id = mind.id();
        mind.quotes.ask = Some(id);
        actions.push(Action::Place(quote(Side::Sell, price, size, id)));
    }
    mind.quotes.mid = Some(mid);
    let verdicts = submit(&actions).await?;
    if let Some((at, until)) = renewal
        && matches!(verdicts.get(at), Some(sdk::Verdict::Accepted(_)))
    {
        mind.dead_man.renewed(until);
    }
    Ok(())
}

/// Pull the quotes and take the deadline off, once: the deadline has run out
/// too often today for the venue to be relied on to fire it again.
async fn stand_aside(mind: &mut Mind) -> Result<(), String> {
    if mind.quotes.bid.is_none() && mind.quotes.ask.is_none() && mind.dead_man.deadline_ms.is_none()
    {
        return Ok(());
    }
    let mut actions = cancels(&mut mind.quotes);
    actions.push(mind.dead_man.clear());
    mind.quotes.mid = None;
    submit(&actions).await.map(|_| ())
}

/// Cancels for the quotes resting now, which are then forgotten.
fn cancels(quotes: &mut Quotes) -> Vec<Action> {
    [quotes.bid.take(), quotes.ask.take()]
        .into_iter()
        .flatten()
        .map(|id| Action::Cancel {
            market: config::MARKET.into(),
            order: OrderRef::Client(id),
        })
        .collect()
}

fn quote(side: Side, price: Decimal, size: Decimal, id: u128) -> Order {
    Order {
        market: config::MARKET.into(),
        side,
        size,
        limit_price: price,
        tif: Tif::PostOnly,
        reduce_only: false,
        client_id: Some(id),
    }
}

/// Pull the quotes and close the inventory, reduce-only, at the book.
async fn flatten(mind: &mut Mind) -> Result<(), String> {
    let mut actions = cancels(&mut mind.quotes);
    actions.push(mind.dead_man.clear());
    submit(&actions).await?;
    for _ in 0..FLATTEN_STEPS {
        let held = inventory(&read_state().await?);
        if held == zero() {
            return Ok(());
        }
        let (side, size, price) = if held > zero() {
            (Side::Sell, held, mind.best_bid)
        } else {
            (Side::Buy, zero() - held, mind.best_ask)
        };
        let Some(price) = price else {
            return Ok(());
        };
        // A wide reach: the vault is stopping, and the contract closes
        // whatever this leaves inside its own band.
        let reach = decimal("0.01");
        let limit = match side {
            Side::Sell => price * (one() - reach),
            Side::Buy => price * (one() + reach),
        };
        submit(&[Action::Place(Order {
            market: config::MARKET.into(),
            side,
            size,
            limit_price: five_figures(limit, side),
            tif: Tif::Ioc,
            reduce_only: true,
            client_id: None,
        })])
        .await?;
    }
    Ok(())
}

fn round_down(size: Decimal, decimals: u32) -> Decimal {
    let scale = Decimal::from(10u64.pow(decimals));
    (size * scale).floor() / scale
}

/// Five significant figures, the most the venue takes, rounded away from
/// the market: down for a bid, up for an ask.
fn five_figures(price: Decimal, side: Side) -> Decimal {
    if price <= zero() {
        return price;
    }
    let ten = Decimal::from(10);
    let mut scale = one();
    while price * scale < Decimal::from(10_000) {
        scale *= ten;
    }
    while price * scale >= Decimal::from(100_000) {
        scale /= ten;
    }
    let scaled = price * scale;
    let rounded = match side {
        Side::Buy => scaled.floor(),
        Side::Sell => scaled.ceil(),
    };
    rounded / scale
}

async fn submit(actions: &[Action]) -> Result<Vec<sdk::Verdict>, String> {
    let encoded: Vec<Vec<u8>> = actions.iter().map(to_payload).collect();
    Ok(drivers::submit(DRIVER.to_string(), encoded).await)
}

sdk::export_agent!(MmQuoter);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn flat_inventory_quotes_symmetrically_around_the_mid() {
        let (bid, ask) = quotes_for(decimal("2700"), zero(), decimal("10000"));
        let (bid, size) = bid.unwrap();
        let (ask, _) = ask.unwrap();
        assert!(bid < decimal("2700") && ask > decimal("2700"));
        assert_eq!(
            decimal("2700") - bid,
            ask - decimal("2700") - (ask - bid - (ask - bid))
        );
        // 2% of 10,000 at 2,700, to four decimals.
        assert_eq!(size, decimal("0.074"));
    }

    #[test]
    fn a_long_inventory_leans_both_quotes_down() {
        let (flat_bid, flat_ask) = quotes_for(decimal("2700"), zero(), decimal("10000"));
        let (long_bid, long_ask) = quotes_for(decimal("2700"), decimal("0.5"), decimal("10000"));
        assert!(long_bid.unwrap().0 < flat_bid.unwrap().0);
        assert!(long_ask.unwrap().0 < flat_ask.unwrap().0);
    }

    #[test]
    fn a_side_at_its_inventory_cap_is_not_quoted() {
        // 2 ETH at 2,700 is 5,400, past half of 10,000.
        let (bid, ask) = quotes_for(decimal("2700"), decimal("2"), decimal("10000"));
        assert!(bid.is_none(), "no more buying at the cap long");
        assert!(ask.is_some());
        let (bid, ask) = quotes_for(decimal("2700"), decimal("-2"), decimal("10000"));
        assert!(bid.is_some());
        assert!(ask.is_none(), "no more selling at the cap short");
    }

    #[test]
    fn a_vault_too_small_for_the_venues_minimum_posts_nothing() {
        assert_eq!(
            quotes_for(decimal("2700"), zero(), decimal("100")),
            (None, None)
        );
    }

    #[test]
    fn the_deadline_is_renewed_only_once_less_than_half_of_it_is_left() {
        let mut dead_man = DeadMan::default();
        let start = 1_000 * DAY_MS;
        dead_man.observe(start);
        let until = dead_man.renewal(start).expect("none set: renewed");
        dead_man.renewed(until);
        // Books every second for the next half minute renew nothing.
        for second in 1..30 {
            let now = start + second * 1_000;
            assert!(!dead_man.observe(now));
            assert!(dead_man.renewal(now).is_none(), "renewed at {second}s");
        }
        // With less than half left, it is renewed, and pushed a minute on.
        let now = start + 30_001;
        assert_eq!(dead_man.renewal(now), Some(now + config::DEAD_MAN_MS));
    }

    #[test]
    fn renewals_a_day_stay_far_below_one_per_requote() {
        // A book every 100 ms for a day.
        let mut dead_man = DeadMan::default();
        let mut renewals = 0;
        for tick in 0..(DAY_MS / 100) {
            let now = tick * 100;
            dead_man.observe(now);
            if let Some(until) = dead_man.renewal(now) {
                dead_man.renewed(until);
                renewals += 1;
            }
        }
        assert!(renewals <= 2 * 24 * 60 + 1, "{renewals}");
        assert_eq!(dead_man.fired, 0, "a renewed deadline never fires");
    }

    #[test]
    fn a_deadline_that_ran_out_is_counted_and_the_agent_stands_aside_after_eight_a_day() {
        let mut dead_man = DeadMan::default();
        let mut now = 2_000 * DAY_MS;
        for fired in 1..=config::STOP_AFTER_FIRES {
            assert!(dead_man.may_quote());
            let until = dead_man.renewal(now).unwrap();
            dead_man.renewed(until);
            // The agent falls silent past the deadline.
            now += config::DEAD_MAN_MS + 5_000;
            assert!(dead_man.observe(now), "a deadline that passed fired");
            assert_eq!(dead_man.fired, fired);
        }
        assert!(!dead_man.may_quote(), "stands aside, leaving the venue two");
        // The next UTC day it quotes again.
        let next_day = (now / DAY_MS + 1) * DAY_MS;
        assert!(!dead_man.observe(next_day));
        assert!(dead_man.may_quote());
    }

    #[test]
    fn a_deadline_cleared_never_counts_as_fired() {
        let mut dead_man = DeadMan::default();
        dead_man.renewed(dead_man.renewal(0).unwrap());
        assert_eq!(dead_man.clear(), Action::CancelAllAt { at_ms: None });
        assert!(!dead_man.observe(10 * config::DEAD_MAN_MS));
        assert_eq!(dead_man.fired, 0);
    }

    #[test]
    fn the_manifest_claims_the_limits_the_code_keeps() {
        let manifest = include_str!("../shonin.toml");
        assert!(manifest.contains("at most 50% of the vault") && config::INVENTORY_CAP == "0.50");
        assert!(manifest.contains("at most 2% of the vault") && config::QUOTE_FRACTION == "0.02");
        assert!(manifest.contains("within 60 seconds") && config::DEAD_MAN_MS == 60_000);
        assert!(manifest.contains("ten times a day") && manifest.contains("eight"));
        assert_eq!(config::STOP_AFTER_FIRES, 8);
        assert!(manifest.contains("leverage 3") && config::LEVERAGE == 3);
        assert!(manifest.contains("ETH perpetual") && config::MARKET == "ETH");
    }
}

//! The numbers this agent decides with.
//!
//! They are constants in the code rather than settings anywhere else, so the
//! reviewer reads them with the rest of the source, and the claims in
//! `shonin.toml` say the same thing in words.

/// The underlyings it trades: the stock token's symbol, the Lighter
/// perpetual's symbol, and the perpetual's market number on Lighter's
/// Robinhood Chain exchange (read from its order books).
pub const NAMES: &[(&str, &str, u32)] =
    &[("SPY", "SPY", 26), ("QQQ", "QQQ", 25), ("NVDA", "NVDA", 15)];

/// The perpetual's premium over the token (per share of the stock) at which
/// a carry is opened, and below which an open one is closed.
pub const ENTRY_PREMIUM: &str = "0.005";
pub const EXIT_PREMIUM: &str = "0.001";
/// How much of the vault to aim to have working across all names: each name
/// gets an equal part.
pub const TARGET_DEPLOYMENT: &str = "0.60";
/// Below this, an order is not worth the spread it would pay.
pub const MINIMUM_NOTIONAL: &str = "50";
/// What the short is margined with at Lighter, as a fraction of its notional:
/// well above the exchange's 2% so a weekend move doesn't liquidate it.
pub const PERP_MARGIN: &str = "0.25";
/// How far from the price seen a closing or opening order may fill.
pub const SLIPPAGE: &str = "0.01";

/// Gross exposure at most twice the vault's value.
pub const MAX_GROSS_LEVERAGE: &str = "2";
/// No single order above 5% of the vault.
pub const MAX_ORDER_FRACTION: &str = "0.05";
/// 6% of the vault kept liquid, so an ordinary withdrawal closes nothing.
pub const IDLE_BUFFER: &str = "0.06";
/// Both legs cut together after a 10% fall from the vault's peak.
pub const DRAWDOWN_STOP: &str = "0.10";

/// The weekend, in UTC: from Friday 21:00 (the cash market has closed) to
/// Monday 13:30 (it opens). Outside it, an open carry is closed.
pub const WEEKEND_FROM: (u8, u32) = (5, 21 * 3600);
pub const WEEKEND_UNTIL: (u8, u32) = (1, 13 * 3600 + 1800);

/// Steps at most this often, in seconds, however busy the books are.
pub const STEP_EVERY: u64 = 30;

//! Holds Robinhood stock tokens against Lighter perpetuals over the weekend.
//!
//! A stock token trades around the clock; the stock behind it, and the
//! channel that creates and redeems tokens against it, don't. From Friday's
//! close to Monday's open nothing pulls a token back to its stock, and the
//! perpetual on the same stock moves with the weekend's flow. When the
//! perpetual trades far enough above the token, this agent buys the token
//! and shorts the perpetual in matching shares, and carries the pair into
//! Monday, when the gap usually closes.
//!
//! The whole strategy is one long-lived program. It listens to the shared
//! Lighter books for its three stocks and to the vault's events, and at most
//! every `STEP_EVERY` seconds it works out what it would like to hold
//! (`plan.rs`) and takes one step towards it. Its limits are in `config.rs`,
//! and the manifest claims them in the same words.

mod config;
mod plan;
mod venues;

use std::collections::HashMap;

use futures::StreamExt;
use sdk::streams::{self, LIGHTER, LighterFeed, LighterValue};
use sdk::transfers::{self, Account, Moved, VenueAccount};
use sdk::{Decimal, Verdict, decimal, drivers, from_payload, millionths, to_payload, vault};
use strategy_sdk as sdk;
use venues::{lighter as lt, robinhood as rh};

use plan::{Name, Picture, Step, zero};

/// How many steps a halt may take to close everything before leaving the
/// rest to the contracts.
const FLATTEN_STEPS: usize = 64;

struct WeekendCarry;

/// What the agent remembers between steps: rebuilt from the venues whenever
/// it starts, so a restart costs a moment and nothing else.
struct Mind {
    peak: Decimal,
    /// Each perpetual's best bid and ask, by Lighter market number.
    books: HashMap<u32, (Decimal, Decimal)>,
    last_step: u64,
}

enum Woke {
    Book(u32, Decimal, Decimal),
    Vault(vault::VaultEvent),
    Nothing,
}

fn now() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|since| since.as_secs())
        .unwrap_or(0)
}

impl sdk::Agent for WeekendCarry {
    async fn run() -> Result<(), String> {
        let mut mind = Mind {
            peak: zero(),
            books: HashMap::new(),
            last_step: 0,
        };
        let mut books = Vec::new();
        for (_, _, market) in config::NAMES {
            let stream = streams::subscribe::<_, LighterValue>(
                LIGHTER,
                &LighterFeed::Book { market: *market },
            )?;
            let market = *market;
            books.push(stream.map(move |value| match value {
                Ok(stamped) => {
                    let LighterValue::Book(book) = stamped.value;
                    match (book.bids.first(), book.asks.first()) {
                        (Some(bid), Some(ask)) => Woke::Book(market, bid.price, ask.price),
                        _ => Woke::Nothing,
                    }
                }
                Err(_) => Woke::Nothing,
            }));
        }
        let books = futures::stream::select_all(books);
        let vault_events = vault::events().into_stream().map(Woke::Vault);
        let mut waking = futures::stream::select(books, vault_events);

        while let Some(woke) = waking.next().await {
            match woke {
                Woke::Book(market, bid, ask) => {
                    mind.books.insert(market, (bid, ask));
                    if now() >= mind.last_step + config::STEP_EVERY {
                        mind.last_step = now();
                        step(&mut mind).await?;
                    }
                }
                // A leaver's fraction of both legs is being closed by the
                // contracts; look again at what is left.
                Woke::Vault(vault::VaultEvent::ClaimPending(_)) => step(&mut mind).await?,
                // Leavers wait on more cash than the vault holds: bring idle
                // dollars home from the Safe, then from Lighter.
                Woke::Vault(vault::VaultEvent::BufferLow(short)) => {
                    let mut owed = short;
                    for driver in [rh::DRIVER, lt::DRIVER] {
                        if owed == 0 {
                            break;
                        }
                        if matches!(
                            transfers::move_(venue(driver), Account::Vault, owed).await,
                            Moved::Done
                        ) {
                            owed = 0;
                        }
                    }
                }
                Woke::Vault(vault::VaultEvent::Halting(_)) => {
                    flatten(&mut mind).await?;
                    return Ok(());
                }
                Woke::Nothing => {}
            }
        }
        Ok(())
    }
}

fn venue(driver: &str) -> Account {
    Account::Venue(VenueAccount {
        chain: transfers::home_chain(),
        driver: driver.to_string(),
    })
}

/// Everything the vault is worth, everywhere, in dollars.
async fn vault_value() -> Decimal {
    let total: u64 = transfers::balances()
        .await
        .iter()
        .map(|balance| balance.amount)
        .sum();
    Decimal::from(total) / Decimal::from(1_000_000u32)
}

async fn state<Q: serde::Serialize, A: serde::de::DeserializeOwned>(
    driver: &str,
    query: &Q,
) -> Result<A, String> {
    from_payload(&drivers::account_state(driver.to_string(), to_payload(query)).await?)
}

/// What the agent sees now.
async fn picture(mind: &mut Mind) -> Result<Picture, String> {
    let prices: Vec<rh::TokenPrice> = state(rh::DRIVER, &rh::Query::Prices).await?;
    let holdings: rh::AccountState = state(rh::DRIVER, &rh::Query::Holdings).await?;
    // No Lighter account before the first move to it: nothing is held there.
    let perps: Option<lt::AccountState> = state(lt::DRIVER, &lt::Query::Account).await.ok();
    let value = vault_value().await;
    if value > mind.peak {
        mind.peak = value;
    }
    let mut names = Vec::new();
    for (token, perp, market) in config::NAMES {
        let Some(price) = prices.iter().find(|p| p.token == *token) else {
            continue;
        };
        let Some((bid, ask)) = mind.books.get(market) else {
            continue;
        };
        let tokens = holdings
            .holdings
            .iter()
            .find(|h| h.token == *token)
            .map(|h| h.tokens)
            .unwrap_or_else(zero);
        let perp_position = perps
            .as_ref()
            .and_then(|state| state.positions.iter().find(|p| p.market == *perp))
            .map(|p| p.size)
            .unwrap_or_else(zero);
        names.push(Name {
            token: token.to_string(),
            perp: perp.to_string(),
            token_price: price.market_price,
            multiplier: price.multiplier,
            paused: price.paused,
            perp_bid: *bid,
            perp_ask: *ask,
            tokens,
            perp_position,
        });
    }
    Ok(Picture {
        now: now(),
        vault_value: value,
        peak: mind.peak,
        names,
    })
}

/// Look, decide, and take one step.
async fn step(mind: &mut Mind) -> Result<(), String> {
    let picture = picture(mind).await?;
    act(&picture, picture.next()).await
}

async fn act(picture: &Picture, step: Step) -> Result<(), String> {
    let slippage = decimal(config::SLIPPAGE);
    let one = Decimal::from(1u8);
    match step {
        Step::Nothing => Ok(()),
        Step::Open {
            index,
            dollars,
            tokens,
            shares,
        } => {
            let name = &picture.names[index];
            // The money has to be at each venue before it can trade there;
            // the buffer stays home, where a withdrawal reaches it.
            let margin = shares * name.perp_bid * decimal(config::PERP_MARGIN);
            if !fund(rh::DRIVER, dollars, picture.vault_value).await
                || !fund(lt::DRIVER, margin, picture.vault_value).await
            {
                return Ok(());
            }
            let bought = submit(
                rh::DRIVER,
                &rh::Action::Buy {
                    token: name.token.clone(),
                    amount: dollars,
                    min_tokens: tokens * (one - slippage),
                },
            )
            .await?;
            // No token, no short: a naked short is the one thing this
            // strategy never holds.
            if !bought {
                return Ok(());
            }
            submit(
                lt::DRIVER,
                &lt::Action::Place(lt::Order {
                    market: name.perp.clone(),
                    side: lt::Side::Sell,
                    size: shares,
                    limit_price: name.perp_bid * (one - slippage),
                    tif: lt::Tif::Ioc,
                    reduce_only: false,
                    client_id: None,
                }),
            )
            .await
            .map(|_| ())
        }
        Step::Close {
            index,
            shares,
            tokens,
        } => {
            let name = &picture.names[index];
            if shares > zero() {
                let bought_back = submit(
                    lt::DRIVER,
                    &lt::Action::Place(lt::Order {
                        market: name.perp.clone(),
                        side: lt::Side::Buy,
                        size: shares,
                        limit_price: name.perp_ask * (one + slippage),
                        tif: lt::Tif::Ioc,
                        reduce_only: true,
                        client_id: None,
                    }),
                )
                .await?;
                // The token waits for the short: the next step sees what
                // the buy-back really closed.
                if !bought_back {
                    return Ok(());
                }
            }
            if tokens > zero() {
                submit(
                    rh::DRIVER,
                    &rh::Action::Sell {
                        token: name.token.clone(),
                        tokens,
                        min_amount: tokens * name.token_price * (one - slippage),
                    },
                )
                .await?;
            }
            Ok(())
        }
    }
}

/// Make sure `driver`'s account holds `wanted` dollars, moving the shortfall
/// from the vault's cash without going below the buffer. Whether it holds
/// enough now.
async fn fund(driver: &str, wanted: Decimal, vault_value: Decimal) -> bool {
    let balances = transfers::balances().await;
    let amount_of = |wanted: &dyn Fn(&Account) -> bool| -> Decimal {
        balances
            .iter()
            .find(|b| wanted(&b.account))
            .map(|b| Decimal::from(b.amount) / Decimal::from(1_000_000u32))
            .unwrap_or_else(zero)
    };
    let there = amount_of(&|account| matches!(account, Account::Venue(v) if v.driver == driver));
    if there >= wanted {
        return true;
    }
    let cash = amount_of(&|account| matches!(account, Account::Vault));
    let keep = vault_value * decimal(config::IDLE_BUFFER);
    let spare = if cash > keep { cash - keep } else { zero() };
    let short = wanted - there;
    if spare < short {
        return false;
    }
    matches!(
        transfers::move_(Account::Vault, venue(driver), millionths(short)).await,
        Moved::Done
    )
}

/// Submit one action; whether the venue took it.
async fn submit<A: serde::Serialize>(driver: &str, action: &A) -> Result<bool, String> {
    let verdicts = drivers::submit(driver.to_string(), vec![to_payload(action)]).await;
    Ok(matches!(verdicts.first(), Some(Verdict::Accepted(_))))
}

/// Close everything, short first, because a halt is an unwind with less
/// time.
async fn flatten(mind: &mut Mind) -> Result<(), String> {
    for _ in 0..FLATTEN_STEPS {
        let mut picture = picture(mind).await?;
        // A halt closes regardless of the weekend or the premium: as if the
        // peak were far above.
        picture.peak = picture.vault_value * Decimal::from(10u8);
        match picture.next() {
            Step::Nothing => return Ok(()),
            close @ Step::Close { .. } => act(&picture, close).await?,
            Step::Open { .. } => return Ok(()),
        }
    }
    Ok(())
}

sdk::export_agent!(WeekendCarry);

//! What the agent would like to hold, worked out from what it sees: no I/O,
//! so every rule is tested here.

use strategy_sdk::{Decimal, decimal};

use crate::config;

pub fn zero() -> Decimal {
    Decimal::from(0)
}

fn abs(value: Decimal) -> Decimal {
    if value < zero() { -value } else { value }
}

/// Whether `unix_secs` falls in the weekend window: from Friday 21:00 UTC to
/// Monday 13:30 UTC.
pub fn in_weekend(unix_secs: u64) -> bool {
    let days = unix_secs / 86_400;
    // The epoch was a Thursday: 0 is Sunday, 5 is Friday.
    let weekday = ((days + 4) % 7) as u8;
    let second = (unix_secs % 86_400) as u32;
    let (from_day, from_second) = config::WEEKEND_FROM;
    let (until_day, until_second) = config::WEEKEND_UNTIL;
    match weekday {
        d if d == from_day => second >= from_second,
        6 | 0 => true,
        d if d == until_day => second < until_second,
        _ => false,
    }
}

/// One underlying, as seen now.
#[derive(Clone, Debug, PartialEq)]
pub struct Name {
    pub token: String,
    pub perp: String,
    /// The token's market price (its pool's), in dollars per token.
    pub token_price: Decimal,
    /// Shares of the stock per token.
    pub multiplier: Decimal,
    /// The issuer has paused the token's oracle: nothing is opened.
    pub paused: bool,
    /// The perpetual's best bid and ask, per share.
    pub perp_bid: Decimal,
    pub perp_ask: Decimal,
    /// Held now: tokens in the Safe, and the perpetual (negative is short).
    pub tokens: Decimal,
    pub perp_position: Decimal,
}

impl Name {
    /// What one share of the stock costs as the token.
    pub fn share_price(&self) -> Decimal {
        if self.multiplier <= zero() {
            return zero();
        }
        self.token_price / self.multiplier
    }

    /// How far the perpetual trades above the token, per share: the bid
    /// (what shorting it fetches) against the token's price.
    pub fn premium(&self) -> Decimal {
        let share = self.share_price();
        if share <= zero() || self.perp_bid <= zero() {
            return zero();
        }
        (self.perp_bid - share) / share
    }
}

/// The whole vault, as seen now.
#[derive(Clone, Debug, PartialEq)]
pub struct Picture {
    pub now: u64,
    /// Everything the vault is worth, everywhere.
    pub vault_value: Decimal,
    pub peak: Decimal,
    pub names: Vec<Name>,
}

/// One step towards what the agent would like to hold.
#[derive(Clone, Debug, PartialEq)]
pub enum Step {
    /// Buy `tokens` of the token (spending about `dollars`), then short the
    /// matching shares of the perpetual.
    Open {
        index: usize,
        dollars: Decimal,
        tokens: Decimal,
        shares: Decimal,
    },
    /// Buy back `shares` of the perpetual, then sell `tokens`: the short
    /// always goes first.
    Close {
        index: usize,
        shares: Decimal,
        tokens: Decimal,
    },
    Nothing,
}

impl Picture {
    pub fn only_reducing(&self) -> bool {
        self.peak > zero()
            && (self.peak - self.vault_value) / self.peak >= decimal(config::DRAWDOWN_STOP)
    }

    fn gross(&self) -> Decimal {
        self.names
            .iter()
            .map(|name| name.tokens * name.token_price + abs(name.perp_position) * name.perp_ask)
            .fold(zero(), |a, b| a + b)
    }

    /// The next step: a close first wherever one is due, else an opening
    /// where one is worth it, one order's worth at a time.
    pub fn next(&self) -> Step {
        let per_order = self.vault_value * decimal(config::MAX_ORDER_FRACTION);
        let weekend = in_weekend(self.now);
        let reducing = self.only_reducing();
        // Closes come first, everywhere.
        for (index, name) in self.names.iter().enumerate() {
            let carrying = name.tokens > zero() || name.perp_position < zero();
            let due = reducing || !weekend || name.premium() <= decimal(config::EXIT_PREMIUM);
            if carrying && due {
                let short = abs(name.perp_position.min(zero()));
                let per_share = name.perp_ask.max(name.share_price());
                let cap = if per_share > zero() {
                    per_order / per_share
                } else {
                    short
                };
                let shares = short.min(cap);
                // The tokens go only as far as the short already gone leaves
                // them hedged: never a naked short, never more than the
                // shares closed in this step allow.
                let left_short = short - shares;
                let tokens_hedged = if name.multiplier > zero() {
                    left_short / name.multiplier
                } else {
                    zero()
                };
                let tokens = if name.tokens > tokens_hedged {
                    name.tokens - tokens_hedged
                } else {
                    zero()
                };
                if shares > zero() || tokens > zero() {
                    return Step::Close {
                        index,
                        shares,
                        tokens,
                    };
                }
            }
        }
        if !weekend || reducing {
            return Step::Nothing;
        }
        let room = self.vault_value * decimal(config::MAX_GROSS_LEVERAGE) - self.gross();
        let per_name = self.vault_value * decimal(config::TARGET_DEPLOYMENT)
            / Decimal::from(self.names.len().max(1) as u64);
        for (index, name) in self.names.iter().enumerate() {
            if name.paused || name.premium() < decimal(config::ENTRY_PREMIUM) {
                continue;
            }
            let held = name.tokens * name.token_price;
            if held >= per_name {
                continue;
            }
            // Both legs count against the gross limit.
            let dollars = (per_name - held)
                .min(per_order)
                .min(room / Decimal::from(2u8));
            if dollars < decimal(config::MINIMUM_NOTIONAL) || name.token_price <= zero() {
                continue;
            }
            let tokens = dollars / name.token_price;
            return Step::Open {
                index,
                dollars,
                tokens,
                shares: tokens * name.multiplier,
            };
        }
        Step::Nothing
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Saturday 3 October 2026, 12:00 UTC.
    const SATURDAY: u64 = 1_791_028_800;

    fn spy(perp_bid: &str) -> Name {
        Name {
            token: "SPY".into(),
            perp: "SPY".into(),
            token_price: decimal("700"),
            multiplier: decimal("1"),
            paused: false,
            perp_bid: decimal(perp_bid),
            perp_ask: decimal(perp_bid) + decimal("0.05"),
            tokens: zero(),
            perp_position: zero(),
        }
    }

    fn picture(now: u64, names: Vec<Name>) -> Picture {
        Picture {
            now,
            vault_value: decimal("100000"),
            peak: decimal("100000"),
            names,
        }
    }

    #[test]
    fn the_weekend_runs_from_friday_evening_to_mondays_open() {
        assert!(in_weekend(SATURDAY));
        assert!(in_weekend(SATURDAY + 86_400), "Sunday");
        let friday_noon = SATURDAY - 86_400;
        assert!(!in_weekend(friday_noon));
        assert!(in_weekend(friday_noon + 9 * 3600 + 1), "Friday after 21:00");
        let monday_midnight = SATURDAY + 2 * 86_400 - 12 * 3600;
        assert!(in_weekend(monday_midnight + 13 * 3600));
        assert!(
            !in_weekend(monday_midnight + 13 * 3600 + 1800),
            "Monday's open"
        );
        assert!(!in_weekend(SATURDAY + 4 * 86_400), "Wednesday");
    }

    #[test]
    fn a_premium_over_the_entry_opens_one_orders_worth_hedged_share_for_share() {
        let step = picture(SATURDAY, vec![spy("704")]).next();
        let Step::Open {
            dollars,
            tokens,
            shares,
            ..
        } = step
        else {
            panic!("{step:?}")
        };
        assert_eq!(dollars, decimal("5000"), "one order: 5% of the vault");
        assert_eq!(shares, tokens, "a token is one share here");
    }

    #[test]
    fn nothing_opens_outside_the_weekend_below_the_entry_or_on_a_paused_oracle() {
        assert_eq!(
            picture(SATURDAY + 4 * 86_400, vec![spy("704")]).next(),
            Step::Nothing
        );
        assert_eq!(picture(SATURDAY, vec![spy("701")]).next(), Step::Nothing);
        let mut paused = spy("704");
        paused.paused = true;
        assert_eq!(picture(SATURDAY, vec![paused]).next(), Step::Nothing);
    }

    #[test]
    fn a_carry_closes_short_first_and_never_leaves_tokens_short_of_the_hedge() {
        let mut held = spy("700.2");
        held.tokens = decimal("20");
        held.perp_position = decimal("-20");
        let step = picture(SATURDAY, vec![held]).next();
        // The premium is below the exit: close, at most an order's worth.
        let Step::Close { shares, tokens, .. } = step else {
            panic!("{step:?}")
        };
        assert!(shares > zero());
        assert_eq!(tokens, shares, "only as many tokens as the short closed");
    }

    #[test]
    fn after_a_ten_percent_fall_it_only_reduces() {
        let mut held = spy("710");
        held.tokens = decimal("5");
        held.perp_position = decimal("-5");
        let mut p = picture(SATURDAY, vec![held]);
        p.vault_value = decimal("89000");
        assert!(p.only_reducing());
        assert!(matches!(p.next(), Step::Close { .. }));
    }

    #[test]
    fn mondays_open_closes_every_carry() {
        let mut held = spy("710");
        held.tokens = decimal("5");
        held.perp_position = decimal("-5");
        let monday_open = SATURDAY + 2 * 86_400 - 12 * 3600 + 14 * 3600;
        assert!(matches!(
            picture(monday_open, vec![held]).next(),
            Step::Close { .. }
        ));
    }

    #[test]
    fn gross_exposure_stays_within_twice_the_vault() {
        let mut held = spy("710");
        // Already 199k gross of a 100k vault.
        held.tokens = decimal("142");
        held.perp_position = decimal("-142");
        held.token_price = decimal("700");
        let mut other = spy("710");
        other.token = "QQQ".into();
        let step = picture(SATURDAY, vec![held, other]).next();
        assert_eq!(step, Step::Nothing, "{step:?}");
    }
}

//! What this agent says to its two drivers, and hears back: the
//! `robinhood` driver's payloads (stock tokens in the station's Safe) and
//! the `lighter` driver's (the station's Lighter account).
//!
//! These are the drivers' own published payload types, copied verbatim (the
//! same names, fields and serde attributes, so they encode to the same
//! canonical CBOR). They move to the SDK beside Hyperliquid's; this file then
//! becomes two `use` lines.

#![allow(dead_code)]

pub mod robinhood {
    use serde::{Deserialize, Serialize};
    pub use strategy_sdk::Decimal;

    /// The driver's name, as `shonin.toml` writes it.
    pub const DRIVER: &str = "robinhood";

    /// The dollar's symbol: USDG, the chain's native dollar.
    pub const DOLLAR: &str = "USDG";

    /// What a strategy submits.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Action {
        /// Spend `amount` of the dollar on stock token `token`, receiving at
        /// least `min_tokens`.
        Buy {
            token: String,
            amount: Decimal,
            min_tokens: Decimal,
        },
        /// Sell `tokens` of stock token `token` for at least `min_amount`
        /// dollars.
        Sell {
            token: String,
            tokens: Decimal,
            min_amount: Decimal,
        },
    }

    /// What came back inside an accepted verdict.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Receipt {
        /// The swap landed: what was spent and what came back.
        Swapped {
            token: String,
            spent: Decimal,
            received: Decimal,
            transaction: String,
        },
    }

    /// What `account-state` is asked.
    #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Query {
        /// The Safe's holdings, priced.
        Holdings,
        /// Every listed token's prices: its feed's and its pool's.
        Prices,
    }

    /// One listed token's prices, as `Query::Prices` answers.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct TokenPrice {
        pub token: String,
        /// Chainlink's price for the token (the multiplier already applied).
        pub feed_price: Decimal,
        /// When the feed last moved, in seconds since the Unix epoch.
        pub feed_updated_at: u64,
        /// What the token's pool says, averaged over the driver's window.
        pub market_price: Decimal,
        /// Shares of the underlying per token.
        pub multiplier: Decimal,
        /// The issuer has paused the token's oracle.
        pub paused: bool,
    }

    /// One stock token the Safe holds.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct Holding {
        pub token: String,
        /// In shares of the token (its own units, not multiplied: the
        /// multiplier only matters for what a share is a claim on).
        pub tokens: Decimal,
        /// The token's Chainlink price, which already applies the multiplier.
        pub feed_price: Decimal,
        /// When the feed last moved, in seconds since the Unix epoch.
        pub feed_updated_at: u64,
        /// Shares of the underlying per token, from the token's multiplier:
        /// for display, never for valuing.
        pub multiplier: Decimal,
    }

    /// What `account-state` answers.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct AccountState {
        /// The Safe's address.
        pub safe: String,
        /// Idle dollars in the Safe.
        pub dollars: Decimal,
        pub holdings: Vec<Holding>,
    }

    /// Something that happened to the Safe, read from the chain.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum AccountEvent {
        /// Tokens moved into or out of the Safe: a swap, a deposit, a close.
        Moved {
            token: String,
            /// Positive when the Safe received.
            amount: Decimal,
            transaction: String,
            block: u64,
        },
    }
}

pub mod lighter {
    use serde::{Deserialize, Serialize};
    pub use strategy_sdk::Decimal;

    /// The driver's name, as `shonin.toml` writes it.
    pub const DRIVER: &str = "lighter";

    #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Side {
        Buy,
        Sell,
    }

    /// How long an order stands.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Tif {
        /// Added to the book only, never taking.
        PostOnly,
        /// Stands until `expiry_ms` (Lighter allows up to 28 days) or a cancel.
        GoodTill { expiry_ms: u64 },
        /// Immediate or cancel, at the limit price or better.
        Ioc,
    }

    /// An order on one perp market, by its symbol (`SPY`, `NVDA`).
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct Order {
        pub market: String,
        pub side: Side,
        /// In units of the underlying (shares, coins).
        pub size: Decimal,
        pub limit_price: Decimal,
        pub tif: Tif,
        /// Only ever shrinks a position, never past flat.
        pub reduce_only: bool,
        /// The agent's own id for the order (1 to 2^48 - 1), so it can cancel it
        /// before it knows the venue's.
        pub client_id: Option<u64>,
    }

    /// Which order: the venue's index, or the agent's own id.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum OrderRef {
        Venue(u64),
        Client(u64),
    }

    /// What a strategy submits.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Action {
        Place(Order),
        Cancel {
            market: String,
            order: OrderRef,
        },
        /// Change a resting order's size and price.
        Modify {
            market: String,
            order: OrderRef,
            size: Decimal,
            limit_price: Decimal,
        },
        /// Cancel every resting order on the account.
        CancelAll,
    }

    /// What came back inside an accepted verdict.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Receipt {
        /// The exchange took the transaction; what it did with it arrives as
        /// account events.
        Sent { tx_hash: String },
    }

    /// What `account-state` is asked.
    #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum Query {
        Account,
    }

    /// One perp position.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct Position {
        pub market: String,
        /// Positive is long.
        pub size: Decimal,
        pub entry_price: Decimal,
        pub unrealized_pnl: Decimal,
    }

    /// What `account-state` answers: the station's master account.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct AccountState {
        pub account_index: u64,
        /// The account's worth at the mark.
        pub equity: Decimal,
        /// What it could withdraw or put up as margin now.
        pub available: Decimal,
        pub positions: Vec<Position>,
    }

    /// Something that happened to the account, as the venue reported it.
    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    #[serde(rename_all = "kebab-case")]
    pub enum AccountEvent {
        Filled {
            market: String,
            side: Side,
            size: Decimal,
            price: Decimal,
            time_ms: u64,
        },
        Order {
            market: String,
            order_index: u64,
            client_id: Option<u64>,
            status: String,
            time_ms: u64,
        },
        Funding {
            market: String,
            /// Positive when the account was paid.
            amount: Decimal,
            time_ms: u64,
        },
    }
}
